# ─── App ───
@asynccontextmanager
async def lifespan(app: FastAPI):
    import asyncio
    # Retry DB init — MySQL may not be fully ready even after healthcheck passes
    for attempt in range(1, 6):
        try:
            init_db()
            break
        except Exception as e:
            if attempt < 5:
                print(f"DB init attempt {attempt} failed: {e} — retrying in {attempt * 2}s")
                await asyncio.sleep(attempt * 2)
            else:
                print(f"DB init gave up after {attempt} attempts: {e}")
    yield


app = FastAPI(title="PickForMe API", lifespan=lifespan, default_response_class=UTF8JSONResponse)

