@app.middleware("http")
async def head_method_support(request: Request, call_next):
    """Allow HEAD requests on any GET-only route.

    Many uptime monitors (UptimeRobot, Pingdom, StatusCake), GitHub link
    previews and several crawlers issue HEAD before GET. FastAPI's default
    routing rejects HEAD on routes registered as @app.get(...), returning
    405 Method Not Allowed. We re-dispatch HEAD as GET internally, then
    return the same status/headers with an empty body.
    """
    if request.method == "HEAD":
        request.scope["method"] = "GET"
        response = await call_next(request)
        # Drain the response body iterator so the upstream handler completes
        # cleanly, but return a body-less Response with the same metadata.
        body_iterator = getattr(response, "body_iterator", None)
        if body_iterator is not None:
            try:
                async for _chunk in body_iterator:
                    pass
            except Exception:
                pass
        headers = dict(response.headers)
        headers.pop("content-length", None)
        return Response(status_code=response.status_code, headers=headers)
    return await call_next(request)


@app.middleware("http")
async def security_headers_middleware(request: Request, call_next):
    response = await call_next(request)
    response.headers["X-Content-Type-Options"] = "nosniff"
    response.headers["X-Frame-Options"] = "SAMEORIGIN"
    response.headers["Referrer-Policy"] = "strict-origin-when-cross-origin"
    response.headers["Permissions-Policy"] = "camera=(), microphone=(), geolocation=()"
    response.headers["X-XSS-Protection"] = "1; mode=block"
    response.headers["Cross-Origin-Opener-Policy"] = "same-origin-allow-popups"
    response.headers["X-Permitted-Cross-Domain-Policies"] = "none"
    response.headers["Content-Security-Policy"] = (
        "default-src 'self'; "
        "script-src 'self' 'unsafe-inline' https://fonts.googleapis.com https://accounts.google.com https://apis.google.com; "
        "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com https://accounts.google.com; "
        "font-src 'self' https://fonts.gstatic.com; "
        "img-src 'self' data: https://image.tmdb.org https://books.google.com https://*.googleapis.com https://*.googleusercontent.com blob:; "
        "connect-src 'self' https://api.groq.com https://api.openai.com "
        "https://fonts.googleapis.com https://fonts.gstatic.com "
        "https://image.tmdb.org https://api.themoviedb.org "
        "https://www.googleapis.com https://books.google.com "
        "https://accounts.google.com; "
        "frame-src 'self' https://www.youtube.com https://youtube.com https://accounts.google.com; "
        "worker-src 'self'; "
        "manifest-src 'self'; "
        "object-src 'none'; base-uri 'self'; "
        "form-action 'self'"
    )
    return response


@app.middleware("http")
async def maintenance_middleware(request: Request, call_next):
    path = request.url.path
    if path.startswith(("/admin", "/api/admin", "/css", "/js", "/favicon", "/api/auth", "/api/settings")):
        return await call_next(request)
    settings = get_site_settings()
    if settings.get("maintenance_mode"):
        if path.startswith("/api/"):
            return JSONResponse({"detail": settings.get("maintenance_text") or "Maintenance mode"}, status_code=503)
        text = html.escape(settings.get("maintenance_text") or "Picksy оновлюється")
        return HTMLResponse(f"""<!doctype html><html lang='uk'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Picksy Maintenance</title><style>body{{margin:0;min-height:100vh;display:grid;place-items:center;background:#060614;color:#fff;font-family:Inter,Arial,sans-serif}}.box{{max-width:520px;margin:20px;padding:34px;border:1px solid rgba(255,255,255,.12);border-radius:24px;background:rgba(255,255,255,.06);box-shadow:0 24px 80px rgba(0,0,0,.45);text-align:center}}h1{{font-size:2rem;margin:0 0 12px;background:linear-gradient(135deg,#8b5cf6,#ec4899,#06d6a0);-webkit-background-clip:text;-webkit-text-fill-color:transparent}}p{{color:rgba(255,255,255,.72);line-height:1.6}}</style></head><body><div class='box'><h1>Picksy оновлюється</h1><p>{text}</p></div></body></html>""", status_code=503)
    return await call_next(request)


# ─── Rate Limiter ───
import time as _time
from collections import defaultdict


class RateLimiter:
    """Simple in-memory sliding-window rate limiter per IP."""

    def __init__(self, max_requests: int = 10, window_seconds: int = 60):
        self.max_requests = max_requests
        self.window = window_seconds
        self._hits: dict[str, list[float]] = defaultdict(list)

    def is_allowed(self, key: str) -> bool:
        now = _time.time()
        cutoff = now - self.window
        hits = self._hits[key]
        self._hits[key] = [t for t in hits if t > cutoff]
        if len(self._hits[key]) >= self.max_requests:
            return False
        self._hits[key].append(now)
        return True

    def cleanup(self):
        """Remove expired entries to prevent memory leaks."""
        now = _time.time()
        expired_keys = [k for k, v in self._hits.items() if not v or v[-1] < now - self.window * 2]
        for k in expired_keys:
            del self._hits[k]


# Bumped from 15/min to 60/min so mobile users with chatty AI prompts
# don't get 429-blocked when scrolling/refreshing.
ai_rate_limiter = RateLimiter(max_requests=60, window_seconds=60)
auth_rate_limiter = RateLimiter(max_requests=30, window_seconds=60)


def _get_client_ip(request: Request) -> str:
    forwarded = request.headers.get("x-forwarded-for")
    if forwarded:
        return forwarded.split(",")[0].strip()
    return request.client.host if request.client else "unknown"


# ─── CSRF Token ───
_csrf_tokens: dict[str, float] = {}


def _generate_csrf_token() -> str:
    token = secrets.token_urlsafe(32)
    _csrf_tokens[token] = _time.time()
    # Cleanup old tokens (older than 2 hours)
    cutoff = _time.time() - 7200
    expired = [k for k, v in _csrf_tokens.items() if v < cutoff]
    for k in expired:
        del _csrf_tokens[k]
    return token


def _validate_csrf_token(token: str) -> bool:
    if not token:
        return False
    if token in _csrf_tokens:
        age = _time.time() - _csrf_tokens[token]
        return age < 7200  # valid for 2 hours
    return False


