# Progressive level thresholds — level n unlocks at LEVEL_THRESHOLDS[n-1] picks.
LEVEL_THRESHOLDS = [0, 10, 30, 75, 150, 300, 600, 1000, 1750, 3000]
LEVEL_NAMES_UK = [
    "Новачок", "Глядач", "Кіноман", "Знавець", "Експерт",
    "Майстер", "Гуру", "Легенда", "Міфологія", "Безсмертний",
]
LEVEL_NAMES_EN = [
    "Newbie", "Viewer", "Buff", "Connoisseur", "Expert",
    "Master", "Guru", "Legend", "Mythic", "Immortal",
]


def compute_level(total_picks: int):
    """Return dict with level, level_name (uk/en), threshold, next_threshold, progress (0..1)."""
    level = 1
    for i, thr in enumerate(LEVEL_THRESHOLDS):
        if total_picks >= thr:
            level = i + 1
        else:
            break
    cur_thr = LEVEL_THRESHOLDS[level - 1]
    if level < len(LEVEL_THRESHOLDS):
        next_thr = LEVEL_THRESHOLDS[level]
        progress = (total_picks - cur_thr) / max(1, next_thr - cur_thr)
    else:
        next_thr = None
        progress = 1.0
    return {
        "level": level,
        "name_uk": LEVEL_NAMES_UK[min(level - 1, len(LEVEL_NAMES_UK) - 1)],
        "name_en": LEVEL_NAMES_EN[min(level - 1, len(LEVEL_NAMES_EN) - 1)],
        "current_threshold": cur_thr,
        "next_threshold": next_thr,
        "to_next": (next_thr - total_picks) if next_thr is not None else 0,
        "progress": round(progress, 4),
    }


