# ─── Social handle / URL normalization ───
_SOCIAL_HOSTS = {
    "telegram":  ("t.me", "telegram.me", "telegram.dog"),
    "instagram": ("instagram.com", "www.instagram.com", "instagr.am"),
    "letterboxd": ("letterboxd.com", "www.letterboxd.com"),
}


def _normalize_social_handle(raw: Optional[str], platform: str) -> Optional[str]:
    """Accepts a full URL, ``@handle`` or bare ``handle`` and returns just the
    handle (no leading ``@``). Examples::

        https://t.me/foo         -> foo
        t.me/foo                 -> foo
        @foo                     -> foo
        foo                      -> foo
        https://instagram.com/foo/?hl=en -> foo
    """
    s = (raw or "").strip()
    if not s:
        return None
    s = s.lstrip("@")
    if "://" in s or s.startswith("www.") or any(h in s.lower() for h in _SOCIAL_HOSTS.get(platform, ())):
        # Strip protocol + host, keep first path segment as handle
        try:
            s_low = s.lower()
            if "://" in s_low:
                s = s.split("://", 1)[1]
            if "/" in s:
                host, _, rest = s.partition("/")
                handle = rest.split("/", 1)[0].split("?", 1)[0].split("#", 1)[0]
                handle = handle.strip("/").lstrip("@")
                if handle:
                    s = handle
        except Exception:
            pass
    s = s.strip().strip("/").lstrip("@")
    s = s.split("?", 1)[0].split("#", 1)[0]
    return s[:120] or None


def _normalize_website_url(raw: Optional[str]) -> Optional[str]:
    """Accepts a URL with or without scheme; ensures it has http(s):// prefix."""
    s = (raw or "").strip()
    if not s:
        return None
    if not (s.startswith("http://") or s.startswith("https://")):
        s = "https://" + s
    return s[:250]


async def _backfill_missing_genres(user_id: int, limit: int = 30) -> None:
    """Best-effort: for the user's saved items missing `genres`, fetch from TMDB
    and write them back. Quietly no-ops if TMDB key is missing or tables lack
    the column."""
    if not TMDB_API_KEY:
        return
    try:
        conn = get_db()
        try:
            with conn.cursor() as cur:
                for table, mtype in (("saved_movies", "movie"), ("saved_tv", "tv")):
                    try:
                        cur.execute(
                            f"SELECT tmdb_id FROM {table} "
                            f"WHERE user_id=%s AND (genres IS NULL OR genres='') "
                            f"ORDER BY id DESC LIMIT %s",
                            (user_id, limit),
                        )
                    except Exception:
                        continue
                    rows = cur.fetchall() or []
                    for r in rows:
                        tid = r.get("tmdb_id") if isinstance(r, dict) else (r[0] if r else None)
                        if not tid:
                            continue
                        g = await _fetch_tmdb_genres(mtype, int(tid))
                        if g:
                            try:
                                cur.execute(
                                    f"UPDATE {table} SET genres=%s WHERE user_id=%s AND tmdb_id=%s",
                                    (g, user_id, int(tid)),
                                )
                            except Exception:
                                pass
                conn.commit()
        finally:
            conn.close()
    except Exception:
        pass


