@app.get("/api/movies/{movie_id}/details")
async def movie_details(movie_id: int, lang: str = "uk"):
    if not TMDB_API_KEY:
        raise HTTPException(status_code=503, detail="TMDB API key not configured")
    language = "uk-UA" if lang == "uk" else "en-US"
    try:
        async with httpx.AsyncClient(timeout=15) as client:
            detail_resp, credits_resp, videos_resp, similar_resp, reviews_resp = await _gather_tmdb(
                client, "movie", movie_id, language
            )
        return _build_detail_response(detail_resp, credits_resp, videos_resp, similar_resp, reviews_resp, "movie", movie_id)
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


