def _get_community_rating(content_type: str, content_id: str) -> dict:
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute(
                "SELECT AVG(rating) as avg_rating, COUNT(*) as count FROM community_ratings WHERE content_type=%s AND content_id=%s",
                (content_type, content_id),
            )
            row = cur.fetchone()
        conn.close()
        avg = round(float(row["avg_rating"]), 1) if row and row["avg_rating"] else 0
        count = int(row["count"]) if row else 0
        return {"average": avg, "count": count}
    except Exception:
        return {"average": 0, "count": 0}


