@app.get("/api/reviews/{content_type}/{content_id}")
async def get_reviews(content_type: str, content_id: str, limit: int = 20, offset: int = 0):
    if content_type not in ("movie", "tv", "book"):
        raise HTTPException(status_code=400, detail="Invalid type")
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute(
                "SELECT r.review_text, r.rating, r.created_at, u.username, u.display_name, u.avatar_emoji "
                "FROM user_reviews r JOIN users u ON r.user_id = u.id "
                "WHERE r.content_type=%s AND r.content_id=%s "
                "ORDER BY r.created_at DESC LIMIT %s OFFSET %s",
                (content_type, content_id, limit, offset),
            )
            reviews = cur.fetchall() or []
            cur.execute(
                "SELECT COUNT(*) as total FROM user_reviews WHERE content_type=%s AND content_id=%s",
                (content_type, content_id),
            )
            total = cur.fetchone()["total"]
        conn.close()
        return {
            "reviews": [
                {
                    "text": r["review_text"],
                    "rating": r["rating"],
                    "created_at": str(r["created_at"]),
                    "username": r["display_name"] or r["username"] or "User",
                    "avatar": r["avatar_emoji"] or "👤",
                }
                for r in reviews
            ],
            "total": total,
        }
    except Exception:
        return {"reviews": [], "total": 0}


