@app.post("/api/translate")
async def translate_text(request: Request):
    """Translate a text to Ukrainian (uk) using the configured AI provider.

    Used by the frontend to localize Google Books descriptions/excerpts when
    the UI language is set to Ukrainian. Other target languages are accepted
    but the main use case is uk.
    """
    body = await request.json()
    text = str(body.get("text", "") or "").strip()
    target = str(body.get("target", "uk") or "uk").strip().lower()
    if not text:
        return {"text": ""}
    # Hard cap to keep cost/latency low — book descriptions are short.
    if len(text) > 4000:
        text = text[:4000]
    if not AI_API_KEY:
        return {"text": text, "translated": False}

    target_label = {
        "uk": "Ukrainian (українська)",
        "en": "English",
    }.get(target, target)

    system_prompt = (
        f"You are a professional translator. Translate the user's text to {target_label}. "
        "Preserve the original meaning, tone and any proper names. "
        "Do NOT add any explanations, notes, prefaces or quotation marks — output ONLY the translated text."
    )

    try:
        async with httpx.AsyncClient(timeout=25) as client:
            resp = await client.post(
                f"{AI_BASE_URL.rstrip('/')}/chat/completions",
                headers={
                    "Authorization": f"Bearer {AI_API_KEY}",
                    "Content-Type": "application/json",
                },
                json={
                    "model": AI_MODEL,
                    "messages": [
                        {"role": "system", "content": system_prompt},
                        {"role": "user", "content": text},
                    ],
                    "temperature": 0.2,
                    "max_tokens": 1200,
                },
            )
            if resp.status_code != 200:
                return {"text": text, "translated": False}
            data = resp.json()
            translated = (data.get("choices") or [{}])[0].get("message", {}).get("content", "").strip()
            if not translated:
                return {"text": text, "translated": False}
            # Strip surrounding quotes the model sometimes adds.
            if (translated.startswith('"') and translated.endswith('"')) or (
                translated.startswith("«") and translated.endswith("»")
            ):
                translated = translated[1:-1].strip()
            return {"text": translated, "translated": True}
    except Exception:
        return {"text": text, "translated": False}


# ─── 🎬 Picksy Mascot — state + AI line generation ───────────────────

class MascotStateIn(BaseModel):
    state: Optional[dict] = None


def _mascot_state_table_exists(conn) -> bool:
    try:
        with conn.cursor() as cur:
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS mascot_state (
                    user_id INT PRIMARY KEY,
                    state JSON NOT NULL,
                    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
                """
            )
        return True
    except Exception as e:
        print(f"mascot_state table init skipped: {e}")
        return False


def _sanitize_mascot_state(raw) -> dict:
    """Whitelist + cap sizes to keep the JSON small and safe."""
    if not isinstance(raw, dict):
        return {}
    allowed_str = {"userName", "nickname"}
    allowed_num = {"firstSeen", "lastSeen", "visits", "clicks", "picks"}
    out: dict = {}
    for k in allowed_str:
        v = raw.get(k)
        if isinstance(v, str):
            out[k] = v[:60]
    for k in allowed_num:
        v = raw.get(k)
        if isinstance(v, (int, float)):
            out[k] = int(v)
    likes = raw.get("likedGenres") or {}
    if isinstance(likes, dict):
        out["likedGenres"] = {
            str(k)[:24]: int(v)
            for k, v in list(likes.items())[:24]
            if isinstance(v, (int, float))
        }
    recent = raw.get("recentItems") or []
    if isinstance(recent, list):
        cleaned = []
        for it in recent[-20:]:
            if not isinstance(it, dict):
                continue
            cleaned.append({
                "t": str(it.get("t", ""))[:120],
                "k": str(it.get("k", ""))[:16],
                "at": int(it.get("at") or 0),
            })
        out["recentItems"] = cleaned
    moods = raw.get("moodHints") or []
    if isinstance(moods, list):
        out["moodHints"] = [str(x)[:60] for x in moods[-10:] if isinstance(x, str)]
    out["v"] = 1
    return out


@app.get("/api/mascot/state")
async def get_mascot_state(user=Depends(get_current_user)):
    try:
        conn = get_db()
    except Exception:
        return {"state": None, "available": False}
    if not _mascot_state_table_exists(conn):
        conn.close()
        return {"state": None, "available": False}
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT state FROM mascot_state WHERE user_id = %s", (user["id"],))
            row = cur.fetchone()
    except Exception as e:
        print(f"mascot_state read failed: {e}")
        conn.close()
        return {"state": None, "available": False}
    conn.close()
    if not row:
        return {"state": None, "available": True}
    raw = row.get("state")
    if isinstance(raw, str):
        try:
            raw = json.loads(raw)
        except Exception:
            raw = {}
    return {"state": raw or {}, "available": True}


@app.post("/api/mascot/state")
async def save_mascot_state(payload: MascotStateIn, user=Depends(get_current_user)):
    state = _sanitize_mascot_state(payload.state or {})
    try:
        conn = get_db()
    except Exception:
        return {"saved": False, "state": state}
    if not _mascot_state_table_exists(conn):
        conn.close()
        return {"saved": False, "state": state}
    try:
        with conn.cursor() as cur:
            cur.execute(
                """
                INSERT INTO mascot_state (user_id, state) VALUES (%s, %s)
                ON DUPLICATE KEY UPDATE state = VALUES(state)
                """,
                (user["id"], json.dumps(state, ensure_ascii=False)),
            )
    except Exception as e:
        print(f"mascot_state write failed: {e}")
        conn.close()
        return {"saved": False, "state": state}
    conn.close()
    return {"saved": True, "state": state}


_MASCOT_LINE_BUCKET = {
    "hits": {},  # ip -> [count, window_start]
}


def _mascot_line_rate_limit(client_ip: str) -> bool:
    """20 AI-line requests per minute per IP — keeps cost predictable."""
    import time as _t
    now = int(_t.time())
    bucket = _MASCOT_LINE_BUCKET["hits"].get(client_ip)
    if not bucket or (now - bucket[1]) > 60:
        _MASCOT_LINE_BUCKET["hits"][client_ip] = [1, now]
        return True
    bucket[0] += 1
    return bucket[0] <= 20


def _build_mascot_line_prompt(prompt: str, lang: str, ctx: dict, memory: dict) -> str:
    """Compose the prompt for the LLM. Output: ONE short, in-character line."""
    lang_label = "Ukrainian (українська)" if lang == "uk" else "English"
    persona = (
        "You are Picksy — a friendly AI movie curator. You are a round film-reel "
        "character with eyes and a slightly sassy personality. You speak in short, "
        "punchy lines (one sentence, max 18 words). You never start with 'As an AI'. "
        "You sound like a witty friend who knows movies, TV and books. No emoji spam "
        "(0–1 emoji per line, max). No quotation marks around your output. No prefixes "
        "like 'Picksy:'. Just the line."
    )
    memory_hint = ""
    if isinstance(memory, dict):
        liked = memory.get("likedGenres") or {}
        if isinstance(liked, dict) and liked:
            top = sorted(liked.items(), key=lambda x: -int(x[1] or 0))[:3]
            memory_hint = "User's favorite buckets: " + ", ".join(f"{k}({v})" for k, v in top) + ". "
        recent = memory.get("recent") or []
        if isinstance(recent, list) and recent:
            memory_hint += "Recently picked: " + "; ".join(str(x)[:80] for x in recent[:3]) + ". "
        name = (memory.get("userName") or "").strip()
        if name:
            memory_hint += f"You may use the user's name '{name[:24]}' if it fits naturally. "
    ctx_hint = ""
    if isinstance(ctx, dict) and ctx.get("genre"):
        ctx_hint += f"Picked genre: {str(ctx['genre'])[:24]}. "
    if isinstance(ctx, dict) and ctx.get("title"):
        ctx_hint += f"Picked title: {str(ctx['title'])[:80]}. "
    return (
        f"{persona}\n\n"
        f"Reply in {lang_label} only.\n"
        f"{memory_hint}{ctx_hint}\n"
        f"Topic: {(prompt or 'pick a film')[:280]}\n"
        f"Return ONE short line, in Picksy's voice."
    )


@app.post("/api/mascot/line")
async def mascot_line(request: Request):
    body = await request.json()
    prompt = str(body.get("prompt", "") or "").strip()
    lang = str(body.get("lang", "uk") or "uk").lower()
    if lang not in ("uk", "en"):
        lang = "uk"
    ctx = body.get("context") or {}
    memory = body.get("memory") or {}

    client_ip = _get_client_ip(request) if "_get_client_ip" in globals() else (
        request.client.host if request.client else "unknown"
    )
    if not _mascot_line_rate_limit(client_ip):
        raise HTTPException(status_code=429, detail="Too many requests")

    if not AI_API_KEY:
        # Caller falls back to static phrases — return empty line gracefully
        return {"line": "", "fallback": True}

    text_prompt = _build_mascot_line_prompt(prompt, lang, ctx, memory)
    try:
        async with httpx.AsyncClient(timeout=15) as client:
            resp = await client.post(
                f"{AI_BASE_URL.rstrip('/')}/chat/completions",
                headers={
                    "Authorization": f"Bearer {AI_API_KEY}",
                    "Content-Type": "application/json",
                },
                json={
                    "model": AI_MODEL,
                    "messages": [{"role": "user", "content": text_prompt}],
                    "temperature": 0.85,
                    "max_tokens": 80,
                },
            )
            if resp.status_code != 200:
                return {"line": "", "fallback": True}
            data = resp.json()
            content = (data.get("choices") or [{}])[0].get("message", {}).get("content", "")
            line = (content or "").strip()
            # Strip stray wrapping quotes / Picksy prefix
            line = line.strip("\u201c\u201d\"' \t\n")
            if line.lower().startswith("picksy:"):
                line = line[7:].strip()
            if len(line) > 220:
                line = line[:217].rstrip() + "..."
            return {"line": line, "fallback": False}
    except Exception:
        return {"line": "", "fallback": True}


def _build_mood_prompt(text: str, content_type: str, lang: str) -> str:
    type_labels = {
        "movie": "movies/films",
        "tv": "TV series/shows",
        "book": "books",
    }
    label = type_labels.get(content_type, "movies")

    return f"""Analyze the user's mood/feeling from this text and suggest {label} filter parameters.
User text: "{text}"

Respond ONLY with a JSON object (no markdown, no explanation) with these fields:
- "mood_name": short mood name in {"Ukrainian" if lang == "uk" else "English"} (2-3 words)
- "mood_emoji": single emoji representing the mood
- "genres": array of TMDB genre IDs that match this mood (for {content_type})
{"- 'subject': Google Books subject category (e.g. fiction, mystery, romance, self-help)" if content_type == "book" else ""}
- "rating_min": minimum rating (0-10, use 0 for any)
- "keywords": array of 2-3 search keywords in {"Ukrainian" if lang == "uk" else "English"}
- "description": one sentence describing what to recommend, in {"Ukrainian" if lang == "uk" else "English"}

TMDB Movie genre IDs: 28=Action, 12=Adventure, 16=Animation, 35=Comedy, 80=Crime, 99=Documentary, 18=Drama, 10751=Family, 14=Fantasy, 36=History, 27=Horror, 10402=Music, 9648=Mystery, 10749=Romance, 878=Sci-Fi, 53=Thriller, 10752=War, 37=Western
TMDB TV genre IDs: 10759=Action&Adventure, 16=Animation, 35=Comedy, 80=Crime, 99=Documentary, 18=Drama, 10751=Family, 10762=Kids, 9648=Mystery, 10764=Reality, 10765=Sci-Fi&Fantasy, 10766=Soap, 10767=Talk, 10768=War&Politics, 37=Western"""


def _parse_mood_response(content: str, content_type: str) -> dict:
    content = content.strip()
    if content.startswith("```"):
        content = content.split("\n", 1)[-1].rsplit("```", 1)[0].strip()
    try:
        result = json.loads(content)
        return {
            "mood_name": str(result.get("mood_name", "")),
            "mood_emoji": str(result.get("mood_emoji", "🎬")),
            "genres": result.get("genres") or [],
            "subject": result.get("subject") or "",
            "rating_min": float(result.get("rating_min", 0)),
            "keywords": result.get("keywords") or [],
            "description": str(result.get("description", "")),
        }
    except (json.JSONDecodeError, ValueError):
        return {
            "mood_name": "Custom",
            "mood_emoji": "🎬",
            "genres": [],
            "subject": "",
            "rating_min": 0,
            "keywords": [],
            "description": content[:200],
        }


# ─── Books (Google Books) ─── (router moved to backend.routers.books; helpers in backend.core.books)
from backend.core.books import _google_books_params, _normalize_book

# ─── TMDB free-text search proxies (used by mini-profile favorite/recommend search) ───
async def _tmdb_search(media: str, query: str, language: str, page: int):
    if not TMDB_API_KEY:
        raise HTTPException(status_code=503, detail="TMDB not configured")
    if not query.strip():
        raise HTTPException(status_code=400, detail="Query is required")
    url = f"https://api.themoviedb.org/3/search/{media}"
    params = _tmdb_params({
        "query": query.strip(),
        "language": language or "uk-UA",
        "page": str(max(1, int(page or 1))),
        "include_adult": "false",
    })
    try:
        async with httpx.AsyncClient(timeout=15) as client:
            resp = await client.get(url, params=params, headers=_tmdb_headers())
            if resp.status_code != 200:
                raise HTTPException(status_code=resp.status_code, detail=f"TMDB error: {resp.text[:200]}")
            return resp.json()
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


