def _get_user_personalization(user_id: int, content_type: str) -> dict:
    """Fetch user history from DB to personalize AI recommendations."""
    result = {
        "last_saved": [],
        "favorite_genres": [],
        "already_seen_ids": [],
        "already_seen_titles": [],
    }
    try:
        conn = get_db()
        with conn.cursor() as cur:
            # Last 5 saved titles for the content type
            if content_type == "tv":
                cur.execute(
                    "SELECT title, tmdb_id FROM saved_tv WHERE user_id = %s ORDER BY created_at DESC LIMIT 5",
                    (user_id,),
                )
            elif content_type == "book":
                cur.execute(
                    "SELECT title, volume_id AS tmdb_id FROM saved_books WHERE user_id = %s ORDER BY created_at DESC LIMIT 5",
                    (user_id,),
                )
            else:
                cur.execute(
                    "SELECT title, tmdb_id FROM saved_movies WHERE user_id = %s ORDER BY created_at DESC LIMIT 5",
                    (user_id,),
                )
            saved_rows = cur.fetchall() or []
            result["last_saved"] = [r["title"] for r in saved_rows if r.get("title")]

            # Already seen: recent pick_history titles and IDs
            cur.execute(
                "SELECT DISTINCT title, item_id FROM pick_history "
                "WHERE user_id = %s AND type = %s ORDER BY picked_at DESC LIMIT 30",
                (user_id, content_type if content_type != "movie" else "movie"),
            )
            history_rows = cur.fetchall() or []
            result["already_seen_titles"] = [r["title"] for r in history_rows if r.get("title")]
            result["already_seen_ids"] = [r["item_id"] for r in history_rows if r.get("item_id")]

            # Favorite genres: derive from saved items via TMDB
            # Use genre_ids from pick_history or saved tables
            # For simplicity, fetch all saved item IDs and count genres from TMDB later
            # Instead, we analyze the most common titles pattern
            if content_type in ("movie", "tv"):
                table = "saved_movies" if content_type == "movie" else "saved_tv"
                cur.execute(
                    f"SELECT tmdb_id FROM {table} WHERE user_id = %s ORDER BY created_at DESC LIMIT 20",
                    (user_id,),
                )
                tmdb_rows = cur.fetchall() or []
                if tmdb_rows:
                    tmdb_ids = [str(r["tmdb_id"]) for r in tmdb_rows]
                    result["_tmdb_ids_for_genres"] = tmdb_ids

        conn.close()
    except Exception:
        pass
    return result


async def _resolve_favorite_genres(tmdb_ids: list[str], content_type: str) -> list[str]:
    """Fetch genre names for a list of TMDB IDs by querying TMDB API."""
    if not tmdb_ids or not TMDB_API_KEY:
        return []
    genre_count: dict[str, int] = {}
    media = "movie" if content_type == "movie" else "tv"
    try:
        async with httpx.AsyncClient(timeout=10) as client:
            for tmdb_id in tmdb_ids[:10]:
                try:
                    url = f"https://api.themoviedb.org/3/{media}/{tmdb_id}"
                    resp = await client.get(url, headers=_tmdb_headers(), params=_tmdb_params({"language": "en-US"}))
                    if resp.status_code != 200:
                        continue
                    data = resp.json()
                    for g in data.get("genres") or []:
                        name = g.get("name", "")
                        if name:
                            genre_count[name] = genre_count.get(name, 0) + 1
                except Exception:
                    continue
    except Exception:
        pass
    sorted_genres = sorted(genre_count.items(), key=lambda x: x[1], reverse=True)
    return [name for name, _count in sorted_genres[:5]] if sorted_genres else []


def _build_personalization_prompt(
    personalization: dict,
    favorite_genres: list[str],
    mood: str = "",
) -> str:
    """Build personalization section for AI prompt based on user history."""
    parts = []

    if favorite_genres:
        parts.append(f"User's favorite genres: {', '.join(favorite_genres)}.")

    last_saved = personalization.get("last_saved", [])
    if last_saved:
        parts.append(f"Recently saved/liked: {', '.join(last_saved)}.")

    already_seen = personalization.get("already_seen_titles", [])
    if already_seen:
        parts.append(f"Do NOT recommend these (already seen): {', '.join(already_seen[:20])}.")

    if mood:
        parts.append(f"Current mood/feeling: {mood}.")

    if parts:
        header = "\n--- USER PERSONALIZATION ---\n"
        return header + "\n".join(parts) + "\nUse this context to give a more personalized, accurate recommendation.\n"
    return ""


# ─── AI Search ───
def _clean_ai_json(content: str):
    """Parse AI response as JSON. Returns a dict or list."""
    content = (content or "").strip()
    if content.startswith("```"):
        content = content.replace("```json", "").replace("```", "").strip()

    # Try parsing as array first (new multi-suggestion format)
    first_bracket = content.find("[")
    last_bracket = content.rfind("]")
    if first_bracket != -1 and last_bracket != -1 and last_bracket > first_bracket:
        try:
            arr_content = content[first_bracket:last_bracket + 1]
            result = json.loads(arr_content)
            if isinstance(result, list) and len(result) > 0:
                return result
        except json.JSONDecodeError:
            pass

    # Fallback: parse as single object
    first = content.find("{")
    last = content.rfind("}")
    if first != -1 and last != -1 and last > first:
        content = content[first:last + 1]

    try:
        result = json.loads(content)
        return [result] if isinstance(result, dict) else result
    except json.JSONDecodeError:
        import re
        content = re.sub(r',\s*}', '}', content)
        content = re.sub(r',\s*]', ']', content)
        content = content.replace('\n', ' ').replace('\r', '')
        result = json.loads(content)
        return [result] if isinstance(result, dict) else result


async def _fetch_movie_from_tmdb(client: httpx.AsyncClient, title: str, lang: str = "uk", exclude_ids: list = None, prefer_recent: bool = False) -> dict | None:
    import random as _random
    if not TMDB_API_KEY or not title:
        return None

    exclude_ids = exclude_ids or []
    language = "uk-UA" if lang == "uk" else "en-US"
    # Only fallback to English — never Russian to avoid Russian titles
    fallback_langs = []
    if language != "en-US":
        fallback_langs.append("en-US")
    try:
        resp = await client.get(
            "https://api.themoviedb.org/3/search/movie",
            params=_tmdb_params({"query": title, "language": language, "page": "1"}),
            headers=_tmdb_headers(),
        )
        if resp.status_code != 200:
            return None

        results = resp.json().get("results", [])
        for fb_lang in fallback_langs:
            if results:
                break
            resp = await client.get(
                "https://api.themoviedb.org/3/search/movie",
                params=_tmdb_params({"query": title, "language": fb_lang, "page": "1"}),
                headers=_tmdb_headers(),
            )
            if resp.status_code == 200:
                results = resp.json().get("results", [])

        if not results:
            return None

        good = [r for r in results if r.get("id") not in exclude_ids and r.get("poster_path") and r.get("vote_average", 0) >= 5]
        if not good:
            good = [r for r in results if r.get("id") not in exclude_ids]
        if not good:
            good = results

        # Prefer newer movies when requested (Duo match, AI search)
        if prefer_recent and len(good) > 1:
            def _year_score(r):
                rd = r.get("release_date") or ""
                try:
                    return int(rd[:4])
                except (ValueError, IndexError):
                    return 0
            good.sort(key=_year_score, reverse=True)

        pool = good[:5]
        movie = _random.choice(pool) if not prefer_recent else pool[0]

        # Re-fetch in target language to ensure title is in Ukrainian/English, not Russian
        movie_id = movie.get("id")
        runtime = None
        genres = []
        if movie_id:
            try:
                detail_resp = await client.get(
                    f"https://api.themoviedb.org/3/movie/{movie_id}",
                    params=_tmdb_params({"language": language}),
                    headers=_tmdb_headers(),
                )
                if detail_resp.status_code == 200:
                    detail = detail_resp.json()
                    movie["title"] = detail.get("title") or movie.get("title")
                    movie["overview"] = detail.get("overview") or movie.get("overview")
                    runtime = detail.get("runtime") or None
                    genres = [g.get("name") for g in (detail.get("genres") or []) if g.get("name")]
            except Exception:
                pass

        return {
            "id": movie.get("id"),
            "title": movie.get("title") or movie.get("original_title") or title,
            "original_title": movie.get("original_title") or movie.get("title") or title,
            "overview": movie.get("overview") or "",
            "release_date": movie.get("release_date"),
            "vote_average": movie.get("vote_average") or 0,
            "genre_ids": movie.get("genre_ids") or [],
            "genres": genres,
            "runtime": runtime,
            "poster_path": movie.get("poster_path"),
        }
    except Exception:
        return None


async def _fetch_tv_from_tmdb(client: httpx.AsyncClient, title: str, lang: str = "uk") -> dict | None:
    import random as _random
    if not TMDB_API_KEY or not title:
        return None

