@app.post("/api/stats/event")
async def add_stats_event(req: StatsEventRequest, user=Depends(get_current_user)):
    allowed = {
        "search": "search_count",
        "random": "random_count",
        "ai_search": "ai_search_count",
    }

    if req.event not in allowed:
        raise HTTPException(status_code=400, detail="Invalid stats event")

    field = allowed[req.event]

    try:
        conn = get_db()
        with conn.cursor() as cur:
            try:
                cur.execute("INSERT INTO user_stats (user_id) VALUES (%s) ON DUPLICATE KEY UPDATE user_id = user_id", (user["id"],))
                cur.execute(f"UPDATE user_stats SET {field} = {field} + 1 WHERE user_id = %s", (user["id"],))
            except Exception as e:
                print(f"Stats update skipped (table may not exist): {e}")
        conn.close()
    except Exception as e:
        print(f"Stats DB error: {e}")

    return {"status": "ok"}


