def _require_collections_access(user_id: int):
    """Raise 403 if site freemium is on and user tier is below premium."""
    if get_site_settings().get("freemium_enabled", False):
        _tier = get_user_tier(user_id)
        if _tier not in ("premium", "pro"):
            raise HTTPException(
                status_code=403,
                detail="Колекції доступні на Premium/Pro.",
            )


@app.post("/api/collections/sync")
async def sync_collections(request: Request, user=Depends(get_current_user)):
    _require_collections_access(user["id"])
    body = await request.json()
    collections = body.get("collections", [])
    if not isinstance(collections, list):
        collections = []
    data_json = json.dumps(collections, ensure_ascii=False)
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute(
                """INSERT INTO user_collections (user_id, collections_json)
                   VALUES (%s, %s)
                   ON DUPLICATE KEY UPDATE collections_json = VALUES(collections_json)""",
                (user["id"], data_json),
            )
            # Also propagate item/name/emoji changes to any published versions
            # of these collections (matched by owner+local_id), so /c/<slug>
            # always shows the latest state from the user's local app.
            try:
                cur.execute(
                    "SELECT id, local_id FROM published_collections WHERE owner_id=%s",
                    (user["id"],),
                )
                pub_rows = cur.fetchall() or []
                pub_by_local = {r["local_id"]: r["id"] for r in pub_rows if r.get("local_id")}
                for col in collections:
                    if not isinstance(col, dict):
                        continue
                    local_id = col.get("id")
                    if not local_id or local_id not in pub_by_local:
                        continue
                    pid = pub_by_local[local_id]
                    items = col.get("items") or []
                    if not isinstance(items, list):
                        items = []
                    name = (col.get("name") or "").strip()[:255] or "Колекція"
                    emoji = (col.get("emoji") or "").strip()[:16]
                    cur.execute(
                        """UPDATE published_collections
                           SET name=%s, emoji=%s, items_json=%s,
                               updated_at=CURRENT_TIMESTAMP
                           WHERE id=%s""",
                        (name, emoji, json.dumps(items, ensure_ascii=False), pid),
                    )
            except Exception as e:
                print(f"sync_collections published mirror error: {e}")
        conn.close()
    except Exception:
        raise HTTPException(status_code=503, detail="Database unavailable")
    return {"status": "ok"}


@app.get("/api/collections")
async def get_collections(user=Depends(get_current_user)):
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute(
                "SELECT collections_json FROM user_collections WHERE user_id = %s",
                (user["id"],),
            )
            row = cur.fetchone()
        conn.close()
        if row and row["collections_json"]:
            return {"collections": json.loads(row["collections_json"])}
        return {"collections": []}
    except Exception:
        raise HTTPException(status_code=503, detail="Database unavailable")


# ─── Public collections (publish / share / like / comment / co-edit / follow) ───

import secrets as _secrets
import re as _re_pub


def _slugify(text: str, max_len: int = 50) -> str:
    """ASCII-friendly slug; supports Cyrillic via simple transliteration."""
    if not text:
        return ""
    translit = {
        "а":"a","б":"b","в":"v","г":"h","ґ":"g","д":"d","е":"e","є":"ie","ж":"zh","з":"z",
        "и":"y","і":"i","ї":"i","й":"i","к":"k","л":"l","м":"m","н":"n","о":"o","п":"p",
        "р":"r","с":"s","т":"t","у":"u","ф":"f","х":"kh","ц":"ts","ч":"ch","ш":"sh","щ":"shch",
        "ь":"","ю":"iu","я":"ia","ё":"e","ы":"y","э":"e","ъ":"",
    }
    s = (text or "").lower().strip()
    out = []
    for ch in s:
        if ch in translit:
            out.append(translit[ch])
        elif ch.isascii() and (ch.isalnum() or ch in " -_"):
            out.append(ch)
        elif ch == " ":
            out.append("-")
    s = "".join(out)
    s = _re_pub.sub(r"[^a-z0-9]+", "-", s).strip("-")
    s = _re_pub.sub(r"-{2,}", "-", s)
    return s[:max_len] or "collection"


def _gen_unique_slug(cur, base: str) -> str:
    base = _slugify(base) or "collection"
    candidate = base
    suffix = _secrets.token_urlsafe(3).lower().replace("_", "").replace("-", "")[:5]
    cur.execute("SELECT 1 FROM published_collections WHERE slug = %s", (candidate,))
    if not cur.fetchone():
        return candidate
    candidate = f"{base}-{suffix}"
    cur.execute("SELECT 1 FROM published_collections WHERE slug = %s", (candidate,))
    if not cur.fetchone():
        return candidate
    # very unlikely collision: extend
    candidate = f"{base}-{_secrets.token_urlsafe(6).lower().replace('_','').replace('-','')[:8]}"
    return candidate


def _can_edit_collection(cur, collection_id: int, user_id: int) -> bool:
    cur.execute(
        "SELECT owner_id FROM published_collections WHERE id = %s",
        (collection_id,),
    )
    row = cur.fetchone()
    if not row:
        return False
    if row["owner_id"] == user_id:
        return True
    cur.execute(
        "SELECT role FROM collection_collaborators WHERE collection_id=%s AND user_id=%s",
        (collection_id, user_id),
    )
    role = cur.fetchone()
    return bool(role and role["role"] in ("owner", "editor"))


def _is_owner(cur, collection_id: int, user_id: int) -> bool:
    cur.execute(
        "SELECT owner_id FROM published_collections WHERE id = %s",
        (collection_id,),
    )
    row = cur.fetchone()
    return bool(row and row["owner_id"] == user_id)


def _build_pub_collection_dto(cur, row, viewer_id: int | None) -> dict:
    cid = row["id"]
    cur.execute(
        "SELECT id, username, email FROM users WHERE id = %s",
        (row["owner_id"],),
    )
    owner = cur.fetchone() or {}
    owner_name = owner.get("username") or (owner.get("email") or "").split("@")[0] or "User"
    items = []
    if row.get("items_json"):
        try:
            items = json.loads(row["items_json"]) or []
        except Exception:
            items = []
    is_liked = False
    is_following = False
    if viewer_id:
        cur.execute(
            "SELECT 1 FROM collection_likes WHERE collection_id=%s AND user_id=%s",
            (cid, viewer_id),
        )
        is_liked = bool(cur.fetchone())
        cur.execute(
            "SELECT 1 FROM user_follows WHERE follower_id=%s AND target_id=%s",
            (viewer_id, row["owner_id"]),
        )
        is_following = bool(cur.fetchone())
    return {
        "id": cid,
        "local_id": row.get("local_id") or "",
        "slug": row["slug"],
        "name": row["name"],
        "emoji": row["emoji"],
        "description": row.get("description") or "",
        "visibility": row["visibility"],
        "items": items,
        "items_count": len(items),
        "likes_count": row["likes_count"],
        "comments_count": row["comments_count"],
        "views_count": row["views_count"],
        "is_liked": is_liked,
        "is_following_owner": is_following,
        "owner": {
            "id": row["owner_id"],
            "username": owner_name,
        },
        "is_owner": viewer_id == row["owner_id"] if viewer_id else False,
        "created_at": _iso_utc(row.get("created_at")),
        "updated_at": _iso_utc(row.get("updated_at")),
    }


@app.post("/api/collections/publish")
async def publish_collection(request: Request, user=Depends(get_current_user)):
    """Publish/update a user's local collection. Body:
       {local_id, name, emoji, description, items, visibility (public|unlisted|private)}"""
    # Collections is a Premium+/Pro feature when freemium is enabled.
    if get_site_settings().get("freemium_enabled", False):
        _tier = get_user_tier(user["id"])
        if _tier not in ("premium", "pro"):
            raise HTTPException(
                status_code=403,
                detail="Колекції доступні на Premium/Pro. Оновіть підписку, щоб ділитися своїми колекціями!",
            )
    body = await request.json()
    local_id = (body.get("local_id") or "").strip()
    if not local_id:
        raise HTTPException(status_code=400, detail="local_id required")
    name = (body.get("name") or "").strip()[:255] or "Колекція"
    emoji = (body.get("emoji") or "").strip()[:16]
    description = (body.get("description") or "").strip()[:2000] or None
    items = body.get("items") or []
    if not isinstance(items, list):
        items = []
    items_json = json.dumps(items, ensure_ascii=False)
    visibility = (body.get("visibility") or "public").strip().lower()
    if visibility not in ("public", "unlisted", "private"):
        visibility = "public"
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute(
                "SELECT id, slug FROM published_collections WHERE owner_id=%s AND local_id=%s",
                (user["id"], local_id),
            )
            existing = cur.fetchone()
            if existing:
                cur.execute(
                    """UPDATE published_collections
                       SET name=%s, emoji=%s, description=%s, items_json=%s, visibility=%s
                       WHERE id=%s""",
                    (name, emoji, description, items_json, visibility, existing["id"]),
                )
                pid = existing["id"]
                slug = existing["slug"]
            else:
                slug = _gen_unique_slug(cur, name)
                cur.execute(
                    """INSERT INTO published_collections
                       (owner_id, local_id, slug, name, emoji, description, items_json, visibility)
                       VALUES (%s,%s,%s,%s,%s,%s,%s,%s)""",
                    (user["id"], local_id, slug, name, emoji, description, items_json, visibility),
                )
                pid = cur.lastrowid
                # owner is also a collaborator with role=owner
                cur.execute(
                    """INSERT IGNORE INTO collection_collaborators
                       (collection_id, user_id, role) VALUES (%s,%s,'owner')""",
                    (pid, user["id"]),
                )
            cur.execute(
                "SELECT * FROM published_collections WHERE id = %s",
                (pid,),
            )
            row = cur.fetchone()
            dto = _build_pub_collection_dto(cur, row, user["id"])
        conn.close()
        return {"collection": dto}
    except HTTPException:
        raise
    except Exception as e:
        print(f"publish_collection error: {e}")
        raise HTTPException(status_code=503, detail="Database unavailable")


@app.delete("/api/collections/published/{local_id}")
async def unpublish_collection(local_id: str, user=Depends(get_current_user)):
    """Unpublish (delete from public DB) the user's published collection.
    Accepts local_id (string) or numeric published collection id."""
    try:
        conn = get_db()
        with conn.cursor() as cur:
            # Try matching by local_id first, then by numeric id
            cur.execute(
                "DELETE FROM published_collections WHERE owner_id=%s AND local_id=%s",
                (user["id"], local_id),
            )
            if cur.rowcount == 0:
                try:
                    cid = int(local_id)
                    cur.execute(
                        "DELETE FROM published_collections WHERE owner_id=%s AND id=%s",
                        (user["id"], cid),
                    )
                except (ValueError, TypeError):
                    pass
        conn.close()
    except Exception:
        raise HTTPException(status_code=503, detail="Database unavailable")
    return {"status": "ok"}


@app.patch("/api/collections/{cid}/visibility")
async def change_collection_visibility(cid: int, request: Request, user=Depends(get_current_user)):
    """Change visibility of a published collection (owner only)."""
    body = await request.json()
    visibility = (body.get("visibility") or "").strip().lower()
    if visibility not in ("public", "unlisted", "private"):
        raise HTTPException(status_code=400, detail="Invalid visibility")
    try:
        conn = get_db()
        with conn.cursor() as cur:
            if not _is_owner(cur, cid, user["id"]):
                conn.close()
                raise HTTPException(status_code=403, detail="Owner only")
            cur.execute(
                "UPDATE published_collections SET visibility=%s WHERE id=%s",
                (visibility, cid),
            )
        conn.close()
        return {"status": "ok", "visibility": visibility}
    except HTTPException:
        raise
    except Exception:
        raise HTTPException(status_code=503, detail="Database unavailable")


