@app.get("/api/collections/feed")
async def public_collections_feed(
    sort: str = "recent",
    limit: int = 24,
    offset: int = 0,
    user=Depends(get_current_user_optional),
):
    """Public discovery feed of public collections. sort: recent | popular"""
    sort = sort if sort in ("recent", "popular") else "recent"
    limit = max(1, min(int(limit or 24), 50))
    offset = max(0, int(offset or 0))
    order_clause = "updated_at DESC" if sort == "recent" else "likes_count DESC, updated_at DESC"
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute(
                f"SELECT * FROM published_collections WHERE visibility='public' "
                f"ORDER BY {order_clause} LIMIT %s OFFSET %s",
                (limit, offset),
            )
            rows = cur.fetchall() or []
            viewer = user["id"] if user else None
            out = [_build_pub_collection_dto(cur, r, viewer) for r in rows]
        conn.close()
        return {"collections": out, "limit": limit, "offset": offset, "sort": sort}
    except Exception:
        raise HTTPException(status_code=503, detail="Database unavailable")


@app.get("/api/collections/by-slug/{slug}")
async def get_public_collection(slug: str, user=Depends(get_current_user_optional)):
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT * FROM published_collections WHERE slug=%s", (slug,))
            row = cur.fetchone()
            if not row:
                conn.close()
                raise HTTPException(status_code=404, detail="not found")
            # Visibility check
            viewer_id = user["id"] if user else None
            is_owner = viewer_id == row["owner_id"]
            is_collab = False
            if viewer_id:
                cur.execute(
                    "SELECT 1 FROM collection_collaborators WHERE collection_id=%s AND user_id=%s",
                    (row["id"], viewer_id),
                )
                is_collab = bool(cur.fetchone())
            if row["visibility"] == "private" and not (is_owner or is_collab):
                conn.close()
                raise HTTPException(status_code=403, detail="private")
            # Bump views (best-effort, no harm if it fails)
            try:
                cur.execute(
                    "UPDATE published_collections SET views_count=views_count+1 WHERE id=%s",
                    (row["id"],),
                )
                row["views_count"] = (row["views_count"] or 0) + 1
            except Exception:
                pass
            dto = _build_pub_collection_dto(cur, row, viewer_id)
            # Include collaborator list summary
            cur.execute(
                """SELECT u.id, u.username, u.email, c.role
                   FROM collection_collaborators c JOIN users u ON u.id=c.user_id
                   WHERE c.collection_id=%s ORDER BY c.role='owner' DESC, c.joined_at""",
                (row["id"],),
            )
            collabs = []
            for r in cur.fetchall() or []:
                nm = r.get("username") or (r.get("email") or "").split("@")[0]
                collabs.append({"id": r["id"], "username": nm, "role": r["role"]})
            dto["collaborators"] = collabs
        conn.close()
        return {"collection": dto}
    except HTTPException:
        raise
    except Exception as e:
        print(f"get_public_collection error: {e}")
        raise HTTPException(status_code=503, detail="Database unavailable")


