@app.post("/api/collections/{cid}/comments")
async def post_comment(cid: int, request: Request, user=Depends(get_current_user)):
    body = await request.json()
    text = (body.get("body") or "").strip()
    if not text:
        raise HTTPException(status_code=400, detail="body required")
    if len(text) > 1000:
        text = text[:1000]
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT id FROM published_collections WHERE id=%s", (cid,))
            if not cur.fetchone():
                conn.close()
                raise HTTPException(status_code=404, detail="not found")
            cur.execute(
                "INSERT INTO collection_comments (collection_id, user_id, body) VALUES (%s,%s,%s)",
                (cid, user["id"], text),
            )
            cur.execute(
                "UPDATE published_collections SET comments_count=comments_count+1 WHERE id=%s",
                (cid,),
            )
            new_id = cur.lastrowid
            cur.execute(
                """SELECT c.id, c.body, c.created_at, c.user_id, u.username, u.email
                   FROM collection_comments c JOIN users u ON u.id=c.user_id
                   WHERE c.id=%s""",
                (new_id,),
            )
            r = cur.fetchone() or {}
        conn.close()
        nm = r.get("username") or (r.get("email") or "").split("@")[0]
        return {
            "comment": {
                "id": r.get("id"),
                "body": r.get("body"),
                "created_at": _iso_utc(r.get("created_at")),
                "author": {"id": user["id"], "username": nm},
                "is_mine": True,
            }
        }
    except HTTPException:
        raise
    except Exception:
        raise HTTPException(status_code=503, detail="Database unavailable")


