@app.get("/api/users/{uid}/profile")
async def public_user_profile(uid: int, user=Depends(get_current_user_optional)):
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT id, username, email, created_at FROM users WHERE id=%s", (uid,))
            u = cur.fetchone()
            if not u:
                conn.close()
                raise HTTPException(status_code=404, detail="not found")
            nm = u.get("username") or (u.get("email") or "").split("@")[0]
            joined_at = _iso_utc(u.get("created_at"))
            cur.execute("SELECT COUNT(*) AS c FROM user_follows WHERE target_id=%s", (uid,))
            followers = cur.fetchone()
            cur.execute("SELECT COUNT(*) AS c FROM user_follows WHERE follower_id=%s", (uid,))
            following = cur.fetchone()
            is_following = False
            if user and user["id"] != uid:
                cur.execute(
                    "SELECT 1 FROM user_follows WHERE follower_id=%s AND target_id=%s",
                    (user["id"], uid),
                )
                is_following = bool(cur.fetchone())
            # Saved items (movies + tv + books)
            saved_counts = {"movies": 0, "tv": 0, "books": 0}
            for tname, key in (("saved_movies", "movies"), ("saved_tv", "tv"), ("saved_books", "books")):
                try:
                    cur.execute(f"SELECT COUNT(*) AS c FROM {tname} WHERE user_id=%s", (uid,))
                    r = cur.fetchone()
                    saved_counts[key] = (r["c"] if r else 0) or 0
                except Exception:
                    pass
            saved_total = saved_counts["movies"] + saved_counts["tv"] + saved_counts["books"]
            # Aggregated stats over user's public collections
            cur.execute(
                """SELECT COUNT(*) AS c, COALESCE(SUM(likes_count),0) AS likes,
                          COALESCE(SUM(comments_count),0) AS comments,
                          COALESCE(SUM(views_count),0) AS views
                   FROM published_collections
                   WHERE owner_id=%s AND visibility='public'""",
                (uid,),
            )
            agg = cur.fetchone() or {}
            # All public collections (limit 24 for first paint)
            cur.execute(
                "SELECT * FROM published_collections WHERE owner_id=%s AND visibility='public' "
                "ORDER BY updated_at DESC LIMIT 24",
                (uid,),
            )
            rows = cur.fetchall() or []
            viewer = user["id"] if user else None
            colls = [_build_pub_collection_dto(cur, r, viewer) for r in rows]
            # Recent activity from public_collections + comments
            activity: list = []
            for r in rows[:5]:
                activity.append({
                    "kind": "collection",
                    "ts": _iso_utc(r.get("updated_at")),
                    "title": r.get("name"),
                    "slug": r.get("slug"),
                    "emoji": r.get("emoji"),
                })
            try:
                cur.execute(
                    """SELECT cc.id, cc.body, cc.created_at, pc.name AS coll_name, pc.slug AS coll_slug
                       FROM collection_comments cc
                       JOIN published_collections pc ON pc.id=cc.collection_id
                       WHERE cc.user_id=%s AND pc.visibility IN ('public','unlisted')
                       ORDER BY cc.created_at DESC LIMIT 5""",
                    (uid,),
                )
                for cmt in cur.fetchall() or []:
                    activity.append({
                        "kind": "comment",
                        "ts": _iso_utc(cmt.get("created_at")),
                        "title": cmt.get("coll_name"),
                        "slug": cmt.get("coll_slug"),
                        "body": (cmt.get("body") or "")[:120],
                    })
            except Exception:
                pass
            activity.sort(key=lambda x: x.get("ts") or "", reverse=True)
            activity = activity[:8]
        conn.close()
        return {
            "user": {
                "id": uid,
                "username": nm,
                "joined_at": joined_at,
                "followers_count": followers["c"] if followers else 0,
                "following_count": following["c"] if following else 0,
                "is_following": is_following,
                "is_self": user["id"] == uid if user else False,
            },
            "stats": {
                "saved_total": saved_total,
                "saved_movies": saved_counts["movies"],
                "saved_tv": saved_counts["tv"],
                "saved_books": saved_counts["books"],
                "public_collections": agg.get("c") or 0,
                "total_likes": agg.get("likes") or 0,
                "total_comments": agg.get("comments") or 0,
                "total_views": agg.get("views") or 0,
            },
            "collections": colls,
            "activity": activity,
        }
    except HTTPException:
        raise
    except Exception:
        raise HTTPException(status_code=503, detail="Database unavailable")


@app.post("/api/collections/{cid}/invites")
async def create_invite(cid: int, request: Request, user=Depends(get_current_user)):
    body = await request.json() if (request.headers.get("content-type") or "").startswith("application/json") else {}
    role = (body.get("role") or "editor").strip().lower()
    if role not in ("editor", "viewer"):
        role = "editor"
    try:
        conn = get_db()
        with conn.cursor() as cur:
            if not _is_owner(cur, cid, user["id"]):
                conn.close()
                raise HTTPException(status_code=403, detail="owner only")
            tok = _secrets.token_urlsafe(24)
            cur.execute(
                """INSERT INTO collection_invites
                   (collection_id, token, role, created_by, uses_left)
                   VALUES (%s,%s,%s,%s,%s)""",
                (cid, tok, role, user["id"], 5),
            )
        conn.close()
        return {"token": tok, "role": role}
    except HTTPException:
        raise
    except Exception:
        raise HTTPException(status_code=503, detail="Database unavailable")


@app.post("/api/collections/invites/{token}/accept")
async def accept_invite(token: str, user=Depends(get_current_user)):
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute(
                "SELECT * FROM collection_invites WHERE token=%s",
                (token,),
            )
            inv = cur.fetchone()
            if not inv or (inv.get("uses_left") or 0) <= 0:
                conn.close()
                raise HTTPException(status_code=410, detail="invalid or used")
            cid = inv["collection_id"]
            role = inv["role"]
            # Owners can't accept their own invite
            cur.execute("SELECT owner_id FROM published_collections WHERE id=%s", (cid,))
            pc = cur.fetchone()
            if not pc:
                conn.close()
                raise HTTPException(status_code=404, detail="collection missing")
            if pc["owner_id"] == user["id"]:
                conn.close()
                raise HTTPException(status_code=400, detail="own collection")
            cur.execute(
                """INSERT INTO collection_collaborators
                   (collection_id, user_id, role, invited_by) VALUES (%s,%s,%s,%s)
                   ON DUPLICATE KEY UPDATE role=VALUES(role)""",
                (cid, user["id"], role, inv["created_by"]),
            )
            cur.execute(
                "UPDATE collection_invites SET uses_left=GREATEST(0,uses_left-1) WHERE id=%s",
                (inv["id"],),
            )
            cur.execute(
                "SELECT * FROM published_collections WHERE id=%s", (cid,),
            )
            row = cur.fetchone() or {}
            dto = _build_pub_collection_dto(cur, row, user["id"]) if row else {}
            if dto:
                dto["my_role"] = role
        conn.close()
        return {
            "status": "ok",
            "collection_id": cid,
            "slug": dto.get("slug") if dto else None,
            "role": role,
            "collection": dto or None,
        }
    except HTTPException:
        raise
    except Exception as e:
        print(f"accept_invite error: {e}")
        raise HTTPException(status_code=503, detail="Database unavailable")


