@app.post("/api/collections/{cid}/items/add")
async def add_item_to_published(cid: int, request: Request, user=Depends(get_current_user)):
    """Add an item to a published collection (owner or editor)."""
    body = await request.json()
    item = body.get("item") or {}
    if not item or not item.get("id") or not item.get("type"):
        raise HTTPException(status_code=400, detail="item with id and type required")
    if item.get("type") not in ("movie", "tv", "book"):
        raise HTTPException(status_code=400, detail="invalid type")
    try:
        conn = get_db()
        with conn.cursor() as cur:
            if not _can_edit_collection(cur, cid, user["id"]):
                conn.close()
                raise HTTPException(status_code=403, detail="edit permission required")
            cur.execute(
                "SELECT items_json, owner_id, local_id FROM published_collections WHERE id=%s",
                (cid,),
            )
            row = cur.fetchone()
            if not row:
                conn.close()
                raise HTTPException(status_code=404, detail="not found")
            try:
                items = json.loads(row.get("items_json") or "[]") or []
                if not isinstance(items, list):
                    items = []
            except Exception:
                items = []
            exists = any(
                str(it.get("id")) == str(item.get("id")) and it.get("type") == item.get("type")
                for it in items
            )
            if not exists:
                import time as _t_inline
                clean_item = {
                    "id": item.get("id"),
                    "type": item.get("type"),
                    "title": (item.get("title") or "")[:500],
                    "poster": item.get("poster") or "",
                    "year": str(item.get("year") or "")[:10],
                    "rating": str(item.get("rating") or "")[:10],
                    "url": item.get("url") or "",
                    "description": (item.get("description") or "")[:300],
                    "addedAt": int(_t_inline.time() * 1000),
                }
                for k in ("runtime", "number_of_seasons", "number_of_episodes",
                          "episode_run_time", "page_count"):
                    if item.get(k) is not None:
                        clean_item[k] = item.get(k)
                items.append(clean_item)
            cur.execute(
                "UPDATE published_collections SET items_json=%s, updated_at=CURRENT_TIMESTAMP WHERE id=%s",
                (json.dumps(items, ensure_ascii=False), cid),
            )
        conn.close()
        return {"status": "ok", "items_count": len(items), "added": not exists}
    except HTTPException:
        raise
    except Exception as e:
        print(f"add_item_to_published error: {e}")
        raise HTTPException(status_code=503, detail="Database unavailable")


@app.post("/api/collections/{cid}/items/remove")
async def remove_item_from_published(cid: int, request: Request, user=Depends(get_current_user)):
    """Remove an item from a published collection (owner or editor)."""
    body = await request.json()
    item_id = body.get("id")
    item_type = body.get("type")
    if not item_id or not item_type:
        raise HTTPException(status_code=400, detail="id and type required")
    try:
        conn = get_db()
        with conn.cursor() as cur:
            if not _can_edit_collection(cur, cid, user["id"]):
                conn.close()
                raise HTTPException(status_code=403, detail="edit permission required")
            cur.execute("SELECT items_json FROM published_collections WHERE id=%s", (cid,))
            row = cur.fetchone()
            if not row:
                conn.close()
                raise HTTPException(status_code=404, detail="not found")
            try:
                items = json.loads(row.get("items_json") or "[]") or []
                if not isinstance(items, list):
                    items = []
            except Exception:
                items = []
            items = [
                it for it in items
                if not (str(it.get("id")) == str(item_id) and it.get("type") == item_type)
            ]
            cur.execute(
                "UPDATE published_collections SET items_json=%s, updated_at=CURRENT_TIMESTAMP WHERE id=%s",
                (json.dumps(items, ensure_ascii=False), cid),
            )
        conn.close()
        return {"status": "ok", "items_count": len(items)}
    except HTTPException:
        raise
    except Exception as e:
        print(f"remove_item_from_published error: {e}")
        raise HTTPException(status_code=503, detail="Database unavailable")


