# ─── Pick history & level system ───
HISTORY_VALID_TYPES = {"movie", "tv", "book"}


@app.post("/api/me/history")
async def add_history(req: HistoryItemRequest, user=Depends(get_current_user)):
    if req.type not in HISTORY_VALID_TYPES:
        raise HTTPException(status_code=400, detail="invalid type")
    check_pick_limit(user["id"])
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute(
                """INSERT INTO pick_history
                   (user_id, type, item_id, title, poster, year, rating, item_url)
                   VALUES (%s, %s, %s, %s, %s, %s, %s, %s)""",
                (user["id"], req.type, str(req.item_id), req.title,
                 req.poster, req.year, req.rating, req.item_url),
            )
        conn.close()
    except HTTPException:
        raise
    except Exception:
        raise HTTPException(status_code=503, detail="Database unavailable")
    increment_pick_count(user["id"])
    # Broadcast to live bar SSE clients
    if req.title and req.title != '__admin_streak__':
        _live_last_pick.update({
            "title": req.title,
            "type": req.type,
            # Always emit UTC with a trailing 'Z' so the browser parses it
            # as UTC (not local time). Otherwise the "time since last pick"
            # ticker drifts by the user's UTC offset.
            "picked_at": datetime.datetime.utcnow().isoformat() + "Z",
        })
        asyncio.ensure_future(_live_broadcast({"type": "pick", **_live_snapshot()}))
    return {"status": "ok"}


@app.get("/api/me/history")
async def list_history(
    user=Depends(get_current_user),
    type: Optional[str] = None,
    limit: int = 30,
    offset: int = 0,
):
    if type and type not in HISTORY_VALID_TYPES:
        raise HTTPException(status_code=400, detail="invalid type")
    limit = max(1, min(100, limit))
    offset = max(0, offset)
    try:
        conn = get_db()
        with conn.cursor() as cur:
            if type:
                cur.execute(
                    """SELECT id, type, item_id, title, poster, year, rating, item_url, picked_at
                       FROM pick_history
                       WHERE user_id = %s AND type = %s
                       ORDER BY picked_at DESC, id DESC
                       LIMIT %s OFFSET %s""",
                    (user["id"], type, limit, offset),
                )
            else:
                cur.execute(
                    """SELECT id, type, item_id, title, poster, year, rating, item_url, picked_at
                       FROM pick_history
                       WHERE user_id = %s
                       ORDER BY picked_at DESC, id DESC
                       LIMIT %s OFFSET %s""",
                    (user["id"], limit, offset),
                )
            rows = cur.fetchall() or []
            cur.execute(
                "SELECT COUNT(*) AS c FROM pick_history WHERE user_id = %s"
                + (" AND type = %s" if type else ""),
                ((user["id"], type) if type else (user["id"],)),
            )
            total_row = cur.fetchone() or {"c": 0}
        conn.close()
    except Exception:
        raise HTTPException(status_code=503, detail="Database unavailable")
    items = [
        {
            "id": r["id"],
            "type": r["type"],
            "item_id": r["item_id"],
            "title": r["title"],
            "poster": r["poster"],
            "year": r["year"],
            "rating": r["rating"],
            "url": r["item_url"],
            "picked_at": _iso_utc(r["picked_at"]),
        }
        for r in rows
    ]
    return {"items": items, "total": int(total_row["c"]), "limit": limit, "offset": offset}


_PICK_ENRICH_CACHE: dict[tuple, dict] = {}
_PICK_ENRICH_CACHE_TTL = 60 * 30  # 30 minutes


async def _enrich_pick_movie(client: httpx.AsyncClient, item_id: str, language: str) -> dict:
    cache_key = ("movie", str(item_id), language)
    hit = _PICK_ENRICH_CACHE.get(cache_key)
    if hit and (_time.time() - hit.get("_ts", 0)) < _PICK_ENRICH_CACHE_TTL:
        return hit["data"]
    try:
        resp = await client.get(
            f"https://api.themoviedb.org/3/movie/{item_id}",
            params=_tmdb_params({"language": language}),
            headers=_tmdb_headers(),
            timeout=8,
        )
        if resp.status_code != 200:
            return {}
        d = resp.json() or {}
        out = {
            "overview": (d.get("overview") or "")[:600],
            "genres": [g.get("name", "") for g in (d.get("genres") or []) if g.get("name")],
            "runtime": int(d.get("runtime") or 0),
            "tagline": d.get("tagline") or "",
        }
    except Exception:
        out = {}
    _PICK_ENRICH_CACHE[cache_key] = {"_ts": _time.time(), "data": out}
    return out


async def _enrich_pick_tv(client: httpx.AsyncClient, item_id: str, language: str) -> dict:
    cache_key = ("tv", str(item_id), language)
    hit = _PICK_ENRICH_CACHE.get(cache_key)
    if hit and (_time.time() - hit.get("_ts", 0)) < _PICK_ENRICH_CACHE_TTL:
        return hit["data"]
    try:
        resp = await client.get(
            f"https://api.themoviedb.org/3/tv/{item_id}",
            params=_tmdb_params({"language": language}),
            headers=_tmdb_headers(),
            timeout=8,
        )
        if resp.status_code != 200:
            return {}
        d = resp.json() or {}
        episode_runtime = d.get("episode_run_time") or []
        ep_rt = int(episode_runtime[0]) if episode_runtime else 0
        out = {
            "overview": (d.get("overview") or "")[:600],
            "genres": [g.get("name", "") for g in (d.get("genres") or []) if g.get("name")],
            "runtime": ep_rt,
            "episodes": int(d.get("number_of_episodes") or 0),
            "seasons": int(d.get("number_of_seasons") or 0),
            "tagline": d.get("tagline") or "",
        }
    except Exception:
        out = {}
    _PICK_ENRICH_CACHE[cache_key] = {"_ts": _time.time(), "data": out}
    return out


async def _enrich_pick_book(client: httpx.AsyncClient, item_id: str) -> dict:
    cache_key = ("book", str(item_id), "")
    hit = _PICK_ENRICH_CACHE.get(cache_key)
    if hit and (_time.time() - hit.get("_ts", 0)) < _PICK_ENRICH_CACHE_TTL:
        return hit["data"]
    try:
        params = {}
        if GOOGLE_BOOKS_API_KEY:
            params["key"] = GOOGLE_BOOKS_API_KEY
        resp = await client.get(
            f"https://www.googleapis.com/books/v1/volumes/{item_id}",
            params=params,
            timeout=8,
        )
        if resp.status_code != 200:
            return {}
        info = (resp.json() or {}).get("volumeInfo") or {}
        # description can be HTML — strip naively
        desc = info.get("description") or ""
        if "<" in desc and ">" in desc:
            desc = re.sub(r"<[^>]+>", "", desc)
        out = {
            "overview": desc[:600],
            "genres": info.get("categories") or [],
            "pages": int(info.get("pageCount") or 0),
            "authors": info.get("authors") or [],
        }
    except Exception:
        out = {}
    _PICK_ENRICH_CACHE[cache_key] = {"_ts": _time.time(), "data": out}
    return out


async def _enrich_picks(items: list, lang: str = "uk") -> list:
    """Fetch overview/genres/runtime for each pick in parallel.

    Mutates and returns the items list. Failed fetches leave the original
    item unchanged (extra fields simply absent). 30-minute in-memory cache
    avoids hammering TMDB / Google Books.
    """
    if not items:
        return items
    language = "uk-UA" if lang == "uk" else "en-US"
    try:
        async with httpx.AsyncClient(timeout=10) as client:
            async def _one(it: dict):
                try:
                    iid = str(it.get("item_id") or "")
                    if not iid:
                        return
                    if it.get("type") == "movie":
                        extra = await _enrich_pick_movie(client, iid, language)
                    elif it.get("type") == "tv":
                        extra = await _enrich_pick_tv(client, iid, language)
                    elif it.get("type") == "book":
                        extra = await _enrich_pick_book(client, iid)
                    else:
                        extra = {}
                    if extra:
                        it.update(extra)
                except Exception:
                    pass
            await asyncio.gather(*[_one(it) for it in items])
    except Exception:
        pass
    return items


@app.get("/api/picks/global")
async def list_global_picks(
    type: Optional[str] = None,
    limit: int = 20,
    enrich: int = 0,
    lang: str = "uk",
):
    """Recent picks across **all** users, anonymized.

    Used by the live activity bar and the "recent picks" modal so users see
    actual site-wide activity instead of just their own history. Returns a
    deduplicated list (one entry per item) ordered by most-recent pick.

    Pass ``enrich=1`` to also include description, genres, and runtime/pages
    for each item (fetched in parallel from TMDB / Google Books with a
    30-minute in-memory cache).
    """
    if type and type not in HISTORY_VALID_TYPES:
        raise HTTPException(status_code=400, detail="invalid type")
    limit = max(1, min(60, limit))
    try:
        conn = get_db()
        with conn.cursor() as cur:
            # Pull a generous window so we can dedupe down to `limit` rows.
            window = max(limit * 4, 80)
            if type:
                cur.execute(
                    """SELECT type, item_id, title, poster, year, rating, item_url,
                              MAX(picked_at) AS picked_at, COUNT(*) AS c
                       FROM pick_history
                       WHERE type = %s
                         AND title IS NOT NULL AND title <> ''
                         AND title <> '__admin_streak__'
                       GROUP BY type, item_id, title, poster, year, rating, item_url
                       ORDER BY MAX(picked_at) DESC
                       LIMIT %s""",
                    (type, window),
                )
            else:
                cur.execute(
                    """SELECT type, item_id, title, poster, year, rating, item_url,
                              MAX(picked_at) AS picked_at, COUNT(*) AS c
                       FROM pick_history
                       WHERE title IS NOT NULL AND title <> ''
                         AND title <> '__admin_streak__'
                       GROUP BY type, item_id, title, poster, year, rating, item_url
                       ORDER BY MAX(picked_at) DESC
                       LIMIT %s""",
                    (window,),
                )
            rows = cur.fetchall() or []
        conn.close()
    except Exception:
        return {"items": [], "total": 0, "limit": limit}
    items: list = []
    seen: set = set()
    for r in rows:
        key = (r["type"], str(r["item_id"]), (r["title"] or "").strip().lower())
        if key in seen:
            continue
        seen.add(key)
        items.append({
            "type": r["type"],
            "item_id": r["item_id"],
            "title": r["title"],
            "poster": r["poster"],
            "year": r["year"],
            "rating": r["rating"],
            "url": r["item_url"],
            "picked_at": _iso_utc(r["picked_at"]),
            "picks": int(r["c"]) if "c" in r and r["c"] is not None else 0,
        })
        if len(items) >= limit:
            break
    if enrich:
        items = await _enrich_picks(items, lang=lang)
    return {"items": items, "total": len(items), "limit": limit}


@app.get("/api/picks/stats")
async def global_picks_stats():
    """Lightweight global counters for the live activity bar."""
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute(
                "SELECT COUNT(*) AS c FROM pick_history "
                "WHERE picked_at >= NOW() - INTERVAL 24 HOUR "
                "AND title <> '__admin_streak__'"
            )
            picks_24h = int((cur.fetchone() or {"c": 0})["c"])
            cur.execute(
                "SELECT COUNT(DISTINCT user_id) AS c FROM pick_history "
                "WHERE picked_at >= NOW() - INTERVAL 24 HOUR "
                "AND title <> '__admin_streak__'"
            )
            active_users_24h = int((cur.fetchone() or {"c": 0})["c"])
            cur.execute(
                "SELECT COUNT(DISTINCT user_id) AS c FROM pick_history "
                "WHERE picked_at >= NOW() - INTERVAL 5 MINUTE "
                "AND title <> '__admin_streak__'"
            )
            active_now = int((cur.fetchone() or {"c": 0})["c"])
        conn.close()
    except Exception:
        return {"picks_24h": 0, "active_users_24h": 0, "active_now": 0}
    return {
        "picks_24h": picks_24h,
        "active_users_24h": active_users_24h,
        "active_now": active_now,
    }


# ─── Live Bar SSE (real-time online counter + last pick) ─────────────
_live_clients: set = set()          # active SSE asyncio.Queue instances
_live_last_pick: dict = {}          # {title, type, picked_at, user}
_live_online_extra: int = 0         # DB active_now cached value


async def _live_broadcast(data: dict):
    """Push a JSON event to every connected SSE client."""
    msg = json.dumps(data, ensure_ascii=False, default=str)
    dead = []
    for q in _live_clients:
        try:
            q.put_nowait(msg)
        except Exception:
            dead.append(q)
    for q in dead:
        _live_clients.discard(q)


def _live_snapshot() -> dict:
    online = len(_live_clients) + _live_online_extra
    return {
        "online": max(online, 1),
        "last_pick": _live_last_pick if _live_last_pick else None,
    }


async def _live_bg_refresh():
    """Background task: refresh DB-based active_now every 30s and broadcast."""
    global _live_online_extra
    while True:
        try:
            await asyncio.sleep(30)
            try:
                conn = get_db()
                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT COUNT(DISTINCT user_id) AS c FROM pick_history "
                        "WHERE picked_at >= NOW() - INTERVAL 5 MINUTE "
                        "AND title <> '__admin_streak__'"
                    )
                    _live_online_extra = max(int((cur.fetchone() or {"c": 0})["c"]) - len(_live_clients), 0)
                    # Also grab the very latest pick
                    cur.execute(
                        "SELECT title, type, picked_at FROM pick_history "
                        "WHERE title <> '__admin_streak__' "
                        "ORDER BY picked_at DESC LIMIT 1"
                    )
                    row = cur.fetchone()
                    if row and row.get("title"):
                        _live_last_pick.update({
                            "title": row["title"],
                            "type": row.get("type", "movie"),
                            "picked_at": _iso_utc(row.get("picked_at")),
                        })
                conn.close()
            except Exception:
                pass
            await _live_broadcast({"type": "update", **_live_snapshot()})
        except asyncio.CancelledError:
            break
        except Exception:
            await asyncio.sleep(10)


_live_bg_task = None


@app.on_event("startup")
async def _start_live_bg():
    global _live_bg_task
    _live_bg_task = asyncio.create_task(_live_bg_refresh())


@app.get("/api/live/stream")
async def live_stream(request: Request):
    """SSE endpoint for real-time live bar updates."""
    q: asyncio.Queue = asyncio.Queue(maxsize=50)
    _live_clients.add(q)

    # Send initial snapshot immediately
    init = json.dumps({"type": "init", **_live_snapshot()}, ensure_ascii=False, default=str)

    async def event_generator():
        try:
            yield f"data: {init}\n\n"
            while True:
                if await request.is_disconnected():
                    break
                try:
                    msg = await asyncio.wait_for(q.get(), timeout=15)
                    yield f"data: {msg}\n\n"
                except asyncio.TimeoutError:
                    # Keep-alive ping
                    yield f": ping\n\n"
        finally:
            _live_clients.discard(q)
            # Broadcast updated count after disconnect
            await _live_broadcast({"type": "update", **_live_snapshot()})

    return StreamingResponse(
        event_generator(),
        media_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "Connection": "keep-alive",
            "X-Accel-Buffering": "no",
        },
    )


@app.post("/api/live/pick")
async def live_pick_notify(request: Request):
    """Called after a pick to broadcast to all live bar clients."""
    try:
        body = await request.json()
        title = body.get("title", "")
        item_type = body.get("type", "movie")
        if title:
            _live_last_pick.update({
                "title": title,
                "type": item_type,
                "picked_at": datetime.datetime.utcnow().isoformat() + "Z",
            })
            await _live_broadcast({
                "type": "pick",
                **_live_snapshot(),
            })
    except Exception:
        pass
    return {"ok": True}


