@app.get("/api/me/stats")
async def my_stats(user=Depends(get_current_user)):
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT COUNT(*) AS c FROM pick_history WHERE user_id = %s", (user["id"],))
            total_picks = int((cur.fetchone() or {"c": 0})["c"])

            cur.execute(
                "SELECT type, COUNT(*) AS c FROM pick_history WHERE user_id = %s GROUP BY type",
                (user["id"],),
            )
            by_type_rows = cur.fetchall() or []
            by_type = {"movie": 0, "tv": 0, "book": 0}
            for r in by_type_rows:
                by_type[r["type"]] = int(r["c"])

            saved = {"movie": 0, "tv": 0, "book": 0}
            for tbl, key in (("saved_movies", "movie"), ("saved_tv", "tv"), ("saved_books", "book")):
                try:
                    cur.execute(f"SELECT COUNT(*) AS c FROM {tbl} WHERE user_id = %s", (user["id"],))
                    saved[key] = int((cur.fetchone() or {"c": 0})["c"])
                except Exception:
                    pass
        conn.close()
    except Exception:
        raise HTTPException(status_code=503, detail="Database unavailable")
    streak = _compute_streak(user["id"])
    return {
        "total_picks": total_picks,
        "picks_by_type": by_type,
        "saved": saved,
        "level": compute_level(total_picks),
        "streak": streak,
    }


