def _esc(s) -> str:
    """HTML-escape a value for safe interpolation into the template."""
    if s is None:
        return ""
    return html.escape(str(s), quote=True)


def _truncate(s: str, n: int = 200) -> str:
    s = s or ""
    if len(s) <= n:
        return s
    return s[: n - 1].rstrip() + "…"


def _build_share_html(
    title: str,
    description: str,
    poster: str,
    rating: str,
    year: str,
    type_label: str,
    genres_html: str,
    external_url: str,
    external_label: str,
    share_url: str,
    lang: str = "uk",
    rating_icon: str = "&#11088;",
    poster_class: str = "",
    footer_label: str = "Знайдено на",
    canonical_url: str = "",
):
    title_e = _esc(title or "")
    desc_e = _esc(description or "")
    desc_short = _esc(_truncate(description or "", 200))
    poster_e = _esc(poster or "")
    rating_e = _esc(rating or "—")
    year_e = _esc(year or "—")
    type_e = _esc(type_label or "")
    external_url_e = _esc(external_url or "/")
    external_label_e = _esc(external_label or "")
    share_url_e = _esc(share_url or "")
    footer_label_e = _esc(footer_label or "")
    poster_class_e = _esc(poster_class or "")

    if poster:
        # quote(' is safe inside attribute, poster URL is escaped
        card_bg_block = f'<div class="card-bg" style="background-image:url(&quot;{poster_e}&quot;)"></div>'
        poster_block = (
            f'<img class="poster {poster_class_e}" src="{poster_e}" alt="{title_e}" '
            f'loading="lazy" decoding="async" '
            f'onerror="this.style.display=\'none\'">'
        )
    else:
        card_bg_block = ""
        poster_block = ""

    replacements = {
        "{{LANG}}": _esc(lang or "uk"),
        "{{TITLE}}": title_e,
        "{{DESCRIPTION}}": desc_e,
        "{{DESCRIPTION_SHORT}}": desc_short,
        "{{POSTER}}": poster_e,
        "{{SHARE_URL}}": share_url_e,
        "{{CANONICAL_URL}}": _esc(canonical_url or share_url or ""),
        "{{RATING}}": rating_e,
        "{{RATING_ICON}}": rating_icon,
        "{{YEAR}}": year_e,
        "{{TYPE_LABEL}}": type_e,
        "{{GENRES_HTML}}": genres_html or "",
        "{{EXTERNAL_URL}}": external_url_e,
        "{{EXTERNAL_LABEL}}": external_label_e,
        "{{CARD_BG_BLOCK}}": card_bg_block,
        "{{POSTER_BLOCK}}": poster_block,
        "{{FOOTER_LABEL}}": footer_label_e,
        "{{OG_LOCALE}}": "en_US" if lang == "en" else "uk_UA",
    }
    out = SHARE_HTML
    for k, v in replacements.items():
        out = out.replace(k, v)
    return out


def _share_host() -> str:
    host = os.getenv("SITE_HOST", "picksy.my").strip().rstrip("/")
    if host.startswith("https://"):
        host = host[8:]
    elif host.startswith("http://"):
        host = host[7:]
    return host


def _footer_label(lang: str) -> str:
    return "Found on" if lang == "en" else "Знайдено на"


@app.get("/movie/{movie_id}", response_class=HTMLResponse)
async def share_movie(movie_id: int, lang: str = "uk"):
    if not TMDB_API_KEY:
        return HTMLResponse(_error_page_html(503, "Сервіс недоступний", "TMDB API не налаштовано.", "⚙️"), status_code=503)

    language = "uk-UA" if lang == "uk" else "en-US"
    try:
        async with httpx.AsyncClient(timeout=15) as client:
            resp = await client.get(
                f"https://api.themoviedb.org/3/movie/{movie_id}",
                params=_tmdb_params({"language": language}),
                headers=_tmdb_headers(),
            )
            if resp.status_code != 200:
                return HTMLResponse(_error_page_html(404, "Фільм не знайдено" if lang == "uk" else "Movie Not Found", "Такого фільму не існує." if lang == "uk" else "This movie does not exist.", "🎬"), status_code=404)
            m = resp.json()
    except Exception:
        return HTMLResponse(_error_page_html(500, "Помилка завантаження", "Не вдалося завантажити фільм.", "⚠️"), status_code=500)

    poster = f"https://image.tmdb.org/t/p/w500{m.get('poster_path')}" if m.get("poster_path") else ""
    genres = "".join(
        f'<span class="genre-tag">{_esc(g.get("name", ""))}</span>'
        for g in (m.get("genres") or [])[:4]
    )
    rating = str(round(m.get("vote_average", 0) or 0, 1))
    year = (m.get("release_date") or "")[:4] or "—"
    type_label = "Фільм" if lang == "uk" else "Film"
    host = _share_host()

    return HTMLResponse(_build_share_html(
        title=m.get("title") or m.get("original_title", ""),
        description=m.get("overview", ""),
        poster=poster,
        rating=rating,
        year=year,
        type_label=type_label,
        genres_html=genres,
        external_url=f"https://www.themoviedb.org/movie/{movie_id}",
        external_label="TMDB",
        share_url=f"https://{host}/movie/{movie_id}",
        lang=lang,
        footer_label=_footer_label(lang),
        canonical_url=f"https://{host}/descmovie/{movie_id}",
    ))


