    language = "uk-UA" if lang == "uk" else "en-US"
    try:
        async with httpx.AsyncClient(timeout=15) as client:
            resp = await client.get(
                f"https://api.themoviedb.org/3/tv/{tv_id}",
                params=_tmdb_params({"language": language}),
                headers=_tmdb_headers(),
            )
            if resp.status_code != 200:
                return HTMLResponse(_error_page_html(404, "Серіал не знайдено" if lang == "uk" else "TV Show Not Found", "Такого серіалу не існує." if lang == "uk" else "This TV show does not exist.", "📺"), status_code=404)
            t = resp.json()
    except Exception:
        return HTMLResponse(_error_page_html(500, "Помилка завантаження", "Не вдалося завантажити серіал.", "⚠️"), status_code=500)

    poster = f"https://image.tmdb.org/t/p/w500{t.get('poster_path')}" if t.get("poster_path") else ""
