def _build_detail_html(
    *,
    page_title: str,
    og_title: str,
    og_desc: str,
    og_image: str,
    og_url: str,
    body_html: str,
    lang: str = "uk",
    json_ld: str = "",
) -> str:
    og_locale = "en_US" if lang == "en" else "uk_UA"
    json_ld_tag = f'\n<script type="application/ld+json">{json_ld}</script>' if json_ld else ""
    return f"""<!DOCTYPE html>
<html lang="{_esc(lang)}">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1.0">
<title>{_esc(page_title)} — Picksy</title>
<meta name="description" content="{_esc(og_desc[:200])}">
<meta name="author" content="Вадим Мосорук (Vadym Mosoruk)">
<meta name="creator" content="Вадим Мосорук (Vadym Mosoruk)">
<meta name="publisher" content="Picksy — Вадим Мосорук">
<meta name="robots" content="index, follow">
<link rel="canonical" href="{_esc(og_url)}">
<meta property="og:title" content="{_esc(og_title)}">
<meta property="og:description" content="{_esc(og_desc[:200])}">
<meta property="og:type" content="website">
<meta property="og:url" content="{_esc(og_url)}">
<meta property="og:site_name" content="Picksy">
<meta property="og:locale" content="{og_locale}">
<meta property="og:image" content="{_esc(og_image)}">
<meta property="og:image:width" content="500">
<meta property="og:image:height" content="750">
<meta name="twitter:card" content="summary_large_image">
<meta name="twitter:site" content="@itspicksy">
<meta name="twitter:title" content="{_esc(og_title)}">
<meta name="twitter:description" content="{_esc(og_desc[:200])}">
<meta name="twitter:image" content="{_esc(og_image)}">{json_ld_tag}
<meta name="theme-color" content="#060614">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;800&display=swap" rel="stylesheet">
<style>{_detail_page_css()}</style>
</head>
<body>
<div class="detail-wrap">
<a class="detail-back" href="/">&#8592; {'На головну' if lang == 'uk' else 'Back to Picksy'}</a>
{body_html}
</div>
</body>
</html>"""


@app.get("/descmovie/{movie_id}", response_class=HTMLResponse)
async def detail_movie_page(movie_id: int, lang: str = "uk"):
    if not TMDB_API_KEY:
        return HTMLResponse(_error_page_html(503, "Сервіс недоступний", "TMDB API не налаштовано.", "⚙️"), status_code=503)

    language = "uk-UA" if lang == "uk" else "en-US"
    try:
        async with httpx.AsyncClient(timeout=15) as client:
            detail_resp, credits_resp, videos_resp, similar_resp, reviews_resp = await _gather_tmdb(
                client, "movie", movie_id, language
            )
    except Exception:
        return HTMLResponse(_error_page_html(500, "Помилка завантаження", "Не вдалося завантажити фільм.", "⚠️"), status_code=500)

    if not detail_resp or detail_resp.status_code != 200:
        return HTMLResponse(_error_page_html(404, "Фільм не знайдено" if lang == "uk" else "Movie Not Found", "", "🎬"), status_code=404)

    d = detail_resp.json()
    isUk = lang == "uk"
    title = _esc(d.get("title") or d.get("original_title") or "")
    overview = _esc(d.get("overview") or "")
    poster = f"https://image.tmdb.org/t/p/w500{d['poster_path']}" if d.get("poster_path") else ""
    backdrop = f"https://image.tmdb.org/t/p/w1280{d['backdrop_path']}" if d.get("backdrop_path") else ""
    year = (d.get("release_date") or "")[:4] or "—"
    rating = round(d.get("vote_average", 0) or 0, 1)
    runtime = d.get("runtime") or 0
    budget = d.get("budget") or 0
    revenue = d.get("revenue") or 0
    tagline = _esc(d.get("tagline") or "")
    status = _esc(d.get("status") or "")
    genres = d.get("genres") or []
    countries = [c.get("name", "") for c in (d.get("production_countries") or [])]
    languages_list = [l.get("english_name") or l.get("name", "") for l in (d.get("spoken_languages") or [])]

    # Cast & crew
    cast = []
    directors = []
    if credits_resp and credits_resp.status_code == 200:
        cr = credits_resp.json()
        for p in (cr.get("cast") or [])[:15]:
            cast.append({"name": p.get("name", ""), "character": p.get("character", ""), "photo": f"https://image.tmdb.org/t/p/w185{p['profile_path']}" if p.get("profile_path") else ""})
        for p in (cr.get("crew") or []):
            if p.get("job") == "Director":
                directors.append(p.get("name", ""))

    # Videos
    trailers = []
    if videos_resp and videos_resp.status_code == 200:
        for v in (videos_resp.json().get("results") or []):
            if v.get("site") == "YouTube":
                trailers.append({"key": v["key"], "name": v.get("name", ""), "type": v.get("type", "")})

    # Similar
    similar = []
    if similar_resp and similar_resp.status_code == 200:
        for s in (similar_resp.json().get("results") or [])[:10]:
            similar.append({"id": s.get("id"), "title": s.get("title") or s.get("name") or "", "poster": f"https://image.tmdb.org/t/p/w185{s['poster_path']}" if s.get("poster_path") else ""})

    # TMDB reviews
    tmdb_reviews = []
    if reviews_resp and reviews_resp.status_code == 200:
        for r in (reviews_resp.json().get("results") or [])[:5]:
            tmdb_reviews.append({"author": r.get("author", ""), "content": (r.get("content") or "")[:500], "rating": (r.get("author_details") or {}).get("rating")})

    host = _share_host()

    # Build body HTML
    body = ""
    if backdrop:
        body += f'<img class="detail-backdrop" src="{_esc(backdrop)}" alt="" loading="lazy" onerror="this.style.display=\'none\'">'
    else:
        body += '<div class="detail-backdrop-placeholder"></div>'

    body += '<div class="detail-main">'
    if poster:
        body += f'<img class="detail-poster" src="{_esc(poster)}" alt="{title}" loading="lazy">'
    body += '<div class="detail-header">'
    body += f'<h1 class="detail-title">{title}</h1>'
    if tagline:
        body += f'<div class="detail-tagline">{tagline}</div>'
    body += '<div class="detail-badges">'
    body += f'<span class="detail-badge detail-badge-rating">&#11088; {rating}</span>'
    body += f'<span class="detail-badge detail-badge-year">&#128197; {_esc(year)}</span>'
    if runtime:
        body += f'<span class="detail-badge detail-badge-runtime">&#9201; {runtime} {"хв" if isUk else "min"}</span>'
    if (d.get("original_language") or "") == "uk":
        body += f'<span class="detail-badge detail-badge-ua" title="{"Український оригінал" if isUk else "Ukrainian original"}">&#127482;&#127462; UA</span>'
    body += '</div></div></div>'

    # Genres
    if genres:
        body += '<div class="detail-genres">'
        for g in genres:
            body += f'<span class="detail-genre-tag">{_esc(g.get("name", ""))}</span>'
        body += '</div>'

    # Actions
    body += '<div class="detail-actions">'
    body += f'<a class="detail-action-btn detail-action-secondary" href="https://www.themoviedb.org/movie/{movie_id}" target="_blank">TMDB</a>'
    body += f'<a class="detail-action-btn detail-action-secondary" href="https://{_esc(host)}/movie/{movie_id}" target="_blank">{"Поділитися" if isUk else "Share"}</a>'
    body += f'<a class="detail-action-btn detail-action-primary" href="/">{"На Picksy" if isUk else "Back to Picksy"}</a>'
    body += '</div>'

    # Overview
    if overview:
        body += f'<div class="detail-overview"><p>{overview}</p></div>'

    # Meta grid
    body += '<div class="detail-meta-grid">'
    if budget:
        body += f'<div class="detail-meta-item"><div class="detail-meta-label">{"Бюджет" if isUk else "Budget"}</div><div class="detail-meta-value">${budget/1000000:.1f}M</div></div>'
    if revenue:
        body += f'<div class="detail-meta-item"><div class="detail-meta-label">{"Касові збори" if isUk else "Revenue"}</div><div class="detail-meta-value">${revenue/1000000:.1f}M</div></div>'
    if status:
        body += f'<div class="detail-meta-item"><div class="detail-meta-label">{"Статус" if isUk else "Status"}</div><div class="detail-meta-value">{status}</div></div>'
    if countries:
        body += f'<div class="detail-meta-item"><div class="detail-meta-label">{"Країна" if isUk else "Country"}</div><div class="detail-meta-value">{_esc(", ".join(countries))}</div></div>'
    if languages_list:
        body += f'<div class="detail-meta-item"><div class="detail-meta-label">{"Мови" if isUk else "Languages"}</div><div class="detail-meta-value">{_esc(", ".join(languages_list))}</div></div>'
    body += '</div>'

    # Directors
    if directors:
        body += '<div class="detail-directors">'
        for dn in directors:
            body += f'<span class="detail-director-tag">&#127916; {_esc(dn)}</span>'
        body += '</div>'

    # Cast
    if cast:
        body += f'<div class="detail-section"><div class="detail-section-title">&#127917; {"Актори" if isUk else "Cast"}</div><div class="detail-cast-scroll">'
        for p in cast:
            if p["photo"]:
                body += f'<div class="detail-cast-card"><img class="detail-cast-photo" src="{_esc(p["photo"])}" alt="{_esc(p["name"])}" loading="lazy"><div class="detail-cast-name">{_esc(p["name"])}</div><div class="detail-cast-character">{_esc(p["character"])}</div></div>'
            else:
                body += f'<div class="detail-cast-card"><div class="detail-cast-photo-placeholder">&#128100;</div><div class="detail-cast-name">{_esc(p["name"])}</div><div class="detail-cast-character">{_esc(p["character"])}</div></div>'
        body += '</div></div>'

    # Trailer
    if trailers:
        trailer = next((t for t in trailers if t["type"] == "Trailer"), trailers[0])
        body += f'<div class="detail-section"><div class="detail-section-title">&#9654; {"Трейлер" if isUk else "Trailer"}</div>'
        body += f'<div class="detail-trailer-wrap"><iframe src="https://www.youtube.com/embed/{_esc(trailer["key"])}" allowfullscreen allow="autoplay" loading="lazy"></iframe></div></div>'

    # Similar
    if similar:
        body += f'<div class="detail-section"><div class="detail-section-title">{"Схожі фільми" if isUk else "Similar Movies"}</div><div class="detail-similar-scroll">'
        for s in similar:
            body += f'<a class="detail-similar-card" href="/descmovie/{s["id"]}?lang={lang}">'
            if s["poster"]:
                body += f'<img class="detail-similar-poster" src="{_esc(s["poster"])}" alt="{_esc(s["title"])}" loading="lazy">'
            body += f'<div class="detail-similar-title">{_esc(s["title"])}</div></a>'
        body += '</div></div>'

    # Reviews
    if tmdb_reviews:
        body += f'<div class="detail-section"><div class="detail-section-title">&#128172; {"Відгуки" if isUk else "Reviews"}</div>'
        for r in tmdb_reviews:
            body += f'<div class="detail-review-card"><div class="detail-review-author">{_esc(r["author"])}</div>'
            if r["rating"]:
                body += f'<div class="detail-review-rating">&#11088; {r["rating"]}/10</div>'
            body += f'<div class="detail-review-text">{_esc(r["content"])}</div></div>'
        body += '</div>'

    # Picksy AI analysis button — deep link passes movie ID for auto-analysis
    _tg_link = f"https://t.me/PicksySupportBot?start=analyze_movie_{movie_id}"
    _ai_label = "AI-аналіз цього фільму" if isUk else "AI analysis of this movie"
    _ai_hint = "Дізнайся кому підходить по архетипах, коли краще дивитися та отримай персональну пораду" if isUk else "Find out who it suits by archetypes, when to watch and get a personal recommendation"
    _ai_cta = "Відкрити в Telegram" if isUk else "Open in Telegram"
    body += f'''<div class="detail-section" style="text-align:center;padding:0;margin:24px 0;position:relative;overflow:hidden;border-radius:24px;border:1px solid rgba(139,92,246,.25);background:linear-gradient(160deg,#0d0b1a 0%,#1a1040 40%,#0f1a3d 100%)">
<style>@keyframes _ai_float{{0%,100%{{transform:translateY(0)}}50%{{transform:translateY(-8px)}}}}@keyframes _ai_shimmer{{0%{{background-position:-200% 0}}100%{{background-position:200% 0}}}}</style>
<div style="position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,transparent,#8b5cf6,#3b82f6,#8b5cf6,transparent);background-size:200% 100%;animation:_ai_shimmer 3s linear infinite"></div>
<div style="position:absolute;top:-40px;right:-40px;width:120px;height:120px;background:radial-gradient(circle,rgba(139,92,246,.2),transparent 70%);pointer-events:none"></div>
<div style="position:absolute;bottom:-30px;left:-30px;width:100px;height:100px;background:radial-gradient(circle,rgba(59,130,246,.15),transparent 70%);pointer-events:none"></div>
<div style="padding:28px 20px 24px;display:flex;flex-direction:column;align-items:center;gap:12px">
<img src="/og/picksy-mascot.svg" alt="Picksy AI" style="width:64px;height:64px;animation:_ai_float 3s ease-in-out infinite;filter:drop-shadow(0 4px 12px rgba(139,92,246,.4))">
<div style="font-size:1.35rem;font-weight:900;background:linear-gradient(135deg,#c084fc,#818cf8,#60a5fa);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text">Picksy AI</div>
<div style="font-size:.9rem;color:rgba(255,255,255,.7);line-height:1.5;max-width:320px">{_ai_hint}</div>
<a href="{_tg_link}" target="_blank" rel="noopener" style="display:inline-flex;align-items:center;gap:10px;padding:14px 32px;margin-top:4px;border-radius:14px;background:linear-gradient(135deg,#8b5cf6,#6366f1,#3b82f6);color:#fff;text-decoration:none;font-weight:800;font-size:1.05rem;box-shadow:0 4px 24px rgba(139,92,246,.4),inset 0 1px 0 rgba(255,255,255,.15);transition:transform .2s,box-shadow .2s;letter-spacing:.3px;position:relative;overflow:hidden"
   onmouseover="this.style.transform='scale(1.05) translateY(-2px)';this.style.boxShadow='0 8px 32px rgba(139,92,246,.55),inset 0 1px 0 rgba(255,255,255,.15)'" onmouseout="this.style.transform='scale(1)';this.style.boxShadow='0 4px 24px rgba(139,92,246,.4),inset 0 1px 0 rgba(255,255,255,.15)'"
><svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor" style="flex-shrink:0"><path d="M12 0C5.37 0 0 5.37 0 12s5.37 12 12 12 12-5.37 12-12S18.63 0 12 0zm5.94 8.13l-1.97 9.28c-.15.67-.54.83-1.09.52l-3.02-2.22-1.46 1.4c-.16.16-.3.3-.61.3l.22-3.06 5.56-5.02c.24-.22-.05-.33-.38-.13L8.69 13.7l-2.97-.93c-.64-.2-.66-.64.14-.95l11.6-4.47c.53-.2 1 .13.83.95l-.35-.17z"/></svg>
{_ai_cta}</a>
<div style="font-size:.78rem;color:rgba(255,255,255,.35);margin-top:2px">{_ai_label}</div>
</div>
</div>'''

    _movie_ld = json.dumps({
        "@context": "https://schema.org",
        "@type": "Movie",
        "name": d.get("title") or d.get("original_title") or "",
        "description": (d.get("overview") or "")[:500],
        "image": poster,
        "datePublished": d.get("release_date") or "",
        "aggregateRating": {"@type": "AggregateRating", "ratingValue": str(rating), "bestRating": "10", "ratingCount": str(d.get("vote_count", 0))},
        "genre": [g.get("name", "") for g in genres],
        "director": [{"@type": "Person", "name": dn} for dn in directors] if directors else [],
        "url": f"https://{host}/descmovie/{movie_id}",
    }, ensure_ascii=False)

    return HTMLResponse(_build_detail_html(
        page_title=d.get("title") or d.get("original_title") or "",
        og_title=f"{d.get('title', '')} — Picksy",
        og_desc=d.get("overview") or "",
        og_image=poster,
        og_url=f"https://{host}/descmovie/{movie_id}",
        body_html=body,
        lang=lang,
        json_ld=_movie_ld,
    ))


@app.get("/desctv/{tv_id}", response_class=HTMLResponse)
async def detail_tv_page(tv_id: int, lang: str = "uk"):
    if not TMDB_API_KEY:
        return HTMLResponse(_error_page_html(503, "Сервіс недоступний", "TMDB API не налаштовано.", "⚙️"), status_code=503)

    language = "uk-UA" if lang == "uk" else "en-US"
    try:
        async with httpx.AsyncClient(timeout=15) as client:
            detail_resp, credits_resp, videos_resp, similar_resp, reviews_resp = await _gather_tmdb(
                client, "tv", tv_id, language
            )
    except Exception:
        return HTMLResponse(_error_page_html(500, "Помилка завантаження", "Не вдалося завантажити серіал.", "⚠️"), status_code=500)

    if not detail_resp or detail_resp.status_code != 200:
        return HTMLResponse(_error_page_html(404, "Серіал не знайдено" if lang == "uk" else "TV Show Not Found", "", "📺"), status_code=404)

    d = detail_resp.json()
    isUk = lang == "uk"
    title = _esc(d.get("name") or d.get("original_name") or "")
    overview = _esc(d.get("overview") or "")
    poster = f"https://image.tmdb.org/t/p/w500{d['poster_path']}" if d.get("poster_path") else ""
    backdrop = f"https://image.tmdb.org/t/p/w1280{d['backdrop_path']}" if d.get("backdrop_path") else ""
    year = (d.get("first_air_date") or "")[:4] or "—"
    rating = round(d.get("vote_average", 0) or 0, 1)
    tagline = _esc(d.get("tagline") or "")
    status_raw = d.get("status") or ""
    n_seasons = d.get("number_of_seasons") or 0
    n_episodes = d.get("number_of_episodes") or 0
    in_production = d.get("in_production", False)
    genres = d.get("genres") or []
    networks = [n.get("name", "") for n in (d.get("networks") or [])]
    created_by = [c.get("name", "") for c in (d.get("created_by") or [])]
    seasons_data = d.get("seasons") or []

    status_map = {
        "Returning Series": "Продовжується" if isUk else "Returning",
        "Ended": "Завершено" if isUk else "Ended",
        "Canceled": "Скасовано" if isUk else "Canceled",
        "In Production": "У виробництві" if isUk else "In Production",
        "Planned": "Заплановано" if isUk else "Planned",
    }
    status_label = status_map.get(status_raw, status_raw)
    is_ended = status_raw in ("Ended", "Canceled")

    # Cast & crew
    cast = []
    directors = []
    if credits_resp and credits_resp.status_code == 200:
        cr = credits_resp.json()
        for p in (cr.get("cast") or [])[:15]:
            cast.append({"name": p.get("name", ""), "character": p.get("character", ""), "photo": f"https://image.tmdb.org/t/p/w185{p['profile_path']}" if p.get("profile_path") else ""})

    # Videos
    trailers = []
    if videos_resp and videos_resp.status_code == 200:
        for v in (videos_resp.json().get("results") or []):
            if v.get("site") == "YouTube":
                trailers.append({"key": v["key"], "name": v.get("name", ""), "type": v.get("type", "")})

    # Similar
    similar = []
    if similar_resp and similar_resp.status_code == 200:
        for s in (similar_resp.json().get("results") or [])[:10]:
            similar.append({"id": s.get("id"), "title": s.get("name") or s.get("title") or "", "poster": f"https://image.tmdb.org/t/p/w185{s['poster_path']}" if s.get("poster_path") else ""})

    # TMDB reviews
    tmdb_reviews = []
    if reviews_resp and reviews_resp.status_code == 200:
        for r in (reviews_resp.json().get("results") or [])[:5]:
            tmdb_reviews.append({"author": r.get("author", ""), "content": (r.get("content") or "")[:500], "rating": (r.get("author_details") or {}).get("rating")})

    host = _share_host()

    # Build body HTML
    body = ""
    if backdrop:
        body += f'<img class="detail-backdrop" src="{_esc(backdrop)}" alt="" loading="lazy" onerror="this.style.display=\'none\'">'
    else:
        body += '<div class="detail-backdrop-placeholder"></div>'

    body += '<div class="detail-main">'
    if poster:
        body += f'<img class="detail-poster" src="{_esc(poster)}" alt="{title}" loading="lazy">'
    body += '<div class="detail-header">'
    body += f'<h1 class="detail-title">{title}</h1>'
    if tagline:
        body += f'<div class="detail-tagline">{tagline}</div>'
    body += '<div class="detail-badges">'
    body += f'<span class="detail-badge detail-badge-rating">&#11088; {rating}</span>'
    body += f'<span class="detail-badge detail-badge-year">&#128197; {_esc(year)}</span>'
    if n_seasons:
        body += f'<span class="detail-badge detail-badge-runtime">&#128250; {n_seasons} {"сезонів" if isUk else "seasons"}</span>'
    if status_label:
        sc = "ended" if is_ended else "ongoing"
        icon = "&#127937;" if is_ended else "&#128225;"
        body += f'<span class="detail-badge detail-badge-status {sc}">{icon} {_esc(status_label)}</span>'
    if (d.get("original_language") or "") == "uk":
        body += f'<span class="detail-badge detail-badge-ua" title="{"Український оригінал" if isUk else "Ukrainian original"}">&#127482;&#127462; UA</span>'
    body += '</div></div></div>'

    # Genres
    if genres:
        body += '<div class="detail-genres">'
        for g in genres:
            body += f'<span class="detail-genre-tag">{_esc(g.get("name", ""))}</span>'
        body += '</div>'

    # Actions
    body += '<div class="detail-actions">'
    body += f'<a class="detail-action-btn detail-action-secondary" href="https://www.themoviedb.org/tv/{tv_id}" target="_blank">TMDB</a>'
    body += f'<a class="detail-action-btn detail-action-secondary" href="https://{_esc(host)}/tv/{tv_id}" target="_blank">{"Поділитися" if isUk else "Share"}</a>'
    body += f'<a class="detail-action-btn detail-action-primary" href="/">{"На Picksy" if isUk else "Back to Picksy"}</a>'
    body += '</div>'

    # Overview
    if overview:
        body += f'<div class="detail-overview"><p>{overview}</p></div>'

    # Seasons progress bar
    regular_seasons = [s for s in seasons_data if s.get("season_number", 0) > 0]
    if regular_seasons:
        total_ep = sum(s.get("episode_count", 0) for s in regular_seasons)
        body += '<div class="detail-seasons-section">'
        body += '<div class="detail-seasons-header">'
        body += f'<span class="detail-seasons-stat">{n_seasons} {"сезонів" if isUk else "seasons"}</span>'
        body += f'<span class="detail-seasons-stat">{n_episodes} {"епізодів" if isUk else "episodes"}</span>'
        body += '</div>'
        body += '<div class="detail-seasons-bar">'
        from datetime import datetime as _dt
        now = _dt.now()
        for s in regular_seasons:
            ep = s.get("episode_count", 0)
            pct = (ep / total_ep * 100) if total_ep > 0 else 0
            air = s.get("air_date") or ""
            aired = bool(air and _dt.strptime(air[:10], "%Y-%m-%d") <= now) if air and len(air) >= 10 else False
            seg_class = "aired" if aired else "upcoming"
            s_year = air[:4] if air else ""
            body += f'<div class="detail-season-seg {seg_class}" style="width:{pct:.1f}%" title="S{s["season_number"]}: {ep} {"еп." if isUk else "ep."}{" (" + s_year + ")" if s_year else ""}">'
            body += f'<span class="detail-season-seg-label">S{s["season_number"]}</span>'
            body += '</div>'
        body += '</div>'
        body += '<div class="detail-seasons-legend">'
        for s in regular_seasons:
            s_year = (s.get("air_date") or "")[:4]
            body += f'<div class="detail-season-legend-item"><strong>S{s["season_number"]}</strong>: {s.get("episode_count", 0)} {"еп." if isUk else "ep."}'
            if s_year:
                body += f' ({s_year})'
            body += '</div>'
        body += '</div></div>'

    # Meta grid
    body += '<div class="detail-meta-grid">'
    if networks:
        body += f'<div class="detail-meta-item"><div class="detail-meta-label">{"Мережа" if isUk else "Network"}</div><div class="detail-meta-value">{_esc(", ".join(networks))}</div></div>'
    if created_by:
        body += f'<div class="detail-meta-item"><div class="detail-meta-label">{"Автор" if isUk else "Created by"}</div><div class="detail-meta-value">{_esc(", ".join(created_by))}</div></div>'
    body += '</div>'

    # Cast
    if cast:
        body += f'<div class="detail-section"><div class="detail-section-title">&#127917; {"Актори" if isUk else "Cast"}</div><div class="detail-cast-scroll">'
        for p in cast:
            if p["photo"]:
                body += f'<div class="detail-cast-card"><img class="detail-cast-photo" src="{_esc(p["photo"])}" alt="{_esc(p["name"])}" loading="lazy"><div class="detail-cast-name">{_esc(p["name"])}</div><div class="detail-cast-character">{_esc(p["character"])}</div></div>'
            else:
                body += f'<div class="detail-cast-card"><div class="detail-cast-photo-placeholder">&#128100;</div><div class="detail-cast-name">{_esc(p["name"])}</div><div class="detail-cast-character">{_esc(p["character"])}</div></div>'
        body += '</div></div>'

    # Trailer
    if trailers:
        trailer = next((t for t in trailers if t["type"] == "Trailer"), trailers[0])
        body += f'<div class="detail-section"><div class="detail-section-title">&#9654; {"Трейлер" if isUk else "Trailer"}</div>'
        body += f'<div class="detail-trailer-wrap"><iframe src="https://www.youtube.com/embed/{_esc(trailer["key"])}" allowfullscreen allow="autoplay" loading="lazy"></iframe></div></div>'

    # Similar
    if similar:
        body += f'<div class="detail-section"><div class="detail-section-title">{"Схожі серіали" if isUk else "Similar TV Shows"}</div><div class="detail-similar-scroll">'
        for s in similar:
            body += f'<a class="detail-similar-card" href="/desctv/{s["id"]}?lang={lang}">'
            if s["poster"]:
                body += f'<img class="detail-similar-poster" src="{_esc(s["poster"])}" alt="{_esc(s["title"])}" loading="lazy">'
            body += f'<div class="detail-similar-title">{_esc(s["title"])}</div></a>'
        body += '</div></div>'

    # Reviews
    if tmdb_reviews:
        body += f'<div class="detail-section"><div class="detail-section-title">&#128172; {"Відгуки" if isUk else "Reviews"}</div>'
        for r in tmdb_reviews:
            body += f'<div class="detail-review-card"><div class="detail-review-author">{_esc(r["author"])}</div>'
            if r["rating"]:
                body += f'<div class="detail-review-rating">&#11088; {r["rating"]}/10</div>'
            body += f'<div class="detail-review-text">{_esc(r["content"])}</div></div>'
        body += '</div>'

    # Picksy AI analysis button for TV shows — deep link passes TV ID
    _tg_link_tv = f"https://t.me/PicksySupportBot?start=analyze_tv_{tv_id}"
