class ShowcaseBadgesRequest(BaseModel):
    badge_ids: list[str] = []

@app.post("/api/me/showcase-badges")
async def set_my_showcase_badges(req: ShowcaseBadgesRequest, user=Depends(get_current_user)):
    badge_ids = list(req.badge_ids or [])
    # Free tier (when freemium enabled) is limited to 1 showcase badge; Premium/Pro get 5.
    _max = 5
    if get_site_settings().get("freemium_enabled", False):
        _tier = get_user_tier(user["id"])
        if _tier not in ("premium", "pro"):
            _max = 1
    if len(badge_ids) > _max:
        badge_ids = badge_ids[:_max]
    # Sanitize
    badge_ids = [str(b)[:64] for b in badge_ids if b]
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("DELETE FROM user_showcase_badges WHERE user_id=%s", (user["id"],))
            for idx, bid in enumerate(badge_ids):
                cur.execute(
                    "INSERT INTO user_showcase_badges (user_id, badge_id, sort_order) VALUES (%s,%s,%s)",
                    (user["id"], bid, idx),
                )
            conn.commit()
        conn.close()
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))
    return {"ok": True, "badges": badge_ids}


