# ─── Activity Log Helper ───
def _log_activity(user_id: int | None, action: str, detail: str = "", ip: str = ""):
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute(
                "INSERT INTO activity_log (user_id, action, detail, ip) VALUES (%s, %s, %s, %s)",
                (user_id, action, detail[:500] if detail else "", ip),
            )
            conn.commit()
        conn.close()
    except Exception:
        pass


