def _check_achievements(user_id: int) -> list[dict]:
    earned = []
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT COUNT(*) AS c FROM pick_history WHERE user_id = %s", (user_id,))
            total_picks = (cur.fetchone() or {}).get("c", 0)
            cur.execute("SELECT COUNT(*) AS c FROM saved_movies WHERE user_id = %s", (user_id,))
            sm = (cur.fetchone() or {}).get("c", 0)
            cur.execute("SELECT COUNT(*) AS c FROM saved_tv WHERE user_id = %s", (user_id,))
            st = (cur.fetchone() or {}).get("c", 0)
            cur.execute("SELECT COUNT(*) AS c FROM saved_books WHERE user_id = %s", (user_id,))
            sb = (cur.fetchone() or {}).get("c", 0)
            total_saved = sm + st + sb
            streak = _compute_streak(user_id)
            cur.execute("SELECT COUNT(DISTINCT type) AS c FROM pick_history WHERE user_id = %s", (user_id,))
            types_count = (cur.fetchone() or {}).get("c", 0)
            cur.execute("SELECT ai_search_count FROM user_stats WHERE user_id = %s", (user_id,))
            ai_row = cur.fetchone()
            ai_count = (ai_row or {}).get("ai_search_count", 0)
        conn.close()

        checks = {
            "first_pick": total_picks >= 1,
            "pick_10": total_picks >= 10,
            "pick_50": total_picks >= 50,
            "pick_100": total_picks >= 100,
            "pick_500": total_picks >= 500,
            "save_5": total_saved >= 5,
            "save_25": total_saved >= 25,
            "save_100": total_saved >= 100,
            "streak_3": streak.get("best_streak", 0) >= 3,
            "streak_7": streak.get("best_streak", 0) >= 7,
            "streak_30": streak.get("best_streak", 0) >= 30,
            "all_types": types_count >= 3,
            "ai_user": ai_count >= 1,
        }
        for a in ACHIEVEMENTS:
            earned.append({**a, "earned": checks.get(a["id"], False)})
    except Exception:
        earned = [{**a, "earned": False} for a in ACHIEVEMENTS]
    return earned


@app.get("/api/me/achievements")
async def my_achievements(user=Depends(get_current_user)):
    if not get_site_settings().get("achievements_enabled", True):
        return []
    return _check_achievements(user["id"])


# ─── Announcements (public) ───
@app.get("/api/announcements")
async def get_announcements():
    try:
        conn = get_db()
        with conn.cursor() as cur:
            # Ensure closeable column exists
            try:
                cur.execute("ALTER TABLE announcements ADD COLUMN closeable TINYINT(1) NOT NULL DEFAULT 1")
            except Exception:
                pass
            cur.execute("SELECT id, message, type, closeable, created_at FROM announcements WHERE active = 1 ORDER BY id DESC LIMIT 5")
            rows = cur.fetchall() or []
        conn.close()
        return [{"id": r["id"], "message": r["message"], "type": r["type"], "closeable": bool(r.get("closeable", 1)), "created_at": str(r["created_at"])} for r in rows]
    except Exception:
        return []


# ─── Trending (TMDB) ───
@app.get("/api/trending")
async def trending(type: str = "movie", lang: str = "uk"):
    if not get_site_settings().get("trending_enabled", True):
        return []
    if not TMDB_API_KEY:
        return []
    media = "movie" if type != "tv" else "tv"
    try:
        async with httpx.AsyncClient(timeout=15) as client:
            params = {"language": lang, "page": 1}
            hdrs = {}
            if TMDB_IS_BEARER:
                hdrs["Authorization"] = f"Bearer {TMDB_API_KEY}"
            else:
                params["api_key"] = TMDB_API_KEY
            r = await client.get(f"https://api.themoviedb.org/3/trending/{media}/week", params=params, headers=hdrs)
            if r.status_code != 200:
                return []
            results = r.json().get("results", [])[:10]
            out = []
            for item in results:
                out.append({
                    "id": item.get("id"),
                    "title": item.get("title") or item.get("name", ""),
                    "poster": f"https://image.tmdb.org/t/p/w200{item['poster_path']}" if item.get("poster_path") else "",
                    "year": (item.get("release_date") or item.get("first_air_date") or "")[:4],
                    "release_date": item.get("release_date") or item.get("first_air_date") or "",
                    "rating": round(item.get("vote_average", 0), 1),
                    "description": item.get("overview", ""),
                    "url": f"https://www.themoviedb.org/{media}/{item.get('id', '')}",
                    "type": media,
                    "original_language": item.get("original_language", ""),
                })
            return out
    except Exception:
        return []


@app.get("/api/trending/detail")
async def trending_detail(id: int, type: str = "movie", lang: str = "uk"):
    """Fetch full details for a trending item (overview, genres, etc.)."""
    if not TMDB_API_KEY:
        raise HTTPException(status_code=503, detail="TMDB not configured")
    media = "movie" if type != "tv" else "tv"
    try:
        async with httpx.AsyncClient(timeout=10) as client:
            params = {"language": lang}
            hdrs = {}
            if TMDB_IS_BEARER:
                hdrs["Authorization"] = f"Bearer {TMDB_API_KEY}"
            else:
                params["api_key"] = TMDB_API_KEY
            r = await client.get(
                f"https://api.themoviedb.org/3/{media}/{id}",
                params=params, headers=hdrs,
            )
            if r.status_code != 200:
                # Fallback to English if Ukrainian overview is empty
                params["language"] = "en"
                r = await client.get(
                    f"https://api.themoviedb.org/3/{media}/{id}",
                    params=params, headers=hdrs,
                )
            if r.status_code != 200:
                raise HTTPException(status_code=404, detail="Not found")
            d = r.json()
            return {
                "overview": d.get("overview", ""),
                "vote_average": d.get("vote_average", 0),
                "genre_ids": [g["id"] for g in d.get("genres", [])],
                "release_date": d.get("release_date") or d.get("first_air_date", ""),
                "original_language": d.get("original_language", ""),
            }
    except HTTPException:
        raise
    except Exception:
        raise HTTPException(status_code=500, detail="Failed to fetch details")


