async def _fetch_random_movie():
    """Fetch a random popular movie from TMDB."""
    tmdb_id = random.choice(POPULAR_MOVIE_IDS)
    url = f"https://api.themoviedb.org/3/movie/{tmdb_id}"
    params = {"language": "uk-UA"}
    h = {}
    if TMDB_IS_BEARER:
        h["Authorization"] = f"Bearer {TMDB_API_KEY}"
    else:
        params["api_key"] = TMDB_API_KEY
    try:
        async with httpx.AsyncClient(timeout=8) as client:
            r = await client.get(url, params=params, headers=h)
            if r.status_code != 200:
                return None
            d = r.json()
            year = int(d.get("release_date", "2000")[:4]) if d.get("release_date") else 2000
            return {
                "title": d.get("title", "Unknown"),
                "poster": f"https://image.tmdb.org/t/p/w500{d['poster_path']}" if d.get("poster_path") else "",
                "year": year,
                "rating": round(d.get("vote_average", 5.0), 1),
            }
    except Exception:
        return None


# ─── Ranking System ───

GAME_RANKS = [
    {"name": "Бронза", "name_en": "Bronze", "icon": "🥉", "min_rating": 0, "color": "#cd7f32"},
    {"name": "Срібло", "name_en": "Silver", "icon": "🥈", "min_rating": 100, "color": "#c0c0c0"},
    {"name": "Золото", "name_en": "Gold", "icon": "🥇", "min_rating": 200, "color": "#ffd700"},
    {"name": "Діамант", "name_en": "Diamond", "icon": "💎", "min_rating": 350, "color": "#60a5fa"},
    {"name": "Майстер", "name_en": "Master", "icon": "👑", "min_rating": 500, "color": "#a78bfa"},
    {"name": "Легенда", "name_en": "Legend", "icon": "🏆", "min_rating": 750, "color": "#f59e0b"},
]


def _get_rank(rating: int) -> dict:
    rank = GAME_RANKS[0]
    for r in GAME_RANKS:
        if rating >= r["min_rating"]:
            rank = r
    return rank


def _get_next_rank(rating: int):
    for r in GAME_RANKS:
        if rating < r["min_rating"]:
            return r
    return None


@app.get("/api/game/rating")
async def game_get_rating(user=Depends(get_current_user)):
    if not get_site_settings().get("game_enabled", True):
        raise HTTPException(status_code=403, detail="Game disabled")
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT rating, wins, losses, draws, game_banned FROM game_ratings WHERE user_id=%s", (user["id"],))
            row = cur.fetchone()
            # Calculate win streak from recent matches
            win_streak = 0
            cur.execute(
                """SELECT winner_id FROM game_matches
                   WHERE (player1_id=%s OR player2_id=%s) AND status='finished'
                   ORDER BY created_at DESC LIMIT 20""",
                (user["id"], user["id"]),
            )
            for match in cur.fetchall() or []:
                if match["winner_id"] == user["id"]:
                    win_streak += 1
                else:
                    break
        conn.close()
        if row:
            rating = row["rating"]
            rank = _get_rank(rating)
            next_rank = _get_next_rank(rating)
            return {"rating": rating, "wins": row["wins"], "losses": row["losses"], "draws": row["draws"], "game_banned": bool(row.get("game_banned", 0)), "win_streak": win_streak, "rank": rank, "next_rank": next_rank}
        rank = _get_rank(100)
        return {"rating": 100, "wins": 0, "losses": 0, "draws": 0, "game_banned": False, "win_streak": 0, "rank": rank, "next_rank": _get_next_rank(100)}
    except Exception:
        rank = _get_rank(100)
        return {"rating": 100, "wins": 0, "losses": 0, "draws": 0, "game_banned": False, "win_streak": 0, "rank": rank, "next_rank": _get_next_rank(100)}


@app.get("/api/game/leaderboard")
async def game_leaderboard(user=Depends(get_current_user)):
    if not get_site_settings().get("game_enabled", True):
        raise HTTPException(status_code=403, detail="Game disabled")
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("""
                SELECT u.username, u.avatar_emoji, g.rating, g.wins, g.losses, g.draws, g.user_id
                FROM game_ratings g JOIN users u ON g.user_id = u.id
                ORDER BY g.rating DESC LIMIT 20
            """)
            rows = cur.fetchall() or []
            # Calculate win streaks for top players
            result = []
            for r in rows:
                streak = 0
                cur.execute(
                    """SELECT winner_id FROM game_matches
                       WHERE (player1_id=%s OR player2_id=%s) AND status='finished'
                       ORDER BY created_at DESC LIMIT 10""",
                    (r["user_id"], r["user_id"]),
                )
                for m in cur.fetchall() or []:
                    if m["winner_id"] == r["user_id"]:
                        streak += 1
                    else:
                        break
                rank = _get_rank(r["rating"])
                result.append({
                    "username": r["username"],
                    "avatar_emoji": r["avatar_emoji"],
                    "rating": r["rating"],
                    "wins": r["wins"],
                    "losses": r["losses"],
                    "draws": r["draws"],
                    "win_streak": streak,
                    "rank": rank,
                })
        conn.close()
        return result
    except Exception:
        return []


@app.post("/api/game/find")
async def game_find_match(user=Depends(get_current_user)):
    """Find or create a game match."""
    if not get_site_settings().get("game_enabled", True):
        raise HTTPException(status_code=403, detail="Game disabled")
    # Check game ban
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT game_banned FROM game_ratings WHERE user_id=%s", (user["id"],))
            row = cur.fetchone()
        conn.close()
        if row and row.get("game_banned"):
            raise HTTPException(status_code=403, detail="Вас забанено в грі")
    except HTTPException:
        raise
    except Exception:
        pass
    try:
        conn = get_db()
        with conn.cursor() as cur:
            # Cleanup stale waiting matches (older than 5 minutes)
            cur.execute(
                "DELETE FROM game_matches WHERE status='waiting' AND created_at < %s",
                (datetime.datetime.utcnow() - datetime.timedelta(minutes=5),),
            )
            # Check if player already has an active match
            cur.execute(
                "SELECT id, status FROM game_matches WHERE (player1_id=%s OR player2_id=%s) AND status IN ('waiting','playing','guessing')",
                (user["id"], user["id"]),
            )
            existing = cur.fetchone()
            if existing:
                conn.close()
                return {"match_id": existing["id"], "status": existing["status"]}

            # Try to join an existing waiting match (skip private lobbies)
            cur.execute(
                "SELECT id, player1_id FROM game_matches WHERE status='waiting' AND player1_id != %s AND is_private=0 ORDER BY created_at ASC LIMIT 1",
                (user["id"],),
            )
            waiting = cur.fetchone()

            if waiting:
                match_id = waiting["id"]
                movie = await _fetch_random_movie()
                if not movie:
                    conn.close()
                    raise HTTPException(status_code=500, detail="Failed to fetch movie")
                deadline = datetime.datetime.utcnow() + datetime.timedelta(seconds=60)
                cur.execute(
                    """UPDATE game_matches SET player2_id=%s, status='playing',
                       movie_title=%s, movie_poster=%s, movie_year=%s, movie_rating=%s,
                       guess_deadline=%s
                       WHERE id=%s""",
                    (user["id"], movie["title"], movie["poster"], movie["year"], movie["rating"], deadline, match_id),
                )
                conn.close()
                return {"match_id": match_id, "status": "playing"}

            # Create new waiting match
            match_id = str(uuid.uuid4())
            cur.execute(
                "INSERT INTO game_matches (id, player1_id, status) VALUES (%s, %s, 'waiting')",
                (match_id, user["id"]),
            )
        conn.close()
        return {"match_id": match_id, "status": "waiting"}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


def _generate_lobby_code() -> str:
    chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
    return "".join(random.choice(chars) for _ in range(6))


@app.post("/api/game/create-lobby")
async def game_create_lobby(user=Depends(get_current_user)):
    if not get_site_settings().get("game_enabled", True):
        raise HTTPException(status_code=403, detail="Game disabled")
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT game_banned FROM game_ratings WHERE user_id=%s", (user["id"],))
            row = cur.fetchone()
            if row and row.get("game_banned"):
                raise HTTPException(status_code=403, detail="Вас забанено в грі")
            cur.execute(
                "SELECT id FROM game_matches WHERE (player1_id=%s OR player2_id=%s) AND status IN ('waiting','playing','guessing')",
                (user["id"], user["id"]),
            )
            existing = cur.fetchone()
            if existing:
                conn.close()
                raise HTTPException(status_code=400, detail="You already have an active match")
            match_id = str(uuid.uuid4())
            lobby_code = _generate_lobby_code()
            cur.execute(
                "INSERT INTO game_matches (id, player1_id, status, lobby_code, is_private) VALUES (%s, %s, 'waiting', %s, 1)",
                (match_id, user["id"], lobby_code),
            )
        conn.close()
        return {"match_id": match_id, "lobby_code": lobby_code, "status": "waiting"}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/api/game/join-lobby")
async def game_join_lobby(body: dict, user=Depends(get_current_user)):
    if not get_site_settings().get("game_enabled", True):
        raise HTTPException(status_code=403, detail="Game disabled")
    lobby_code = (body.get("lobby_code") or "").strip().upper()
    if not lobby_code:
        raise HTTPException(status_code=400, detail="Lobby code is required")
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT game_banned FROM game_ratings WHERE user_id=%s", (user["id"],))
            row = cur.fetchone()
            if row and row.get("game_banned"):
                raise HTTPException(status_code=403, detail="Вас забанено в грі")
            cur.execute(
                "SELECT id, player1_id FROM game_matches WHERE lobby_code=%s AND status='waiting' AND is_private=1 LIMIT 1",
                (lobby_code,),
            )
            match = cur.fetchone()
            if not match:
                conn.close()
                raise HTTPException(status_code=404, detail="Лобі не знайдено або вже зайняте")
            if match["player1_id"] == user["id"]:
                conn.close()
                raise HTTPException(status_code=400, detail="Ви не можете приєднатися до свого лобі")
            match_id = match["id"]
            movie = await _fetch_random_movie()
            if not movie:
                conn.close()
                raise HTTPException(status_code=500, detail="Failed to fetch movie")
            deadline = datetime.datetime.utcnow() + datetime.timedelta(seconds=60)
            cur.execute(
                """UPDATE game_matches SET player2_id=%s, status='playing',
                   movie_title=%s, movie_poster=%s, movie_year=%s, movie_rating=%s,
                   guess_deadline=%s WHERE id=%s""",
                (user["id"], movie["title"], movie["poster"], movie["year"], movie["rating"], deadline, match_id),
            )
        conn.close()
        return {"match_id": match_id, "status": "playing"}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


def _finish_match_timeout(cur, m):
    """Auto-finish match when deadline expired. The player who didn't guess loses."""
    p1_guessed = m["p1_guess_rating"] is not None
    p2_guessed = m["p2_guess_rating"] is not None

    if p1_guessed and not p2_guessed:
        winner_id = m["player1_id"]
        loser_id = m["player2_id"]
    elif p2_guessed and not p1_guessed:
        winner_id = m["player2_id"]
        loser_id = m["player1_id"]
    else:
        winner_id = None
        loser_id = None

    cur.execute("UPDATE game_matches SET status='finished', winner_id=%s WHERE id=%s", (winner_id, m["id"]))

    if winner_id:
        cur.execute(
            "INSERT INTO game_ratings (user_id, rating, wins, losses, draws) VALUES (%s, 125, 1, 0, 0) "
            "ON DUPLICATE KEY UPDATE rating=rating+25, wins=wins+1",
            (winner_id,),
        )
        cur.execute(
            "INSERT INTO game_ratings (user_id, rating, wins, losses, draws) VALUES (%s, 90, 0, 1, 0) "
            "ON DUPLICATE KEY UPDATE rating=GREATEST(0, rating-10), losses=losses+1",
            (loser_id,),
        )
    else:
        for pid in (m["player1_id"], m["player2_id"]):
            if pid:
                cur.execute(
                    "INSERT INTO game_ratings (user_id, rating, wins, losses, draws) VALUES (%s, 90, 0, 1, 0) "
                    "ON DUPLICATE KEY UPDATE rating=GREATEST(0, rating-10), losses=losses+1",
                    (pid,),
                )


@app.get("/api/game/match/{match_id}")
async def game_get_match(match_id: str, user=Depends(get_current_user)):
    """Get match state. Checks deadline timeout and auto-finishes if expired."""
    if not get_site_settings().get("game_enabled", True):
        raise HTTPException(status_code=403, detail="Game disabled")
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT * FROM game_matches WHERE id=%s", (match_id,))
            m = cur.fetchone()

            if not m:
                conn.close()
                raise HTTPException(status_code=404, detail="Match not found")
            uid = user["id"]
            if uid not in (m["player1_id"], m["player2_id"]):
                conn.close()
                raise HTTPException(status_code=403, detail="Not your match")

            # Check timeout — auto-finish if deadline passed
            if m["status"] in ("playing", "guessing") and m.get("guess_deadline"):
                now = datetime.datetime.utcnow()
                dl = m["guess_deadline"]
                if hasattr(dl, 'replace'):
                    dl = dl.replace(tzinfo=None)
                if now > dl:
                    _finish_match_timeout(cur, m)
                    cur.execute("SELECT * FROM game_matches WHERE id=%s", (match_id,))
                    m = cur.fetchone()

        conn.close()

        is_p1 = uid == m["player1_id"]
        result = {
            "match_id": m["id"],
            "status": m["status"],
            "player_number": 1 if is_p1 else 2,
        }

        if m["status"] in ("playing", "guessing"):
            result["movie_title"] = m["movie_title"]
            result["movie_poster"] = m["movie_poster"]
            my_guessed = (m["p1_guess_rating"] is not None) if is_p1 else (m["p2_guess_rating"] is not None)
            opponent_guessed = (m["p2_guess_rating"] is not None) if is_p1 else (m["p1_guess_rating"] is not None)
            result["my_guessed"] = my_guessed
            result["opponent_guessed"] = opponent_guessed
            if m.get("guess_deadline"):
                dl = m["guess_deadline"]
                if hasattr(dl, 'replace'):
                    dl = dl.replace(tzinfo=None)
                remaining = max(0, int((dl - datetime.datetime.utcnow()).total_seconds()))
                result["time_left"] = remaining

        if m["status"] == "finished":
            result["movie_title"] = m["movie_title"]
            result["movie_poster"] = m["movie_poster"]
            result["movie_year"] = m["movie_year"]
            result["movie_rating"] = m["movie_rating"]
            result["my_guess_rating"] = m["p1_guess_rating"] if is_p1 else m["p2_guess_rating"]
            result["my_guess_year"] = m["p1_guess_year"] if is_p1 else m["p2_guess_year"]
            result["opponent_guess_rating"] = m["p2_guess_rating"] if is_p1 else m["p1_guess_rating"]
            result["opponent_guess_year"] = m["p2_guess_year"] if is_p1 else m["p1_guess_year"]
            result["winner"] = "me" if m["winner_id"] == uid else ("opponent" if m["winner_id"] else "draw")
            # Detect forfeit: one side has no guesses but there is a winner
            my_guess = m["p1_guess_rating"] if is_p1 else m["p2_guess_rating"]
            opp_guess = m["p2_guess_rating"] if is_p1 else m["p1_guess_rating"]
            result["forfeit"] = (my_guess is None or opp_guess is None) and m["winner_id"] is not None
            # Get current rating for the player
            try:
                conn2 = get_db()
                with conn2.cursor() as cur2:
                    cur2.execute("SELECT rating FROM game_ratings WHERE user_id=%s", (uid,))
                    rr = cur2.fetchone()
                    result["new_rating"] = rr["rating"] if rr else 100
                conn2.close()
            except Exception:
                pass

        return result
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/api/game/guess/{match_id}")
async def game_submit_guess(match_id: str, body: dict, user=Depends(get_current_user)):
    """Submit guess for rating and year."""
    if not get_site_settings().get("game_enabled", True):
        raise HTTPException(status_code=403, detail="Game disabled")
    guess_rating = body.get("rating")
    guess_year = body.get("year")
    if guess_rating is None or guess_year is None:
        raise HTTPException(status_code=400, detail="rating and year required")
    try:
        guess_rating = round(float(guess_rating), 1)
        guess_year = int(guess_year)
    except (ValueError, TypeError):
        raise HTTPException(status_code=400, detail="Invalid values")

    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT * FROM game_matches WHERE id=%s FOR UPDATE", (match_id,))
            m = cur.fetchone()
            if not m:
                conn.close()
                raise HTTPException(status_code=404, detail="Match not found")
            if m["status"] not in ("playing", "guessing"):
                conn.close()
                raise HTTPException(status_code=400, detail="Not in guessing phase")

            uid = user["id"]
            is_p1 = uid == m["player1_id"]

            if is_p1:
                if m["p1_guess_rating"] is not None:
                    conn.close()
                    raise HTTPException(status_code=400, detail="Already guessed")
                cur.execute(
                    "UPDATE game_matches SET p1_guess_rating=%s, p1_guess_year=%s, status='guessing' WHERE id=%s",
                    (guess_rating, guess_year, match_id),
                )
            else:
                if m["p2_guess_rating"] is not None:
                    conn.close()
                    raise HTTPException(status_code=400, detail="Already guessed")
                cur.execute(
                    "UPDATE game_matches SET p2_guess_rating=%s, p2_guess_year=%s, status='guessing' WHERE id=%s",
                    (guess_rating, guess_year, match_id),
                )

            # Check if both players have guessed
            cur.execute("SELECT * FROM game_matches WHERE id=%s", (match_id,))
            m = cur.fetchone()

            if m["p1_guess_rating"] is not None and m["p2_guess_rating"] is not None:
                # Calculate scores — closer to real values wins
                real_r = m["movie_rating"]
                real_y = m["movie_year"]
                p1_score = abs(m["p1_guess_rating"] - real_r) + abs(m["p1_guess_year"] - real_y) * 0.1
                p2_score = abs(m["p2_guess_rating"] - real_r) + abs(m["p2_guess_year"] - real_y) * 0.1

                if p1_score < p2_score:
                    winner_id = m["player1_id"]
                    loser_id = m["player2_id"]
                elif p2_score < p1_score:
                    winner_id = m["player2_id"]
                    loser_id = m["player1_id"]
                else:
                    winner_id = None
                    loser_id = None

                cur.execute(
                    "UPDATE game_matches SET status='finished', winner_id=%s WHERE id=%s",
                    (winner_id, match_id),
                )

                # Update ratings
                if winner_id:
                    cur.execute(
                        "INSERT INTO game_ratings (user_id, rating, wins, losses, draws) VALUES (%s, 125, 1, 0, 0) "
                        "ON DUPLICATE KEY UPDATE rating=rating+25, wins=wins+1",
                        (winner_id,),
                    )
                    cur.execute(
                        "INSERT INTO game_ratings (user_id, rating, wins, losses, draws) VALUES (%s, 90, 0, 1, 0) "
                        "ON DUPLICATE KEY UPDATE rating=GREATEST(0, rating-10), losses=losses+1",
                        (loser_id,),
                    )
                else:
                    for pid in (m["player1_id"], m["player2_id"]):
                        cur.execute(
                            "INSERT INTO game_ratings (user_id, rating, wins, losses, draws) VALUES (%s, 105, 0, 0, 1) "
                            "ON DUPLICATE KEY UPDATE rating=rating+5, draws=draws+1",
                            (pid,),
                        )

                conn.close()
                return {"ok": True, "finished": True}

        conn.close()
        return {"ok": True, "finished": False}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/api/game/cancel/{match_id}")
async def game_cancel(match_id: str, user=Depends(get_current_user)):
    """Cancel a waiting match."""
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute(
                "DELETE FROM game_matches WHERE id=%s AND player1_id=%s AND status='waiting'",
                (match_id, user["id"]),
            )
        conn.close()
        return {"ok": True}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/api/game/forfeit/{match_id}")
async def game_forfeit(match_id: str, request: Request, user=Depends(get_current_user_optional)):
    """Player forfeits (leaves) an active match — opponent wins.
    Supports both regular auth and sendBeacon (token in body)."""
    if not user:
        try:
            body = await request.json()
            token = body.get("token")
            if token:
                conn = get_db()
                with conn.cursor() as cur:
                    user = _lookup_user_by_token(
                        cur, token, "id, email, username, is_admin, is_banned"
                    )
                conn.close()
        except Exception:
            pass
    if not user:
        return {"ok": True}
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT * FROM game_matches WHERE id=%s FOR UPDATE", (match_id,))
            m = cur.fetchone()
            if not m or m["status"] not in ("playing", "guessing"):
                conn.close()
                return {"ok": True}
            uid = user["id"]
            if uid not in (m["player1_id"], m["player2_id"]):
                conn.close()
                return {"ok": True}
            winner_id = m["player2_id"] if uid == m["player1_id"] else m["player1_id"]
            cur.execute("UPDATE game_matches SET status='finished', winner_id=%s WHERE id=%s", (winner_id, match_id))
            cur.execute(
                "INSERT INTO game_ratings (user_id, rating, wins, losses, draws) VALUES (%s, 125, 1, 0, 0) "
                "ON DUPLICATE KEY UPDATE rating=rating+25, wins=wins+1",
                (winner_id,),
            )
            cur.execute(
                "INSERT INTO game_ratings (user_id, rating, wins, losses, draws) VALUES (%s, 90, 0, 1, 0) "
                "ON DUPLICATE KEY UPDATE rating=GREATEST(0, rating-10), losses=losses+1",
                (uid,),
            )
        conn.close()
        return {"ok": True}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/api/game/history")
async def game_history(user=Depends(get_current_user)):
    """Get user's game match history."""
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("""
                SELECT m.id, m.movie_title, m.movie_poster, m.winner_id, m.created_at,
                       m.player1_id, m.player2_id,
                       u1.username AS p1_name, u2.username AS p2_name
                FROM game_matches m
                LEFT JOIN users u1 ON m.player1_id = u1.id
                LEFT JOIN users u2 ON m.player2_id = u2.id
                WHERE (m.player1_id=%s OR m.player2_id=%s) AND m.status='finished'
                ORDER BY m.created_at DESC LIMIT 30
            """, (user["id"], user["id"]))
            rows = cur.fetchall() or []
        conn.close()
        result = []
        for r in rows:
            is_p1 = r["player1_id"] == user["id"]
            if r["winner_id"] == user["id"]:
                game_result = "win"
            elif r["winner_id"] is None:
                game_result = "draw"
            else:
                game_result = "lose"
            opponent_name = r["p2_name"] if is_p1 else r["p1_name"]
            result.append({
                "id": r["id"],
                "movie_title": r["movie_title"],
                "movie_poster": r["movie_poster"],
                "opponent_name": opponent_name or "Гравець",
                "result": game_result,
                "created_at": str(r["created_at"]),
            })
        return result
    except Exception:
        return []


