@app.get("/api/subscription")
async def get_subscription(user=Depends(get_current_user)):
    tier = get_user_tier(user["id"])
    settings = get_site_settings()
    freemium_on = settings.get("freemium_enabled", False)
    result = {"tier": tier, "freemium_enabled": freemium_on}
    if freemium_on and tier == "free":
        try:
            conn = get_db()
            with conn.cursor() as cur:
                today = today_kyiv().isoformat()
                cur.execute("SELECT pick_count FROM daily_pick_counts WHERE user_id=%s AND pick_date=%s", (user["id"], today))
                row = cur.fetchone()
                result["picks_today"] = row["pick_count"] if row else 0
                result["picks_limit"] = int(settings.get("freemium_free_picks_per_day", "6"))
                cur.execute("SELECT COUNT(*) AS c FROM saved_movies WHERE user_id=%s", (user["id"],))
                sm = (cur.fetchone() or {}).get("c", 0)
                cur.execute("SELECT COUNT(*) AS c FROM saved_tv WHERE user_id=%s", (user["id"],))
                st = (cur.fetchone() or {}).get("c", 0)
                cur.execute("SELECT COUNT(*) AS c FROM saved_books WHERE user_id=%s", (user["id"],))
                sb = (cur.fetchone() or {}).get("c", 0)
                result["saved_total"] = sm + st + sb
                result["save_limit"] = int(settings.get("freemium_free_save_limit", "20"))
            conn.close()
        except Exception:
            pass
    # Duo usage count for today
    if freemium_on:
        try:
            conn2 = get_db()
            with conn2.cursor() as cur2:
                cur2.execute(
                    "SELECT COUNT(*) as cnt FROM duo_usage WHERE user_id=%s AND DATE(created_at)=CURDATE()",
                    (user["id"],),
                )
                duo_row = cur2.fetchone()
                result["duo_used_today"] = duo_row["cnt"] if duo_row else 0
            conn2.close()
        except Exception:
            result["duo_used_today"] = 0
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT expires_at, trial_used_at FROM user_subscriptions WHERE user_id=%s", (user["id"],))
            row = cur.fetchone()
            if row:
                if row.get("expires_at") and tier != "free":
                    result["expires_at"] = str(row["expires_at"])
                result["trial_used"] = row.get("trial_used_at") is not None
            else:
                result["trial_used"] = False
        conn.close()
    except Exception:
        result["trial_used"] = False
    return result


