@app.post("/api/subscription/start-trial")
async def start_trial(user=Depends(get_current_user)):
    settings = get_site_settings()
    if not settings.get("freemium_enabled", False):
        raise HTTPException(status_code=400, detail="Freemium is disabled")
    if not settings.get("freemium_trial_enabled", True):
        raise HTTPException(status_code=400, detail="Trial is disabled")
    trial_days = int(settings.get("freemium_trial_days", "7"))
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT tier, expires_at, trial_used_at FROM user_subscriptions WHERE user_id=%s", (user["id"],))
            existing = cur.fetchone()
            if existing and existing.get("trial_used_at"):
                conn.close()
                raise HTTPException(status_code=400, detail="Безкоштовний пробний період вже був використаний на цьому акаунті")
            if existing and existing["tier"] != "free":
                conn.close()
                raise HTTPException(status_code=400, detail="You already have an active subscription")
            expires = datetime.datetime.utcnow() + datetime.timedelta(days=trial_days)
            now = datetime.datetime.utcnow()
            cur.execute(
                """INSERT INTO user_subscriptions (user_id, tier, expires_at, trial_used_at)
                   VALUES (%s, 'premium', %s, %s)
                   ON DUPLICATE KEY UPDATE tier='premium', expires_at=%s, trial_used_at=%s""",
                (user["id"], expires, now, expires, now),
            )
        conn.close()
        _log_activity(user["id"], "trial_started", f"Premium trial {trial_days}d")
        return {"ok": True, "tier": "premium", "expires_at": str(expires), "trial_days": trial_days}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


