    item_type = body.get("item_type", "")
    item_id = body.get("item_id", "")
    if item_type not in ("avatar", "frame", "emoji"):
        raise HTTPException(status_code=400, detail="Invalid item type")

    conn = get_db()
    with conn.cursor() as cur:
        cur.execute(
            "SELECT id FROM user_cosmetics WHERE user_id=%s AND item_type=%s AND item_id=%s",
            (user["id"], item_type, item_id),
        )
        if not cur.fetchone():
            conn.close()
            raise HTTPException(status_code=400, detail="Item not unlocked")
        cur.execute(
            "UPDATE user_cosmetics SET equipped=0 WHERE user_id=%s AND item_type=%s",
            (user["id"], item_type),
        )
        cur.execute(
            "UPDATE user_cosmetics SET equipped=1 WHERE user_id=%s AND item_type=%s AND item_id=%s",
            (user["id"], item_type, item_id),
        )
    conn.close()
    return {"ok": True}


