async def get_admin_user(user=Depends(get_current_user)):
    if not user.get("is_admin"):
        raise HTTPException(status_code=403, detail="Admin access required")
    return user



def _admin_collection_dto(cur, row) -> dict:
    """Compact DTO for admin list/edit views."""
    cur.execute(
        "SELECT id, username, email FROM users WHERE id=%s", (row["owner_id"],)
    )
    o = cur.fetchone() or {}
    nm = o.get("username") or (o.get("email") or "").split("@")[0] or f"user_{row['owner_id']}"
    cur.execute(
        "SELECT COUNT(*) AS c FROM collection_collaborators WHERE collection_id=%s",
        (row["id"],),
    )
    collab = cur.fetchone() or {"c": 0}
    items_count = 0
    if row.get("items_json"):
        try:
            items_count = len(json.loads(row["items_json"]) or [])
        except Exception:
            items_count = 0
    return {
        "id": row["id"],
        "slug": row["slug"],
        "name": row["name"],
        "emoji": row["emoji"],
        "visibility": row["visibility"],
        "items_count": items_count,
        "likes_count": row.get("likes_count") or 0,
        "comments_count": row.get("comments_count") or 0,
        "views_count": row.get("views_count") or 0,
        "collaborators_count": collab["c"],
        "owner": {
            "id": row["owner_id"],
            "username": nm,
            "email": o.get("email"),
        },
        "created_at": _iso_utc(row.get("created_at")),
        "updated_at": _iso_utc(row.get("updated_at")),
    }


@app.get("/api/admin/collections")
async def admin_list_collections(
    q: str = "",
    visibility: str = "",
    sort: str = "recent",
    limit: int = 50,
    offset: int = 0,
    admin=Depends(get_admin_user),
):
    """Admin listing of all published collections with optional search/filter."""
    limit = max(1, min(int(limit or 50), 200))
    offset = max(0, int(offset or 0))
    sort = sort if sort in ("recent", "popular", "items") else "recent"
    order_clause = {
        "recent": "pc.updated_at DESC",
        "popular": "pc.likes_count DESC, pc.updated_at DESC",
        "items": "pc.views_count DESC, pc.updated_at DESC",
    }[sort]
    where = ["1=1"]
    params: list = []
    if visibility in ("public", "unlisted", "private"):
        where.append("pc.visibility=%s")
        params.append(visibility)
    if q:
        where.append("(pc.name LIKE %s OR pc.slug LIKE %s OR u.username LIKE %s OR u.email LIKE %s)")
        like = f"%{q}%"
        params.extend([like, like, like, like])
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute(
                f"""SELECT pc.* FROM published_collections pc
                    LEFT JOIN users u ON u.id=pc.owner_id
                    WHERE {' AND '.join(where)}
                    ORDER BY {order_clause}
                    LIMIT %s OFFSET %s""",
                tuple(params) + (limit, offset),
            )
            rows = cur.fetchall() or []
            out = [_admin_collection_dto(cur, r) for r in rows]
            cur.execute(
                f"""SELECT COUNT(*) AS c FROM published_collections pc
                    LEFT JOIN users u ON u.id=pc.owner_id
                    WHERE {' AND '.join(where)}""",
                tuple(params),
            )
            total = (cur.fetchone() or {}).get("c", 0)
        conn.close()
        return {"collections": out, "total": total, "limit": limit, "offset": offset}
    except Exception as e:
        print(f"admin_list_collections error: {e}")
        raise HTTPException(status_code=503, detail="Database unavailable")


@app.get("/api/admin/collections/{cid}")
async def admin_get_collection(cid: int, admin=Depends(get_admin_user)):
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT * FROM published_collections WHERE id=%s", (cid,))
            row = cur.fetchone()
            if not row:
                conn.close()
                raise HTTPException(status_code=404, detail="not found")
            dto = _admin_collection_dto(cur, row)
            cur.execute(
                """SELECT u.id, u.username, u.email, c.role
                   FROM collection_collaborators c JOIN users u ON u.id=c.user_id
                   WHERE c.collection_id=%s ORDER BY c.role='owner' DESC, c.joined_at""",
                (cid,),
            )
            collabs = []
            for r in cur.fetchall() or []:
                nm = r.get("username") or (r.get("email") or "").split("@")[0]
                collabs.append({"id": r["id"], "username": nm, "role": r["role"]})
            dto["collaborators"] = collabs
            try:
                dto["items"] = json.loads(row.get("items_json") or "[]") or []
            except Exception:
                dto["items"] = []
            dto["description"] = row.get("description") or ""
        conn.close()
        return {"collection": dto}
    except HTTPException:
        raise
    except Exception:
        raise HTTPException(status_code=503, detail="Database unavailable")


@app.patch("/api/admin/collections/{cid}")
async def admin_update_collection(cid: int, request: Request, admin=Depends(get_admin_user)):
    """Admin can change name, description, emoji, visibility."""
    body = await request.json()
    fields = []
    params: list = []
    if "name" in body:
        fields.append("name=%s")
        params.append((body.get("name") or "")[:255])
    if "emoji" in body:
        fields.append("emoji=%s")
        params.append((body.get("emoji") or "")[:16])
    if "description" in body:
        fields.append("description=%s")
        params.append((body.get("description") or "")[:2000])
    if "visibility" in body:
        v = (body.get("visibility") or "").strip().lower()
        if v not in ("public", "unlisted", "private"):
            raise HTTPException(status_code=400, detail="invalid visibility")
        fields.append("visibility=%s")
        params.append(v)
    if not fields:
        raise HTTPException(status_code=400, detail="no fields to update")
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute(
                f"UPDATE published_collections SET {', '.join(fields)} WHERE id=%s",
                tuple(params) + (cid,),
            )
        conn.close()
        _log_activity(admin["id"], "admin_update_collection", f"Updated collection {cid}: {list(body.keys())}")
        return {"status": "ok"}
    except HTTPException:
        raise
    except Exception as e:
        print(f"admin_update_collection error: {e}")
        raise HTTPException(status_code=503, detail="Database unavailable")


