# ─── Role-Based Access Control ───
ROLE_HIERARCHY = {
    "user": 0,
    "media": 1,
    "content-manager": 1,
    "moderator": 2,
    "editor": 1,
    "support": 1,
    "admin": 3,
    "superadmin": 4,
}

# Roles that grant a free Pro subscription (no admin permissions, just badge + perks)
PERK_ROLES = {"media"}

# STAFF_PRO_ROLES is imported from backend.core.config — see that module for
# the canonical list of staff roles that auto-promote to Pro tier.

ROLE_PERMISSIONS = {
    "user": set(),
    "media": set(),
    "content-manager": {
        "manage_announcements", "manage_daily_pick", "manage_banners",
        "view_feedback", "view_stats", "manage_content",
    },
    "editor": {
        "manage_announcements", "manage_daily_pick", "manage_banners",
        "view_feedback", "view_stats", "manage_content",
    },
    "support": {
        "view_users", "view_feedback", "manage_feedback", "view_stats",
        "view_logs",
    },
    "moderator": {
        "view_users", "ban_users", "manage_feedback", "view_feedback",
        "manage_announcements", "manage_game", "view_stats", "view_logs",
        "manage_content",
    },
    "admin": {
        "view_users", "ban_users", "delete_users", "manage_roles",
        "manage_feedback", "view_feedback", "manage_announcements",
        "manage_settings", "manage_banners", "manage_game", "view_stats",
        "view_logs", "manage_subscriptions", "manage_content",
        "manage_daily_pick", "manage_system",
    },
    "superadmin": {
        "view_users", "ban_users", "delete_users", "manage_roles",
        "manage_feedback", "view_feedback", "manage_announcements",
        "manage_settings", "manage_banners", "manage_game", "view_stats",
        "view_logs", "manage_subscriptions", "manage_content",
        "manage_daily_pick", "manage_system", "manage_admins",
    },
}

ALL_ROLES = list(ROLE_HIERARCHY.keys())


def user_has_permission(user: dict, permission: str) -> bool:
    if user.get("is_admin"):
        return True
    role = user.get("role", "user")
    return permission in ROLE_PERMISSIONS.get(role, set())


def user_role_level(user: dict) -> int:
    """Effective role level.

    `is_admin=1` legacy flag grants at least admin-level (3). If the user
    also has an explicit role (e.g. `superadmin` → 4), the higher of the
    two values is returned so superadmins are not collapsed to admin.
    """
    role = user.get("role", "user") or "user"
    role_level = ROLE_HIERARCHY.get(role, 0)
    if user.get("is_admin"):
        return max(role_level, ROLE_HIERARCHY.get("admin", 3))
    return role_level


def require_permission(permission: str):
    async def _check(user=Depends(get_current_user)):
        if not user_has_permission(user, permission):
            raise HTTPException(status_code=403, detail=f"Permission denied: {permission}")
        return user
    return _check


async def get_staff_user(user=Depends(get_current_user)):
    if user_role_level(user) < 1:
        raise HTTPException(status_code=403, detail="Staff access required")
    return user


def _staff_with_permission(permission: str):
    """Permission-based guard.

    Returns the current user if they are a full admin (is_admin=1) OR
    if their role grants the required permission. Used for endpoints that
    should be reachable from both /admin and /staff panels for the right
    role tiers.
    """
    async def _check(user=Depends(get_current_user)):
        if user.get("is_admin"):
            return user
        if user_has_permission(user, permission):
            return user
        raise HTTPException(status_code=403, detail=f"Permission denied: {permission}")
    return _check


@app.get("/api/roles")
async def list_roles():
    return {
        "roles": ALL_ROLES,
        "permissions": {k: sorted(v) for k, v in ROLE_PERMISSIONS.items()},
    }


@app.get("/api/me/permissions")
async def my_permissions(user=Depends(get_current_user)):
    role = user.get("role", "user") or "user"
    perms = set(ROLE_PERMISSIONS.get(role, set()))
    if user.get("is_admin"):
        perms |= ROLE_PERMISSIONS.get("admin", set())
    return {
        "role": role,
        "is_admin": bool(user.get("is_admin")),
        "permissions": sorted(perms),
        "role_level": user_role_level(user),
    }


