@app.post("/api/admin/payments/{payment_id}/approve")
async def admin_approve_payment(payment_id: int, admin=Depends(get_admin_user)):
    conn = get_db()
    with conn.cursor() as cur:
        cur.execute("SELECT * FROM payment_requests WHERE id=%s", (payment_id,))
        p = cur.fetchone()
        if not p:
            conn.close()
            raise HTTPException(status_code=404, detail="Payment not found")
        if p["status"] != "pending":
            conn.close()
            raise HTTPException(status_code=400, detail="Already processed")

        cur.execute(
            "UPDATE payment_requests SET status='approved', processed_at=CURRENT_TIMESTAMP WHERE id=%s",
            (payment_id,),
        )

        if p["user_id"]:
            expires = datetime.datetime.utcnow() + datetime.timedelta(days=p["days"])
            cur.execute(
                """INSERT INTO user_subscriptions (user_id, tier, expires_at)
                   VALUES (%s, %s, %s)
                   ON DUPLICATE KEY UPDATE tier=%s, expires_at=%s""",
                (p["user_id"], p["tier"], expires, p["tier"], expires),
            )
            _log_activity(p["user_id"], "payment_approved", f"{p['tier']} {p['days']}d")
    conn.close()
    return {"ok": True, "receipt_id": p.get("receipt_id")}


@app.post("/api/admin/payments/{payment_id}/reject")
async def admin_reject_payment(payment_id: int, admin=Depends(get_admin_user)):
    conn = get_db()
    with conn.cursor() as cur:
        cur.execute("SELECT receipt_id, user_id, tier, days FROM payment_requests WHERE id=%s", (payment_id,))
        p = cur.fetchone()
        if not p:
            conn.close()
            raise HTTPException(status_code=404, detail="Payment not found")
        cur.execute(
            "UPDATE payment_requests SET status='rejected', processed_at=CURRENT_TIMESTAMP WHERE id=%s",
            (payment_id,),
        )
        if p.get("user_id"):
            try:
                _log_activity(p["user_id"], "payment_rejected", f"{p.get('tier','')} {p.get('days','')}d")
            except Exception:
                pass
    conn.close()
    return {"ok": True, "receipt_id": p.get("receipt_id")}


