class SetStreakReq(BaseModel):
    streak: int = 0


@app.post("/api/admin/users/{user_id}/set-streak")
async def admin_set_streak(user_id: int, req: SetStreakReq, admin=Depends(get_admin_user)):
    """Insert pick_history entries to create desired streak count."""
    streak = max(0, min(req.streak, 9999))
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT id FROM users WHERE id = %s", (user_id,))
            if not cur.fetchone():
                raise HTTPException(status_code=404, detail="User not found")
            # Remove existing admin-injected streak entries (marked by title)
            cur.execute("DELETE FROM pick_history WHERE user_id = %s AND title = '__admin_streak__'", (user_id,))
            # Insert one entry per day going backwards from today
            today = today_kyiv()
            for i in range(streak):
                d = today - datetime.timedelta(days=i)
                cur.execute(
                    "INSERT INTO pick_history (user_id, type, item_id, title, picked_at) VALUES (%s, 'movie', '0', '__admin_streak__', %s)",
                    (user_id, d),
                )
        conn.close()
        _log_activity(admin["id"], "set_streak", f"User {user_id} streak={streak}")
        return {"user_id": user_id, "streak": streak}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


