            u = cur.fetchone()
            if not u:
                raise HTTPException(status_code=404, detail="User not found")
            cur.execute("SELECT COUNT(*) AS c FROM pick_history WHERE user_id = %s", (user_id,))
            picks = (cur.fetchone() or {}).get("c", 0)
            cur.execute("SELECT type, COUNT(*) AS c FROM pick_history WHERE user_id = %s GROUP BY type", (user_id,))
            by_type = {r["type"]: r["c"] for r in (cur.fetchall() or [])}
            cur.execute("SELECT COUNT(*) AS c FROM saved_movies WHERE user_id = %s", (user_id,))
            sm = (cur.fetchone() or {}).get("c", 0)
            cur.execute("SELECT COUNT(*) AS c FROM saved_tv WHERE user_id = %s", (user_id,))
            st = (cur.fetchone() or {}).get("c", 0)
            cur.execute("SELECT COUNT(*) AS c FROM saved_books WHERE user_id = %s", (user_id,))
            sb = (cur.fetchone() or {}).get("c", 0)
            cur.execute("SELECT search_count, random_count, ai_search_count FROM user_stats WHERE user_id = %s", (user_id,))
            stats = cur.fetchone() or {"search_count": 0, "random_count": 0, "ai_search_count": 0}
            cur.execute("SELECT title, type, picked_at FROM pick_history WHERE user_id = %s ORDER BY picked_at DESC LIMIT 20", (user_id,))
            recent = [{"title": r["title"], "type": r["type"], "date": str(r["picked_at"])} for r in (cur.fetchall() or [])]
