@app.get("/api/admin/subscriptions")
async def admin_list_subscriptions(admin=Depends(get_admin_user)):
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("""
                SELECT s.user_id, u.email, u.username, s.tier, s.started_at, s.expires_at
                FROM user_subscriptions s JOIN users u ON s.user_id = u.id
                ORDER BY s.updated_at DESC
            """)
            rows = cur.fetchall() or []
        conn.close()
        return [
            {**r, "started_at": str(r["started_at"]) if r.get("started_at") else None,
             "expires_at": str(r["expires_at"]) if r.get("expires_at") else None}
            for r in rows
        ]
    except Exception:
        return []


@app.post("/api/admin/subscriptions/{user_id}")
async def admin_set_subscription(user_id: int, body: dict, admin=Depends(get_admin_user)):
    tier = body.get("tier", "free")
    if tier not in ("free", "premium", "pro"):
        raise HTTPException(status_code=400, detail="Invalid tier")
    days = int(body.get("days", 30))
    try:
        conn = get_db()
        with conn.cursor() as cur:
            if tier == "free":
                # Keep the row so trial_used_at marker survives — prevents users
                # from getting an extra free trial after admin downgrades them.
                cur.execute(
                    """INSERT INTO user_subscriptions (user_id, tier, expires_at)
                       VALUES (%s, 'free', NULL)
                       ON DUPLICATE KEY UPDATE tier='free', expires_at=NULL""",
                    (user_id,),
                )
            else:
                expires = datetime.datetime.utcnow() + datetime.timedelta(days=days)
                cur.execute(
                    """INSERT INTO user_subscriptions (user_id, tier, expires_at)
                       VALUES (%s, %s, %s)
                       ON DUPLICATE KEY UPDATE tier=%s, expires_at=%s""",
                    (user_id, tier, expires, tier, expires),
                )
        conn.close()
        _log_activity(admin["id"], "set_subscription", f"User {user_id} → {tier} ({days}d)")
        return {"ok": True, "tier": tier}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


