@app.get("/api/admin/analytics/overview")
async def admin_analytics_overview(admin=Depends(get_admin_user)):
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT COUNT(*) AS c FROM analytics_sessions")
            total_sessions = (cur.fetchone() or {}).get("c", 0)
            cur.execute("SELECT COUNT(*) AS c FROM analytics_sessions WHERE started_at >= CURDATE()")
            sessions_today = (cur.fetchone() or {}).get("c", 0)
            cur.execute("SELECT COUNT(*) AS c FROM analytics_events")
            total_events = (cur.fetchone() or {}).get("c", 0)
            cur.execute("SELECT COUNT(*) AS c FROM analytics_events WHERE created_at >= CURDATE()")
            events_today = (cur.fetchone() or {}).get("c", 0)
            cur.execute("SELECT COUNT(*) AS c FROM analytics_clicks")
            total_clicks = (cur.fetchone() or {}).get("c", 0)
            cur.execute("""
                SELECT funnel_step, COUNT(*) AS cnt
                FROM analytics_sessions
                WHERE started_at >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)
                GROUP BY funnel_step
            """)
            funnel_raw = cur.fetchall() or []
            funnel = {r["funnel_step"]: r["cnt"] for r in funnel_raw}
            cur.execute("""
                SELECT event_type, COUNT(*) AS cnt
                FROM analytics_events
                WHERE created_at >= DATE_SUB(CURDATE(), INTERVAL 7 DAY)
                GROUP BY event_type ORDER BY cnt DESC LIMIT 20
            """)
            top_events = [{"event": r["event_type"], "count": r["cnt"]} for r in (cur.fetchall() or [])]
            cur.execute("""
                SELECT DATE(started_at) AS d, COUNT(*) AS cnt
                FROM analytics_sessions
                WHERE started_at >= DATE_SUB(CURDATE(), INTERVAL 14 DAY)
                GROUP BY d ORDER BY d
            """)
            sessions_chart = [{"date": str(r["d"]), "count": r["cnt"]} for r in (cur.fetchall() or [])]
        conn.close()
        return {
            "total_sessions": total_sessions,
            "sessions_today": sessions_today,
            "total_events": total_events,
            "events_today": events_today,
            "total_clicks": total_clicks,
            "funnel": {
                "visit": funnel.get("visit", 0),
                "register": funnel.get("register", 0),
                "first_pick": funnel.get("first_pick", 0),
                "active": funnel.get("active", 0),
            },
            "top_events": top_events,
            "sessions_chart": sessions_chart,
        }
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


