@app.get("/api/admin/analytics/funnel")
async def admin_analytics_funnel(days: int = 30, admin=Depends(get_admin_user)):
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("""
                SELECT funnel_step, COUNT(*) AS cnt
                FROM analytics_sessions
                WHERE started_at >= DATE_SUB(CURDATE(), INTERVAL %s DAY)
                GROUP BY funnel_step
                ORDER BY FIELD(funnel_step, 'visit','register','first_pick','active')
            """, (days,))
            steps = cur.fetchall() or []
        conn.close()
        total_visit = sum(r["cnt"] for r in steps) or 1
        result = []
        for r in steps:
            result.append({
                "step": r["funnel_step"],
                "count": r["cnt"],
                "percent": round(r["cnt"] / total_visit * 100, 1),
            })
        return {"days": days, "funnel": result}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


