# ─── Role Audit Log ───

@app.get("/api/admin/role-audit-log")
async def admin_role_audit_log(admin=Depends(_staff_with_permission("manage_roles"))):
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("""
                SELECT r.*, u1.email AS target_email, u1.username AS target_username,
                       u2.email AS changed_by_email, u2.username AS changed_by_username
                FROM role_audit_log r
                LEFT JOIN users u1 ON r.target_user_id = u1.id
                LEFT JOIN users u2 ON r.changed_by = u2.id
                ORDER BY r.created_at DESC LIMIT 100
            """)
            rows = cur.fetchall() or []
        conn.close()
        return [{**r, "created_at": str(r["created_at"])} for r in rows]
    except Exception:
        return []


# ─── Staff invite by email ───

class StaffInviteRequest(BaseModel):
    email: str
    role: str = "content-manager"
    message: Optional[str] = None


@app.post("/api/admin/staff/invite")
async def admin_invite_staff(req: StaffInviteRequest, admin=Depends(_staff_with_permission("manage_roles"))):
    if req.role not in ALL_ROLES or req.role == "user":
        raise HTTPException(status_code=400, detail="Invalid staff role")
    target_level = ROLE_HIERARCHY.get(req.role, 0)
    admin_level = user_role_level(admin)
    if target_level >= admin_level:
        raise HTTPException(status_code=403, detail="Cannot invite with a role equal to or higher than your own")
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT id, role FROM users WHERE email=%s", (req.email,))
            user_row = cur.fetchone()
            if not user_row:
                conn.close()
                raise HTTPException(status_code=404, detail="Користувача з таким email не знайдено. Спочатку він має зареєструватися.")
            uid = user_row["id"]
            old_role = user_row.get("role", "user")
            cur.execute("UPDATE users SET role = %s WHERE id = %s", (req.role, uid))
            if req.role in ("admin", "superadmin"):
                cur.execute("UPDATE users SET is_admin = 1 WHERE id = %s", (uid,))
            cur.execute(
                "INSERT INTO role_audit_log (target_user_id, changed_by, old_role, new_role, reason) VALUES (%s,%s,%s,%s,%s)",
                (uid, admin["id"], old_role, req.role, f"Staff invite: {req.message or ''}"),
            )
            conn.commit()
        conn.close()
        _log_activity(admin["id"], "staff_invite", f"{req.email} → {req.role}")
        return {"ok": True, "email": req.email, "role": req.role}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


# ─── Superadmin self-assign ───

@app.post("/api/admin/make-superadmin")
async def make_superadmin(user=Depends(get_current_user)):
    """First admin or any existing admin/superadmin can promote themselves.

    Bootstrap rule: if there are zero superadmins in the system, any
    authenticated user may claim the role. Otherwise only existing
    admins can self-assign superadmin.
    """
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT COUNT(*) AS c FROM users WHERE role='superadmin'")
            super_count = (cur.fetchone() or {}).get("c", 0)
            if super_count > 0 and not user.get("is_admin"):
                conn.close()
                raise HTTPException(status_code=403, detail="Superadmin already exists. Ask an admin to promote you.")
            cur.execute("UPDATE users SET role='superadmin', is_admin=1 WHERE id=%s", (user["id"],))
            cur.execute(
                "INSERT INTO role_audit_log (target_user_id, changed_by, old_role, new_role, reason) VALUES (%s,%s,%s,%s,%s)",
                (user["id"], user["id"], user.get("role", "user"), "superadmin", "Self-assigned superadmin"),
            )
            conn.commit()
        conn.close()
        return {"ok": True, "role": "superadmin"}
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


