# ─── Daily Pick override (admin/staff with manage_daily_pick) ───

class DailyPickOverrideRequest(BaseModel):
    type: str = "movie"  # movie | tv | book
    tmdb_id: Optional[int] = None
    volume_id: Optional[str] = None


@app.post("/api/admin/daily-pick")
async def admin_set_daily_pick(req: DailyPickOverrideRequest, admin=Depends(_staff_with_permission("manage_daily_pick"))):
    if req.type not in ("movie", "tv", "book"):
        raise HTTPException(status_code=400, detail="type must be movie, tv or book")
    today = today_kyiv().isoformat()
    if req.type == "book":
        if not req.volume_id:
            raise HTTPException(status_code=400, detail="volume_id required for type=book")
        value = {"date": today, "volume_id": req.volume_id}
    else:
        if not req.tmdb_id:
            raise HTTPException(status_code=400, detail="tmdb_id required")
        value = {"date": today, "tmdb_id": int(req.tmdb_id)}
    try:
        conn = get_db()
        with conn.cursor() as cur:
            key = f"daily_pick_override_{req.type}"
            cur.execute(
                "INSERT INTO site_settings (name, value) VALUES (%s, %s) ON DUPLICATE KEY UPDATE value=VALUES(value)",
                (key, json.dumps(value)),
            )
            conn.commit()
        conn.close()
        _log_activity(admin["id"], "daily_pick_override", f"{req.type} → {value}")
        return {"ok": True, "type": req.type, "override": value}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.delete("/api/admin/daily-pick/{type}")
async def admin_clear_daily_pick(type: str, admin=Depends(_staff_with_permission("manage_daily_pick"))):
    if type not in ("movie", "tv", "book"):
        raise HTTPException(status_code=400, detail="type must be movie, tv or book")
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("DELETE FROM site_settings WHERE name = %s", (f"daily_pick_override_{type}",))
            conn.commit()
        conn.close()
        return {"ok": True, "type": type, "cleared": True}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


# ─── Data Export ───

@app.get("/api/me/export")
async def export_my_data(user=Depends(get_current_user)):
    uid = user["id"]
    data = {"user": {"id": uid, "email": user.get("email"), "username": user.get("username"), "role": user.get("role", "user"), "created_at": str(user.get("created_at", ""))}}
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT * FROM user_subscriptions WHERE user_id=%s", (uid,))
            sub = cur.fetchone()
            if sub:
                data["subscription"] = {k: str(v) if isinstance(v, (datetime.datetime, datetime.date)) else v for k, v in sub.items()}
            cur.execute("SELECT type, tmdb_id, title, poster, year, rating, picked_at FROM pick_history WHERE user_id=%s ORDER BY picked_at DESC LIMIT 500", (uid,))
            data["history"] = [
                {k: str(v) if isinstance(v, (datetime.datetime, datetime.date)) else v for k, v in r.items()}
                for r in (cur.fetchall() or [])
            ]
            cur.execute("SELECT type, tmdb_id, title, poster, year, rating FROM saved_items WHERE user_id=%s", (uid,))
            data["saved"] = [
                {k: str(v) if isinstance(v, (datetime.datetime, datetime.date)) else v for k, v in r.items()}
                for r in (cur.fetchall() or [])
            ]
        conn.close()
    except Exception:
        pass
    return data


