@app.get("/api/gifts/notifications/recent")
async def gift_notifications_v2(user=Depends(get_current_user)):
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute(
                """SELECT id, action, detail, created_at FROM activity_log
                   WHERE user_id=%s AND action='gift_opened'
                   ORDER BY created_at DESC LIMIT 25""",
                (user["id"],),
            )
            rows = cur.fetchall() or []
        conn.close()
    except Exception:
        return {"items": []}
    out = []
    for r in rows:
        det = (r.get("detail") or "").split("|")
        out.append({
            "id": r.get("id"),
            "title": det[0] if det else "",
            "type": det[1] if len(det) > 1 else "",
            "token": det[2] if len(det) > 2 else "",
            "created_at": _iso_utc(r.get("created_at")),
        })
    return {"items": out}


@app.get("/api/gifts/{token}")
async def get_gift(token: str):
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT * FROM movie_gifts WHERE token=%s", (token,))
            row = cur.fetchone()
        conn.close()
    except Exception:
        raise HTTPException(status_code=503, detail="Database unavailable")
    if not row:
        raise HTTPException(status_code=404, detail="not found")
    # voice_data is a ~600 KB base64 blob — exclude it from the JSON and let
    # clients lazily fetch it via /api/gifts/{token}/voice. Cuts the gift
    # bootstrap payload dramatically on slow mobile connections.
    return _gift_to_dto(row, include_voice=False, include_overview=True)


@app.get("/api/gifts/{token}/voice")
async def get_gift_voice(token: str):
    """Serve the voice clip as a small audio response.

    The voice clip is stored as a base64 string (often a full data URL) in the
    movie_gifts.voice_data column. We strip the data: prefix, decode, and stream
    bytes back so audio elements can use a stable URL instead of stuffing a
    multi-hundred-KB base64 string into the JSON payload.
    """
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT voice_data FROM movie_gifts WHERE token=%s", (token,))
            row = cur.fetchone()
        conn.close()
    except Exception:
        raise HTTPException(status_code=503, detail="Database unavailable")
    if not row or not row.get("voice_data"):
        raise HTTPException(status_code=404, detail="not found")
    raw = row["voice_data"]
    media_type = "audio/webm"
    if isinstance(raw, str) and raw.startswith("data:"):
        try:
            header, b64 = raw.split(",", 1)
            # header looks like "data:audio/webm;base64"
            if ";" in header and ":" in header:
                media_type = header.split(":", 1)[1].split(";", 1)[0] or media_type
        except Exception:
            b64 = raw
    else:
        b64 = raw
    try:
        import base64 as _b64
        data = _b64.b64decode(b64, validate=False)
    except Exception:
        raise HTTPException(status_code=500, detail="decode error")
    return Response(
        content=data,
        media_type=media_type,
        headers={"Cache-Control": "public, max-age=86400"},
    )


@app.post("/api/gifts/{token}/open")
async def open_gift(token: str):
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT * FROM movie_gifts WHERE token=%s", (token,))
            g = cur.fetchone()
            if not g:
                conn.close()
                raise HTTPException(status_code=404, detail="not found")
            sched = g.get("scheduled_at")
            if sched and hasattr(sched, "timestamp"):
                if sched.timestamp() > datetime.datetime.utcnow().timestamp():
                    conn.close()
                    return {"ok": False, "locked": True, "scheduled_at": sched.isoformat()}
            current_count = int(g.get("opened_count") or 0)
            max_opens = int(g.get("max_opens") or 1)
            gift_mode = g.get("gift_mode") or "single"
            if gift_mode == "single" and current_count >= 1:
                conn.close()
                return {"ok": False, "expired": True, "reason": "single_use_exhausted"}
            if gift_mode == "multi" and current_count >= max_opens:
                conn.close()
                return {"ok": False, "expired": True, "reason": "max_opens_reached", "max_opens": max_opens}
            first_open = g.get("opened_at") is None
            cur.execute(
                "UPDATE movie_gifts SET opened_count=opened_count+1, opened_at=COALESCE(opened_at, NOW()) WHERE token=%s",
                (token,),
            )
            if first_open:
                try:
                    cur.execute(
                        "INSERT INTO activity_log (user_id, action, detail) VALUES (%s, %s, %s)",
                        (g.get("sender_id"), "gift_opened",
                         f"{g.get('item_title') or g.get('item_id')}|{g.get('item_type')}|{token}"),
                    )
                except Exception:
                    pass
        conn.close()
    except HTTPException:
        raise
    except Exception:
        raise HTTPException(status_code=503, detail="Database unavailable")
    return {"ok": True, "first_open": first_open, "opened_count": current_count + 1, "max_opens": max_opens, "gift_mode": gift_mode}


