@app.get("/qr/{item_type}/{item_id}")
async def qr_landing_page(item_type: str, item_id: str, request: Request, lang: str = "uk"):
    """Beautiful QR landing page that wraps the raw QR with branding,
    poster, share/download/copy actions. Use this everywhere instead of
    linking the raw /api/qr/* endpoint."""
    if item_type not in ("movie", "tv", "book", "profile"):
        raise HTTPException(status_code=400, detail="Invalid type")
    host = _request_share_host(request)
    app_url = f"https://{host}"
    if item_type == "profile":
        share_url = f"{app_url}/u/{item_id}"
    else:
        share_url = f"{app_url}/{item_type}/{item_id}"

    title = "Picksy"
    subtitle = ""
    poster = ""

    try:
        if item_type in ("movie", "tv"):
            media_type = "movie" if item_type == "movie" else "tv"
            api_url = f"https://api.themoviedb.org/3/{media_type}/{item_id}?language={lang}"
            headers = {}
            if TMDB_IS_BEARER:
                headers["Authorization"] = f"Bearer {TMDB_API_KEY}"
            else:
                api_url += f"&api_key={TMDB_API_KEY}"
            async with httpx.AsyncClient(timeout=8) as client:
                resp = await client.get(api_url, headers=headers)
                if resp.status_code == 200:
                    data = resp.json()
                    title = data.get("title") or data.get("name") or "Picksy"
                    poster_path = data.get("poster_path", "")
                    poster = f"https://image.tmdb.org/t/p/w500{poster_path}" if poster_path else ""
                    year = (data.get("release_date") or data.get("first_air_date") or "")[:4]
                    rating = data.get("vote_average")
                    parts = []
                    if year:
                        parts.append(year)
                    if rating:
                        parts.append(f"⭐ {rating:.1f}")
                    if item_type == "movie":
                        runtime_min = data.get("runtime") or 0
                        if runtime_min:
                            parts.append(f"⏱️ {runtime_min} хв")
                        parts.append("Фільм")
                    else:
                        seasons = data.get("number_of_seasons") or 0
                        episodes = data.get("number_of_episodes") or 0
                        if seasons:
                            parts.append(f"📺 {seasons} сез.")
                        if episodes:
                            parts.append(f"{episodes} еп.")
                        parts.append("Серіал")
                    subtitle = " · ".join(parts)
        elif item_type == "book":
            api_url = f"https://www.googleapis.com/books/v1/volumes/{item_id}"
            async with httpx.AsyncClient(timeout=8) as client:
                resp = await client.get(api_url)
                if resp.status_code == 200:
                    vol = (resp.json() or {}).get("volumeInfo", {})
                    title = vol.get("title", "Picksy")
                    poster = vol.get("imageLinks", {}).get("thumbnail", "")
                    authors = vol.get("authors") or []
                    page_count = vol.get("pageCount") or 0
                    parts = []
                    if authors:
                        parts.append(", ".join(authors[:2]))
                    if page_count:
                        parts.append(f"📄 {page_count} стор.")
                    parts.append("Книга")
                    subtitle = " · ".join(parts)
        elif item_type == "profile":
            title = f"@{item_id}"
            subtitle = "Профіль на Picksy"
    except Exception:
        pass

    if poster:
        poster_html = f'<img class="qr-poster" src="{_esc(poster)}" alt="{_esc(title)}" onerror="this.replaceWith(Object.assign(document.createElement(\'div\'),{{className:\'qr-poster-fallback\',textContent:\'🎬\'}}))">'
    else:
        emoji = "📚" if item_type == "book" else ("👤" if item_type == "profile" else "🎬")
        poster_html = f'<div class="qr-poster-fallback">{emoji}</div>'

    title_js = (title or "").replace("\\", "\\\\").replace("'", "\\'").replace("\n", " ")

    html = QR_PAGE_HTML
    html = html.replace("{{TITLE}}", _esc(title))
    html = html.replace("{{TITLE_JS}}", title_js)
    html = html.replace("{{SUBTITLE}}", _esc(subtitle or "Сканеруй щоб відкрити в Picksy"))
    html = html.replace("{{POSTER}}", _esc(poster or ""))
    html = html.replace("{{POSTER_HTML}}", poster_html)
    html = html.replace("{{SHARE_URL}}", _esc(share_url))
    html = html.replace("{{APP_URL}}", _esc(app_url))
    html = html.replace("{{TYPE}}", _esc(item_type))
    html = html.replace("{{ITEM_ID}}", _esc(str(item_id)))
    return HTMLResponse(html)


@app.get("/api/qr/{item_type}/{item_id}")
async def generate_qr_code(
    item_type: str,
    item_id: str,
    request: Request,
    format: str = "auto",   # auto | png | svg
    fill: str = "#8b5cf6",
    bg: str = "#0a0a14",
    size: int = 10,
):
    if item_type not in ("movie", "tv", "book", "link", "profile"):
        raise HTTPException(status_code=400, detail="Invalid type")
    if format not in ("auto", "png", "svg"):
        raise HTTPException(status_code=400, detail="format must be png, svg or auto")
    if not re.match(r"^#[0-9a-fA-F]{6}$", fill) or not re.match(r"^#[0-9a-fA-F]{6}$", bg):
        fill = "#8b5cf6"
        bg = "#0a0a14"
    try:
        size = max(4, min(int(size), 24))
    except Exception:
        size = 10

    host = _request_share_host(request)
    url = _qr_url_for(item_type, item_id, host)
    cache_key = f"{format}:{size}:{fill}:{bg}:{url}"

    cached = _qr_cache.get(cache_key)
    if cached:
        body, mime = cached
        from fastapi.responses import Response
        return Response(
            content=body,
            media_type=mime,
            headers={
                "Content-Disposition": f"inline; filename=picksy-qr-{item_type}-{item_id}.{('svg' if mime.endswith('svg+xml') else 'png')}",
                "Cache-Control": "public, max-age=86400",
                "X-QR-Cache": "HIT",
            },
        )

    try:
        png_bytes: Optional[bytes] = None
        if format in ("auto", "png"):
            png_bytes = _render_qr_png(url, fill=fill, bg=bg, box_size=size)

        from fastapi.responses import Response
        if png_bytes is not None:
            if len(_qr_cache) >= _QR_CACHE_LIMIT:
                _qr_cache.clear()
            _qr_cache[cache_key] = (png_bytes, "image/png")
            return Response(
                content=png_bytes,
                media_type="image/png",
                headers={
                    "Content-Disposition": f"inline; filename=picksy-qr-{item_type}-{item_id}.png",
                    "Cache-Control": "public, max-age=86400",
                    "X-QR-Cache": "MISS",
                },
            )

        # SVG path (explicit format=svg, or PNG generation unavailable)
        svg_str = _generate_qr_svg(url, fill=fill, bg=bg)
        body = svg_str.encode("utf-8")
        if len(_qr_cache) >= _QR_CACHE_LIMIT:
            _qr_cache.clear()
        _qr_cache[cache_key] = (body, "image/svg+xml")
        return Response(
            content=body,
            media_type="image/svg+xml",
            headers={
                "Content-Disposition": f"inline; filename=picksy-qr-{item_type}-{item_id}.svg",
                "Cache-Control": "public, max-age=86400",
                "X-QR-Cache": "MISS",
            },
        )
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


def _generate_qr_svg(data: str, fill: str = "#8b5cf6", bg: str = "#0a0a14") -> str:
    try:
        import qrcode
        qr = qrcode.QRCode(version=None, error_correction=qrcode.constants.ERROR_CORRECT_H, box_size=10, border=2)
        qr.add_data(data)
        qr.make(fit=True)
        matrix = qr.get_matrix()
    except ImportError:
        matrix = _simple_qr_matrix(data)

    size = len(matrix)
    scale = 8
    svg_size = size * scale
    rects = []
    for y, row in enumerate(matrix):
        for x, cell in enumerate(row):
            if cell:
                rects.append(f'<rect x="{x*scale}" y="{y*scale}" width="{scale}" height="{scale}" fill="{fill}"/>')
    return f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {svg_size} {svg_size}" width="{svg_size}" height="{svg_size}">
<rect width="{svg_size}" height="{svg_size}" fill="{bg}"/>
{"".join(rects)}
</svg>'''


def _simple_qr_matrix(data: str) -> list:
    h = hashlib.md5(data.encode()).hexdigest()
    size = 21
    matrix = [[False]*size for _ in range(size)]
    for i in range(size):
        for j in range(size):
            idx = (i * size + j) % len(h)
            matrix[i][j] = int(h[idx], 16) > 7
    for i in range(7):
        for j in range(7):
            val = (i in (0,6) or j in (0,6) or (2<=i<=4 and 2<=j<=4))
            matrix[i][j] = val
            matrix[i][size-1-j] = val
            matrix[size-1-i][j] = val
    return matrix


