@app.get("/share/card/{item_type}/{item_id}")
async def share_card_page(item_type: str, item_id: str, request: Request, lang: str = "uk"):
    if item_type not in ("movie", "tv", "book"):
        raise HTTPException(status_code=400, detail="Invalid type")
    host = _request_share_host(request)
    share_url = f"https://{host}/{item_type}/{item_id}"
    # Always request SVG so the QR works even without qrcode[pil] installed.
    qr_url = f"/api/qr/{item_type}/{item_id}?format=svg"
    app_url = f"https://{host}"

    title = "Picksy"
    description = ""
    poster = ""
    badges_html = ""
    tmdb_url = ""

    is_uk = (lang or "uk").lower().startswith("uk")
    min_label = "хв" if is_uk else "min"
    seasons_label = "сезонів" if is_uk else "seasons"
    episodes_label = "епізодів" if is_uk else "episodes"
    pages_label = "стор." if is_uk else "pages"

    try:
        if item_type in ("movie", "tv"):
            media_type = "movie" if item_type == "movie" else "tv"
            tmdb_url_api = f"https://api.themoviedb.org/3/{media_type}/{item_id}?language={lang}"
            headers = {}
            if TMDB_IS_BEARER:
                headers["Authorization"] = f"Bearer {TMDB_API_KEY}"
            else:
                tmdb_url_api += f"&api_key={TMDB_API_KEY}"
            async with httpx.AsyncClient(timeout=8) as client:
                resp = await client.get(tmdb_url_api, headers=headers)
                if resp.status_code == 200:
                    data = resp.json()
                    title = data.get("title") or data.get("name") or "Picksy"
                    description = data.get("overview", "")[:300]
                    poster_path = data.get("poster_path", "")
                    poster = f"https://image.tmdb.org/t/p/w500{poster_path}" if poster_path else ""
                    year = (data.get("release_date") or data.get("first_air_date") or "")[:4]
                    rating = data.get("vote_average", "")
                    tmdb_url = f"https://www.themoviedb.org/{media_type}/{item_id}"
                    genres = [g["name"] for g in data.get("genres", [])[:3]]
                    if rating:
                        try:
                            rating_text = f"{float(rating):.1f}"
                        except Exception:
                            rating_text = str(rating)
                        badges_html += f'<span class="share-badge badge-rating">⭐ {rating_text}</span>'
                    if year:
                        badges_html += f'<span class="share-badge badge-year">{year}</span>'
                    if media_type == "movie":
                        runtime_min = data.get("runtime") or 0
                        if runtime_min:
                            badges_html += f'<span class="share-badge badge-runtime">⏱️ {runtime_min} {min_label}</span>'
                    else:
                        seasons = data.get("number_of_seasons") or 0
                        episodes = data.get("number_of_episodes") or 0
                        ep_runtime_list = data.get("episode_run_time") or []
                        ep_runtime = ep_runtime_list[0] if ep_runtime_list else 0
                        if seasons:
                            badges_html += f'<span class="share-badge badge-seasons">📺 {seasons} {seasons_label}</span>'
                        if episodes:
                            badges_html += f'<span class="share-badge badge-seasons">🎞️ {episodes} {episodes_label}</span>'
                        if ep_runtime:
                            badges_html += f'<span class="share-badge badge-runtime">⏱️ {ep_runtime} {min_label}</span>'
                    for g in genres:
                        badges_html += f'<span class="share-badge badge-genre">{_esc(g)}</span>'
        elif item_type == "book":
            book_url = f"https://www.googleapis.com/books/v1/volumes/{item_id}"
            async with httpx.AsyncClient(timeout=8) as client:
                resp = await client.get(book_url)
                if resp.status_code == 200:
                    data = resp.json()
                    vol = data.get("volumeInfo", {})
                    title = vol.get("title", "Book")
                    description = vol.get("description", "")[:300]
                    poster = vol.get("imageLinks", {}).get("thumbnail", "")
                    year = (vol.get("publishedDate", "") or "")[:4]
                    tmdb_url = vol.get("infoLink", "")
                    page_count = vol.get("pageCount") or 0
                    if year:
                        badges_html += f'<span class="share-badge badge-year">{year}</span>'
                    if page_count:
                        badges_html += f'<span class="share-badge badge-pages">📄 {page_count} {pages_label}</span>'
    except Exception:
        pass

    html = SHARE_CARD_HTML
    html = html.replace("{{TITLE}}", _esc(title))
    html = html.replace("{{DESCRIPTION}}", _esc(description))
    html = html.replace("{{POSTER}}", _esc(poster))
    html = html.replace("{{SHARE_URL}}", _esc(share_url))
    html = html.replace("{{QR_URL}}", _esc(qr_url))
    html = html.replace("{{APP_URL}}", _esc(app_url))
    html = html.replace("{{APP_URL_FULL}}", _esc(share_url))
    html = html.replace("{{TMDB_URL}}", _esc(tmdb_url or share_url))
    html = html.replace("{{BADGES_HTML}}", badges_html)
    html = html.replace("{{LANG}}", _esc(lang))
    html = html.replace("{{PICKSY_MASCOT_SVG}}", PICKSY_MASCOT_SVG_INLINE)
    html = html.replace("{{PICKSY_WATERMARK}}", _esc(picksy_watermark_text(lang)))
    return HTMLResponse(html)


