@app.get("/api/me/year-recap")
async def my_year_recap(user=Depends(get_current_user)):
    try:
        conn = get_db()
        with conn.cursor() as cur:
            year_start = f"{today_kyiv().year}-01-01"
            cur.execute("SELECT COUNT(*) AS c FROM pick_history WHERE user_id=%s AND type='movie' AND picked_at>=%s", (user["id"], year_start))
            movies = (cur.fetchone() or {}).get("c", 0)
            cur.execute("SELECT COUNT(*) AS c FROM pick_history WHERE user_id=%s AND type='tv' AND picked_at>=%s", (user["id"], year_start))
            tv = (cur.fetchone() or {}).get("c", 0)
            cur.execute("SELECT COUNT(*) AS c FROM pick_history WHERE user_id=%s AND type='book' AND picked_at>=%s", (user["id"], year_start))
            books = (cur.fetchone() or {}).get("c", 0)
            cur.execute(
                "SELECT title, type, poster, COUNT(*) AS cnt FROM pick_history WHERE user_id=%s AND picked_at>=%s GROUP BY title, type, poster ORDER BY cnt DESC LIMIT 5",
                (user["id"], year_start),
            )
            top_items = cur.fetchall() or []
            cur.execute("SELECT COUNT(*) AS c FROM saved_movies WHERE user_id=%s", (user["id"],))
            saved_movies = (cur.fetchone() or {}).get("c", 0)
            cur.execute("SELECT COUNT(*) AS c FROM saved_tv WHERE user_id=%s", (user["id"],))
            saved_tv = (cur.fetchone() or {}).get("c", 0)
            cur.execute("SELECT COUNT(*) AS c FROM saved_books WHERE user_id=%s", (user["id"],))
            saved_books = (cur.fetchone() or {}).get("c", 0)
        conn.close()
        return {
            "year": today_kyiv().year,
            "username": user.get("username") or user.get("email", "").split("@")[0],
            "picks": {"movies": movies, "tv": tv, "books": books},
            "saved": {"movies": saved_movies, "tv": saved_tv, "books": saved_books},
            "top_items": [{"title": t["title"], "type": t["type"], "poster": t.get("poster", ""), "count": t["cnt"]} for t in top_items],
        }
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.get("/share/year/{username}")
async def share_year_page(username: str):
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT id, username, display_name FROM users WHERE username=%s", (username,))
            u = cur.fetchone()
            if not u:
                raise HTTPException(status_code=404, detail="User not found")
            uid = u["id"]
            display = u.get("display_name") or u.get("username") or username
            year_start = f"{today_kyiv().year}-01-01"
            cur.execute("SELECT COUNT(*) AS c FROM pick_history WHERE user_id=%s AND type='movie' AND picked_at>=%s", (uid, year_start))
            movies = (cur.fetchone() or {}).get("c", 0)
            cur.execute("SELECT COUNT(*) AS c FROM pick_history WHERE user_id=%s AND type='tv' AND picked_at>=%s", (uid, year_start))
            tv = (cur.fetchone() or {}).get("c", 0)
            cur.execute("SELECT COUNT(*) AS c FROM pick_history WHERE user_id=%s AND type='book' AND picked_at>=%s", (uid, year_start))
            books = (cur.fetchone() or {}).get("c", 0)
            cur.execute(
                "SELECT title, type, poster FROM pick_history WHERE user_id=%s AND picked_at>=%s GROUP BY title, type, poster ORDER BY COUNT(*) DESC LIMIT 5",
                (uid, year_start),
            )
            top_items = cur.fetchall() or []
        conn.close()

        top_poster = ""
        top_html = ""
        for i, item in enumerate(top_items, 1):
            p = item.get("poster", "") or ""
            if i == 1 and p:
                top_poster = p
            top_html += f'''<div class="year-top-item">
                <span class="year-top-rank">{i}</span>
                <img class="year-top-poster" src="{_esc(p)}" alt="">
                <div class="year-top-info"><div class="year-top-name">{_esc(item["title"])}</div><div class="year-top-meta">{item["type"]}</div></div>
            </div>'''

        host = _share_host()
        summary = f"{movies} фільмів, {tv} серіалів, {books} книг у {today_kyiv().year}"
        html = MY_YEAR_HTML
        html = html.replace("{{USERNAME}}", _esc(display))
        html = html.replace("{{SUMMARY}}", _esc(summary))
        html = html.replace("{{TOP_POSTER}}", _esc(top_poster))
        html = html.replace("{{MOVIES_COUNT}}", str(movies))
        html = html.replace("{{TV_COUNT}}", str(tv))
        html = html.replace("{{BOOKS_COUNT}}", str(books))
        html = html.replace("{{TOP_ITEMS_HTML}}", top_html)
        html = html.replace("{{GENRES_HTML}}", "")
        html = html.replace("{{HOST}}", _esc(host))
        html = html.replace("{{PICKSY_MASCOT_SVG}}", PICKSY_MASCOT_SVG_INLINE)
        # The My Year card is currently UK-only copy, so we default to uk here.
        html = html.replace("{{PICKSY_WATERMARK}}", _esc(picksy_watermark_text("uk")))
        return HTMLResponse(html)
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


