@app.get("/api/embed/{username}")
async def embed_collection(username: str, type: str = "movies", limit: int = 10):
    if limit > 50:
        limit = 50
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT id FROM users WHERE username=%s", (username,))
            u = cur.fetchone()
            if not u:
                raise HTTPException(status_code=404, detail="User not found")
            uid = u["id"]
            if type == "movies":
                cur.execute("SELECT title, poster, year, rating FROM saved_movies WHERE user_id=%s ORDER BY created_at DESC LIMIT %s", (uid, limit))
            elif type == "tv":
                cur.execute("SELECT title, poster, year, rating FROM saved_tv WHERE user_id=%s ORDER BY created_at DESC LIMIT %s", (uid, limit))
            elif type == "books":
                cur.execute("SELECT title, poster, year, rating FROM saved_books WHERE user_id=%s ORDER BY created_at DESC LIMIT %s", (uid, limit))
            else:
                cur.execute("SELECT title, poster, year, rating FROM saved_movies WHERE user_id=%s ORDER BY created_at DESC LIMIT %s", (uid, limit))
            items = cur.fetchall() or []
        conn.close()
        return {"username": username, "type": type, "items": items}
    except HTTPException:
        raise
    except Exception:
        return {"username": username, "type": type, "items": []}


