# ─── Blog system ───────────────────────────────────────────────────────────

_TRANSLIT_MAP = {
    'а':'a','б':'b','в':'v','г':'h','ґ':'g','д':'d','е':'e','є':'ie',
    'ж':'zh','з':'z','и':'y','і':'i','ї':'i','й':'y','к':'k','л':'l',
    'м':'m','н':'n','о':'o','п':'p','р':'r','с':'s','т':'t','у':'u',
    'ф':'f','х':'kh','ц':'ts','ч':'ch','ш':'sh','щ':'shch','ь':'',
    'ю':'yu','я':'ya',
}


def _generate_slug(title: str) -> str:
    t = title.lower()
    result = ''
    for ch in t:
        result += _TRANSLIT_MAP.get(ch, ch)
    result = re.sub(r'[^a-z0-9\s\-]', '', result)
    result = re.sub(r'[\s\-]+', '-', result).strip('-')
    return result[:200] or 'post'


def _unique_slug(base: str, exclude_id: int = None) -> str:
    conn = get_db()
    slug = base
    n = 2
    while True:
        try:
            with conn.cursor() as cur:
                if exclude_id:
                    cur.execute("SELECT id FROM blog_posts WHERE slug=%s AND id!=%s LIMIT 1", (slug, exclude_id))
                else:
                    cur.execute("SELECT id FROM blog_posts WHERE slug=%s LIMIT 1", (slug,))
                row = cur.fetchone()
        except Exception:
            row = None
        finally:
            try: conn.close()
            except Exception: pass
        if not row:
            return slug
        slug = f"{base}-{n}"
        n += 1
        conn = get_db()


def _blog_row_to_dict(row: dict) -> dict:
    if not row:
        return {}
    d = dict(row)
    for f in ('created_at', 'updated_at'):
        if f in d and d[f] is not None:
            try:
                d[f] = d[f].isoformat()
            except Exception:
                d[f] = str(d[f])
    return d


def _parse_loose_json(raw: str) -> dict:
    """Parse a JSON object string returned by an LLM, tolerating common
    issues (raw newlines/tabs inside strings, trailing commas, smart
    quotes). Used by the blog AI / SEO generators because the model
    occasionally emits multi-line HTML inside the ``content`` field
    without escaping the line breaks."""
    if raw is None:
        raise json.JSONDecodeError("empty payload", "", 0)
    s = raw.strip()
    if s.startswith('\ufeff'):
        s = s[1:]
    # First attempt: lenient parser (allows control chars inside strings).
    try:
        return json.loads(s, strict=False)
    except json.JSONDecodeError:
        pass
    # Second attempt: drop trailing commas the model may have left behind.
    fixed = re.sub(r',\s*([}\]])', r'\1', s)
    try:
        return json.loads(fixed, strict=False)
    except json.JSONDecodeError:
        pass
    # Third attempt: rewrite raw control characters that fall inside string
    # values into their escaped JSON form. We walk the buffer character by
    # character so we don't touch control chars that are already escaped or
    # that live outside a string.
    out = []
    in_string = False
    escape = False
    for ch in fixed:
        if in_string:
            if escape:
                out.append(ch)
                escape = False
                continue
            if ch == '\\':
                out.append(ch)
                escape = True
                continue
            if ch == '"':
                out.append(ch)
                in_string = False
                continue
            code = ord(ch)
            if code < 0x20:
                if ch == '\n':
                    out.append('\\n')
                elif ch == '\r':
                    out.append('\\r')
                elif ch == '\t':
                    out.append('\\t')
                else:
                    out.append('\\u%04x' % code)
                continue
            out.append(ch)
        else:
            if ch == '"':
                in_string = True
            out.append(ch)
    sanitized = ''.join(out)
    try:
        return json.loads(sanitized, strict=False)
    except json.JSONDecodeError:
        pass
    # Fourth attempt: regex-based field extraction for known blog JSON schema.
    # The AI often puts unescaped double quotes inside HTML content values
    # (e.g. class="title"), breaking standard JSON parsing.
    fields = ['title', 'content', 'excerpt', 'tags', 'content_type',
              'meta_title', 'meta_description', 'meta_keywords']
    result = {}
    for i, field in enumerate(fields):
        pat = re.compile(
            r'"' + re.escape(field) + r'"\s*:\s*"', re.DOTALL
        )
        m = pat.search(sanitized)
        if not m:
            continue
        start = m.end()
        # Walk forward to find the closing quote that's followed by
        # , or } (with optional whitespace) — skip escaped quotes.
        pos = start
        depth = 0
        while pos < len(sanitized):
            ch = sanitized[pos]
            if ch == '\\':
                pos += 2
                continue
            if ch == '"':
                # Check if this quote is followed by comma/closing brace/next field
                rest = sanitized[pos + 1:].lstrip()
                if rest and rest[0] in (',', '}'):
                    break
                # Check if next thing is a known field key like "title":
                next_field_pat = re.match(r'\s*"(' + '|'.join(re.escape(f) for f in fields) + r')"\s*:', sanitized[pos + 1:])
                if next_field_pat:
                    break
                # Otherwise it's an unescaped quote inside the value — skip it
                pos += 1
                continue
            pos += 1
        val = sanitized[start:pos]
        # Unescape
        try:
            result[field] = json.loads('"' + val + '"', strict=False)
        except json.JSONDecodeError:
            result[field] = val.replace('\\n', '\n').replace('\\"', '"')
    if result.get('title') and result.get('content'):
        return result
    raise json.JSONDecodeError("could not parse AI response", sanitized[:200], 0)


def _is_blog_editor(user: dict) -> bool:
    if not user:
        return False
    if user.get('is_admin'):
        return True
    role = user.get('role', '') or ''
    return role in ('admin', 'superadmin', 'editor', 'content-manager')


