@app.get("/api/blog")
async def public_blog_list(page: int = 1, per_page: int = 10, tag: Optional[str] = None):
    per_page = max(1, min(per_page, 50))
    offset = (max(1, page) - 1) * per_page
    conn = get_db()
    try:
        with conn.cursor() as cur:
            if tag:
                cur.execute(
                    "SELECT COUNT(*) AS c FROM blog_posts WHERE is_published=1 AND FIND_IN_SET(%s, tags)",
                    (tag.strip(),)
                )
            else:
                cur.execute("SELECT COUNT(*) AS c FROM blog_posts WHERE is_published=1")
            total = (cur.fetchone() or {}).get('c', 0)

            if tag:
                cur.execute(
                    "SELECT id,title,slug,excerpt,cover_image,tags,content_type,is_ai_generated,views,created_at "
                    "FROM blog_posts WHERE is_published=1 AND FIND_IN_SET(%s, tags) "
                    "ORDER BY created_at DESC LIMIT %s OFFSET %s",
                    (tag.strip(), per_page, offset)
                )
            else:
                cur.execute(
                    "SELECT id,title,slug,excerpt,cover_image,tags,content_type,is_ai_generated,views,created_at "
                    "FROM blog_posts WHERE is_published=1 "
                    "ORDER BY created_at DESC LIMIT %s OFFSET %s",
                    (per_page, offset)
                )
            rows = cur.fetchall() or []
    finally:
        conn.close()
    posts = [_blog_row_to_dict(r) for r in rows]
    return {
        "posts": posts,
        "total": total,
        "page": page,
        "per_page": per_page,
        "total_pages": max(1, (total + per_page - 1) // per_page),
    }


@app.get("/api/blog/{slug}")
async def public_blog_post(slug: str, request: Request):
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT * FROM blog_posts WHERE slug=%s LIMIT 1", (slug,))
            row = cur.fetchone()
    finally:
        conn.close()
    if not row:
        raise HTTPException(status_code=404, detail="Post not found")
    if not row.get('is_published'):
        token = request.headers.get('Authorization', '').replace('Bearer ', '').strip()
        is_admin = False
        if token:
            try:
                conn2 = get_db()
                with conn2.cursor() as cur2:
                    cur2.execute("SELECT is_admin, role FROM users WHERE token=%s LIMIT 1", (token,))
                    u = cur2.fetchone()
                    is_admin = bool(u and (u.get('is_admin') or u.get('role') in ('admin','superadmin','editor','content-manager')))
                conn2.close()
            except Exception:
                pass
        if not is_admin:
            raise HTTPException(status_code=404, detail="Post not found")
    conn3 = get_db()
    try:
        with conn3.cursor() as cur3:
            cur3.execute("UPDATE blog_posts SET views=views+1 WHERE slug=%s", (slug,))
        conn3.commit()
    except Exception:
        pass
    finally:
        conn3.close()
    post = _blog_row_to_dict(row)
    post['views'] = (post.get('views') or 0) + 1
    return post


@app.get("/blog/{slug}", response_class=HTMLResponse)
async def blog_post_ssr(slug: str):
    site = os.getenv("SITE_DOMAIN", "https://picksy.my")
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT * FROM blog_posts WHERE slug=%s AND is_published=1 LIMIT 1", (slug,))
            row = cur.fetchone()
    finally:
        conn.close()
    if not row:
        return HTMLResponse(
            _error_page_html(404, "Статтю не знайдено", "Можливо, вона була видалена або переміщена.", "📝"),
            status_code=404,
        )
    p = _blog_row_to_dict(row)
    post_id = p.get('id')
    title = html.escape(p.get('meta_title') or p.get('title') or 'Picksy Blog')
    desc = html.escape(p.get('meta_description') or p.get('excerpt') or '')
    kw = html.escape(p.get('meta_keywords') or p.get('tags') or '')
    og_img = html.escape(p.get('og_image') or p.get('cover_image') or f'{site}/og/default-blog.png')
    canonical = f"{site}/blog/{html.escape(slug)}"
    pub_date = str(p.get('created_at') or '')[:10]
    mod_date = str(p.get('updated_at') or pub_date)[:10]
    content_html = p.get('content') or ''
    # If the post was created before TMDB-enrichment shipped (or with markers
    # that fell through), resolve any leftover [[MOVIE:...]] / [[TV:...]]
    # tokens at render time. Already-resolved anchors are untouched.
    mentions: list[dict] = []
    try:
        content_html, mentions = await _enrich_blog_content_with_links(content_html)
    except Exception:
        pass
    mentions_html = _render_mentions_section(mentions)

    # Reading-time estimate: strip HTML, count words, divide by ~200 wpm.
    # Used both for the on-page badge and for schema.org `timeRequired`.
    plain_text = _re_blog.sub(r"<[^>]+>", " ", content_html or "")
    plain_text = _re_blog.sub(r"\s+", " ", plain_text).strip()
    word_count = len(plain_text.split()) if plain_text else 0
    read_min = max(1, round(word_count / 200)) if word_count else 1

    # Related posts: pick up to 3 other published posts that share at least
    # one tag with the current one, falling back to the latest if there's no
    # tag overlap.  Sorted by tag-match-count DESC, then by recency.
    related_posts: list[dict] = []
    try:
        current_tags = [t.strip().lower() for t in (p.get('tags') or '').split(',') if t.strip()]
        conn2 = get_db()
        with conn2.cursor() as cur2:
            cur2.execute(
                "SELECT id, slug, title, excerpt, cover_image, tags, created_at "
                "FROM blog_posts "
                "WHERE is_published=1 AND id <> %s "
                "ORDER BY created_at DESC LIMIT 50",
                (post_id,),
            )
            cand = cur2.fetchall() or []
        conn2.close()
        scored = []
        for c in cand:
            c_tags = [t.strip().lower() for t in (c.get('tags') or '').split(',') if t.strip()]
            score = sum(1 for t in c_tags if t in current_tags)
            scored.append((score, c))
        # Sort: most tag-overlap first, then most recent.
        scored.sort(key=lambda x: (-x[0], -(x[1].get('id') or 0)))
        for _s, c in scored[:3]:
            related_posts.append(c)
    except Exception:
        related_posts = []

    related_html = ""
    if related_posts:
        cards = []
        for rp in related_posts:
            r_slug = html.escape((rp.get('slug') or '').strip())
            r_title = html.escape((rp.get('title') or '').strip())
            r_excerpt = html.escape(((rp.get('excerpt') or '')[:140]).strip())
            r_cover = (rp.get('cover_image') or '').strip() or f'{site}/og/default-blog.png'
            r_date = str(rp.get('created_at') or '')[:10]
            cover_inner = (
                f'<img src="{html.escape(r_cover)}" alt="{r_title}" loading="lazy">'
            )
            cards.append(
                f'<a class="bp-related-card" href="/blog/{r_slug}">'
                f'<div class="bp-related-cover">{cover_inner}</div>'
                f'<div class="bp-related-body">'
                f'<h3 class="bp-related-title">{r_title}</h3>'
                f'<p class="bp-related-excerpt">{r_excerpt}</p>'
                f'<div class="bp-related-meta"><span>📅 {r_date}</span></div>'
                f'</div></a>'
            )
        related_html = (
            '<section class="bp-related"><h2>📖 Читай також</h2>'
            '<div class="bp-related-grid">' + "".join(cards) + '</div></section>'
        )
    # If the post has no `cover_image`, fall back to the shared Picksy blog
    # OG banner — same one as the open-graph card — so the article never
    # renders headless.
    cover_url = (p.get('cover_image') or '').strip() or f'{site}/og/default-blog.png'
    tags_chips = ''
    raw_tags = (p.get('tags') or '').strip()
    if raw_tags:
        tag_items = [t.strip() for t in raw_tags.split(',') if t.strip()][:8]
        tags_chips = '<div class="bp-tags">' + ''.join(
            f'<span class="bp-tag">#{html.escape(t)}</span>' for t in tag_items
        ) + '</div>'
    cover_block = (
        f'<div class="bp-cover"><img src="{html.escape(cover_url)}" alt="{html.escape(p.get("title") or "")}" loading="eager" decoding="async"></div>'
    )
    excerpt_block = (
        f'<p class="bp-excerpt">{html.escape(p.get("excerpt") or "")}</p>'
        if (p.get('excerpt') or '').strip() else ''
    )
    json_ld_dict = {
        "@context": "https://schema.org",
        "@type": "Article",
        "headline": p.get('title') or '',
        "description": p.get('meta_description') or p.get('excerpt') or '',
        "image": p.get('og_image') or p.get('cover_image') or f'{site}/og/default-blog.png',
        "datePublished": pub_date,
        "dateModified": mod_date,
        "author": {"@type": "Organization", "name": "Picksy", "@id": f"{site}/#organization"},
        "publisher": {
            "@type": "Organization",
            "name": "Picksy",
            "@id": f"{site}/#organization",
            "logo": {"@type": "ImageObject", "url": f"{site}/og-image.png"}
        },
        "mainEntityOfPage": {"@type": "WebPage", "@id": canonical},
        "isPartOf": {"@id": f"{site}/blog#blog"},
        "wordCount": word_count,
        "timeRequired": f"PT{read_min}M",
        "inLanguage": "uk",
        "keywords": (p.get('meta_keywords') or p.get('tags') or '').strip(),
    }
    if mentions:
        json_ld_dict["mentions"] = [
            {
                "@type": "Movie" if m["media"] == "movie" else "TVSeries",
                "name": m["title"],
                "sameAs": f"https://www.themoviedb.org/{m['media']}/{m['tmdb_id']}",
            } for m in mentions[:20]
        ]
    json_ld = json.dumps(json_ld_dict, ensure_ascii=False)
    from urllib.parse import quote_plus as _qp
    share_url = canonical
    share_url_enc = _qp(canonical)
    share_title_enc = _qp((p.get('title') or '').strip())
    ssr_html = f"""<!DOCTYPE html>
<html lang="uk">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1.0">
<title>{title} — Picksy Blog</title>
<meta name="description" content="{desc}">
<meta name="keywords" content="{kw}">
<meta name="robots" content="index, follow, max-image-preview:large">
<link rel="canonical" href="{canonical}">
<meta property="og:type" content="article">
<meta property="og:title" content="{title}">
<meta property="og:description" content="{desc}">
<meta property="og:image" content="{og_img}">
<meta property="og:image:width" content="1200">
<meta property="og:image:height" content="630">
<meta property="og:url" content="{canonical}">
<meta property="og:site_name" content="Picksy">
<meta property="article:published_time" content="{pub_date}">
<meta property="article:modified_time" content="{mod_date}">
<meta name="twitter:card" content="summary_large_image">
<meta name="twitter:title" content="{title}">
<meta name="twitter:description" content="{desc}">
<meta name="twitter:image" content="{og_img}">
<link rel="icon" href="data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><text y='.9em' font-size='90'>%F0%9F%8E%AC</text></svg>" type="image/svg+xml">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">
<script type="application/ld+json">{json_ld}</script>
<style>
*,*::before,*::after{{box-sizing:border-box;margin:0;padding:0}}
:root{{
  --bg:#060614;--text:#f5f5ff;--text-dim:rgba(245,245,255,.74);--text-muted:rgba(245,245,255,.45);
  --glass:rgba(255,255,255,.045);--glass-deep:rgba(255,255,255,.07);--glass-border:rgba(255,255,255,.09);
  --accent:#8b5cf6;--accent-light:#a78bfa;--accent2:#ec4899;--accent3:#06d6a0;
  --radius:18px;--radius-sm:12px;
  --gradient:linear-gradient(135deg,#8b5cf6 0%,#ec4899 50%,#06d6a0 100%);
}}
html{{scroll-behavior:smooth;background:var(--bg)}}
body{{background:var(--bg);color:var(--text);font-family:'Inter',system-ui,-apple-system,Segoe UI,Roboto,sans-serif;line-height:1.7;overflow-x:hidden;-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale}}
.bp-bg-fx{{position:fixed;inset:0;z-index:0;pointer-events:none;overflow:hidden}}
.bp-blob{{position:absolute;border-radius:50%;filter:blur(120px);opacity:.22;will-change:transform}}
.bp-blob-1{{width:520px;height:520px;background:#8b5cf6;top:-160px;left:-120px}}
.bp-blob-2{{width:460px;height:460px;background:#ec4899;bottom:-160px;right:-140px}}
.bp-blob-3{{width:360px;height:360px;background:#06d6a0;top:48%;left:54%;transform:translate(-50%,-50%);opacity:.12}}
.bp-wrap{{position:relative;z-index:2;max-width:880px;margin:0 auto;padding:28px 22px 100px}}
.bp-nav{{display:flex;align-items:center;gap:14px;margin-bottom:22px}}
.bp-back{{display:inline-flex;align-items:center;gap:6px;color:var(--accent-light);text-decoration:none;font-size:.95rem;font-weight:600;padding:8px 14px;border:1px solid var(--glass-border);border-radius:999px;background:var(--glass);transition:.2s}}
.bp-back:hover{{border-color:rgba(167,139,250,.5);background:rgba(167,139,250,.08)}}
.bp-brand{{margin-left:auto;color:var(--text-muted);font-size:.85rem;text-decoration:none}}
.bp-brand b{{color:var(--text);font-weight:800}}
.bp-meta{{display:flex;align-items:center;gap:14px;flex-wrap:wrap;font-size:.85rem;color:var(--text-muted);margin-bottom:18px}}
.bp-meta .bp-dot{{width:4px;height:4px;border-radius:50%;background:currentColor;opacity:.4}}
.bp-meta time{{color:var(--text-dim)}}
.bp-title{{font-size:clamp(1.85rem,4.2vw,3rem);line-height:1.12;font-weight:900;margin:8px 0 18px;letter-spacing:-.02em}}
.bp-title{{background:linear-gradient(135deg,#fff 0%,#fff 40%,#a78bfa 100%);-webkit-background-clip:text;background-clip:text;color:transparent}}
.bp-excerpt{{font-size:1.1rem;color:var(--text-dim);margin:0 0 24px;line-height:1.6}}
.bp-tags{{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:24px}}
.bp-tag{{font-size:.78rem;font-weight:600;padding:5px 12px;border-radius:999px;background:rgba(139,92,246,.12);color:var(--accent-light);border:1px solid rgba(139,92,246,.22)}}
.bp-cover{{margin:0 0 32px;border-radius:var(--radius);overflow:hidden;border:1px solid var(--glass-border);background:var(--glass)}}
.bp-cover img{{display:block;width:100%;height:auto;max-height:520px;object-fit:cover}}
.bp-article{{font-size:1.05rem;color:var(--text-dim);line-height:1.8}}
.bp-article h1,.bp-article h2,.bp-article h3,.bp-article h4{{color:var(--text);font-weight:800;line-height:1.25;margin:1.7em 0 .55em;letter-spacing:-.01em}}
.bp-article h2{{font-size:clamp(1.4rem,2.6vw,1.85rem);padding-bottom:.4em;border-bottom:1px solid var(--glass-border)}}
.bp-article h3{{font-size:1.3rem}}
.bp-article h4{{font-size:1.1rem;color:var(--accent-light)}}
.bp-article p{{margin:.95em 0}}
.bp-article p:first-child{{margin-top:0}}
.bp-article ul,.bp-article ol{{margin:1em 0;padding-left:1.6em}}
.bp-article li{{margin:.4em 0}}
.bp-article li::marker{{color:var(--accent-light)}}
.bp-article a{{color:var(--accent-light);text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:3px;text-decoration-color:rgba(167,139,250,.45);transition:.15s}}
.bp-article a:hover{{color:#fff;text-decoration-color:#fff}}
.bp-article a.picksy-film-link{{color:#fff;text-decoration:none;font-weight:600;background:linear-gradient(135deg,rgba(139,92,246,.22),rgba(236,72,153,.18));padding:1px 8px;border-radius:6px;border:1px solid rgba(139,92,246,.35);box-shadow:0 1px 0 rgba(255,255,255,.04) inset;transition:.18s}}
.bp-article a.picksy-film-link::before{{content:"🎬 ";font-size:.85em;opacity:.85}}
.bp-article a.picksy-film-link:hover{{background:linear-gradient(135deg,rgba(139,92,246,.42),rgba(236,72,153,.32));border-color:rgba(236,72,153,.55);transform:translateY(-1px)}}
.bp-article blockquote{{border-left:3px solid var(--accent);padding:.3em 0 .3em 1.2em;margin:1.3em 0;color:var(--text-dim);font-style:italic;background:rgba(139,92,246,.06);border-radius:0 12px 12px 0}}
.bp-article code{{background:rgba(255,255,255,.06);padding:1px 6px;border-radius:6px;font-size:.92em;font-family:ui-monospace,SFMono-Regular,Menlo,monospace}}
.bp-article pre{{background:#0d0d22;border:1px solid var(--glass-border);border-radius:12px;padding:14px 16px;overflow:auto;margin:1.2em 0}}
.bp-article pre code{{background:transparent;padding:0}}
.bp-article img{{max-width:100%;height:auto;border-radius:12px;margin:1.2em 0;border:1px solid var(--glass-border)}}
.bp-article hr{{border:0;height:1px;background:var(--glass-border);margin:2em 0}}
/* Mentioned-films section ------------------------------------------------ */
.picksy-mentions{{margin:48px 0 16px;padding:24px;background:linear-gradient(135deg,rgba(139,92,246,.07),rgba(236,72,153,.05));border:1px solid var(--glass-border);border-radius:var(--radius)}}
.picksy-mentions > h2{{font-size:1.35rem!important;margin:0 0 16px!important;border:0!important;padding:0!important;color:var(--text)!important}}
.picksy-mentions-grid{{display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:14px}}
.picksy-film-card{{display:flex;flex-direction:column;text-decoration:none;color:var(--text);background:rgba(255,255,255,.04);border:1px solid var(--glass-border);border-radius:14px;overflow:hidden;transition:.18s;will-change:transform}}
.picksy-film-card:hover{{transform:translateY(-3px);border-color:rgba(167,139,250,.55);box-shadow:0 10px 30px -10px rgba(139,92,246,.4)}}
.picksy-film-card .pfc-poster{{position:relative;width:100%;aspect-ratio:2/3;background:linear-gradient(135deg,#1a1430,#0a0a18);overflow:hidden}}
.picksy-film-card .pfc-poster img{{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block;margin:0;border:0;border-radius:0}}
.picksy-film-card .pfc-no-poster{{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:2.4rem;opacity:.4}}
.picksy-film-card .pfc-rating{{position:absolute;top:8px;right:8px;background:rgba(0,0,0,.7);backdrop-filter:blur(8px);color:#fbbf24;font-weight:700;font-size:.78rem;padding:3px 8px;border-radius:999px;border:1px solid rgba(255,255,255,.08)}}
.picksy-film-card .pfc-body{{padding:10px 12px 12px;display:flex;flex-direction:column;gap:3px}}
.picksy-film-card .pfc-media{{font-size:.7rem;text-transform:uppercase;letter-spacing:.06em;color:var(--accent-light);font-weight:700}}
.picksy-film-card .pfc-title{{font-size:.95rem;font-weight:700;line-height:1.25;color:var(--text);overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}}
.picksy-film-card .pfc-meta{{font-size:.78rem;color:var(--text-muted)}}
/* Footer / share --------------------------------------------------------- */
.bp-footer{{margin-top:48px;padding-top:24px;border-top:1px solid var(--glass-border)}}
.bp-share-row{{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin-bottom:30px}}
.bp-share-row span{{color:var(--text-muted);font-size:.88rem;margin-right:4px}}
.bp-share-btn{{display:inline-flex;align-items:center;gap:6px;padding:8px 14px;border-radius:999px;background:var(--glass);border:1px solid var(--glass-border);color:var(--text);text-decoration:none;font-size:.85rem;font-weight:600;transition:.15s;cursor:pointer}}
.bp-share-btn:hover{{border-color:rgba(167,139,250,.55);background:rgba(167,139,250,.08)}}
.bp-cta{{margin-top:18px;padding:24px;border-radius:var(--radius);background:linear-gradient(135deg,rgba(139,92,246,.16),rgba(236,72,153,.1));border:1px solid rgba(139,92,246,.25);display:flex;flex-direction:column;gap:6px}}
.bp-cta h3{{font-size:1.15rem;margin:0;font-weight:800}}
.bp-cta p{{margin:0;color:var(--text-dim);font-size:.95rem}}
.bp-cta a{{display:inline-flex;align-items:center;gap:6px;margin-top:10px;align-self:flex-start;padding:11px 22px;background:var(--gradient);color:#fff;text-decoration:none;border-radius:999px;font-weight:700;font-size:.95rem;transition:.15s}}
.bp-cta a:hover{{transform:translateY(-2px);box-shadow:0 10px 30px -8px rgba(139,92,246,.5)}}
/* Reading progress bar: sticky top 4px line that fills as user scrolls. */
.bp-progress{{position:fixed;top:0;left:0;height:3px;width:0%;background:var(--gradient);z-index:9999;transition:width .08s linear;will-change:width;box-shadow:0 0 12px rgba(167,139,250,.6)}}
/* Reading-time badge in the meta line */
.bp-readtime{{display:inline-flex;align-items:center;gap:4px;color:var(--accent-light);font-weight:600}}
/* Related posts grid */
.bp-related{{margin:56px 0 12px;padding-top:32px;border-top:1px solid var(--glass-border)}}
.bp-related > h2{{font-size:1.35rem;margin:0 0 18px;font-weight:800;color:var(--text)}}
.bp-related-grid{{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:16px}}
.bp-related-card{{display:flex;flex-direction:column;text-decoration:none;color:var(--text);background:var(--glass-deep);border:1px solid var(--glass-border);border-radius:14px;overflow:hidden;transition:.2s;will-change:transform}}
.bp-related-card:hover{{transform:translateY(-3px);border-color:rgba(167,139,250,.5);box-shadow:0 12px 30px -10px rgba(139,92,246,.35)}}
.bp-related-cover{{position:relative;width:100%;aspect-ratio:16/9;background:linear-gradient(135deg,#1a1430,#0a0a18);overflow:hidden}}
.bp-related-cover img{{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block;margin:0;border:0;border-radius:0}}
.bp-related-cover-fallback{{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:2.4rem;opacity:.3}}
.bp-related-body{{padding:12px 14px 14px;display:flex;flex-direction:column;gap:6px;flex:1}}
.bp-related-title{{font-size:.98rem;font-weight:800;line-height:1.3;color:var(--text);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;margin:0}}
.bp-related-excerpt{{color:var(--text-dim);font-size:.82rem;line-height:1.45;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;margin:0}}
.bp-related-meta{{font-size:.72rem;color:var(--text-muted);margin-top:auto}}
@media(max-width:540px){{
  .bp-wrap{{padding:18px 14px 80px}}
  .picksy-mentions{{padding:18px 14px}}
  .picksy-mentions-grid{{grid-template-columns:repeat(2,1fr);gap:10px}}
  .bp-cover img{{max-height:280px}}
  .bp-related-grid{{grid-template-columns:1fr}}
}}
@media (prefers-reduced-motion: reduce){{
  *{{transition:none!important;animation:none!important}}
}}
</style>
</head>
<body>
<div class="bp-progress" id="bp-progress" aria-hidden="true"></div>
<div class="bp-bg-fx" aria-hidden="true">
  <div class="bp-blob bp-blob-1"></div>
  <div class="bp-blob bp-blob-2"></div>
  <div class="bp-blob bp-blob-3"></div>
</div>
<article class="bp-wrap">
  <nav class="bp-nav">
    <a class="bp-back" href="/blog">← Блог Picksy</a>
    <a class="bp-brand" href="/"><b>Picksy</b> · AI-куратор кіно</a>
  </nav>
  <div class="bp-meta">
    <time datetime="{pub_date}">{pub_date}</time>
    <span class="bp-dot"></span>
    <span>Picksy</span>
    <span class="bp-dot"></span>
    <span class="bp-readtime">⏱ {read_min} хв читання</span>
    {('<span class="bp-dot"></span><span>🤖 AI</span>' if p.get('is_ai_generated') else '')}
  </div>
  <h1 class="bp-title">{html.escape(p.get('title') or '')}</h1>
  {excerpt_block}
  {tags_chips}
  {cover_block}
  <div class="bp-article">{content_html}</div>
  {mentions_html}
  {related_html}
  <footer class="bp-footer">
    <div class="bp-share-row">
      <span>Поділитися:</span>
      <a class="bp-share-btn" href="https://t.me/share/url?url={share_url_enc}&text={share_title_enc}" target="_blank" rel="noopener">✈️ Telegram</a>
      <a class="bp-share-btn" href="https://twitter.com/intent/tweet?url={share_url_enc}&text={share_title_enc}" target="_blank" rel="noopener">𝕏 Twitter</a>
      <a class="bp-share-btn" href="https://www.facebook.com/sharer/sharer.php?u={share_url_enc}" target="_blank" rel="noopener">📘 Facebook</a>
      <button type="button" class="bp-share-btn" id="bp-copy-btn">🔗 Копіювати лінк</button>
    </div>
    <div class="bp-cta">
      <h3>Не знаєш що дивитися?</h3>
      <p>Picksy — AI-куратор кіно, серіалів та книг. Підбірка за настрій за 5 секунд.</p>
      <a href="/">🎬 Підібрати зараз →</a>
    </div>
  </footer>
</article>
<script>
(function(){{
  var btn=document.getElementById('bp-copy-btn');
  if(btn){{btn.addEventListener('click',function(){{
    var u={share_url!r};
    if(navigator.clipboard){{navigator.clipboard.writeText(u).then(function(){{btn.textContent='✓ Скопійовано';setTimeout(function(){{btn.textContent='🔗 Копіювати лінк'}},1800)}})}}
    else{{var t=document.createElement('textarea');t.value=u;document.body.appendChild(t);t.select();try{{document.execCommand('copy');btn.textContent='✓ Скопійовано';setTimeout(function(){{btn.textContent='🔗 Копіювати лінк'}},1800)}}catch(e){{}}t.remove()}}
  }})}}
  /* Reading progress bar — updates the .bp-progress width based on scroll.
     Throttled with requestAnimationFrame so the listener never costs more
     than one frame per scroll tick. */
  var bar=document.getElementById('bp-progress');
  if(bar){{
    var ticking=false;
    function update(){{
      var h=document.documentElement;
      var max=(h.scrollHeight-h.clientHeight);
      var pct=max>0?Math.min(100,Math.max(0,(window.scrollY||h.scrollTop)/max*100)):0;
      bar.style.width=pct.toFixed(2)+'%';
      ticking=false;
    }}
    window.addEventListener('scroll',function(){{
      if(!ticking){{requestAnimationFrame(update);ticking=true}}
    }},{{passive:true}});
    update();
  }}
}})();
</script>
</body>
</html>"""
    return HTMLResponse(ssr_html)


# ─── Blog: TMDB enrichment ───
# AI generates posts with [[MOVIE:Title (Year)]] / [[TV:Title]] markers.
# We post-process them server-side by looking each title up in TMDB, then
# replace the marker with an inline anchor to /descmovie/{id} or /desctv/{id}.
# Failed lookups fall back to plain text (the title) so the post never breaks.

import re as _re_blog

_TMDB_BLOG_CACHE: dict[tuple, dict | None] = {}
_BLOG_MARKER_RE = _re_blog.compile(r"\[\[(MOVIE|TV)\s*:\s*([^\]\n]{1,200})\]\]", _re_blog.IGNORECASE)


async def _tmdb_lookup_for_blog(media: str, query: str) -> dict | None:
    """Search TMDB and return a small dict with id/title/poster/rating/genres/year
    for the *first* result. Memoised per (media, normalized-query).

    Returns None if TMDB isn't configured, the query is empty, or no match
    was found.  Errors are swallowed silently so a flaky TMDB never breaks
    blog publishing.
    """
    if not TMDB_API_KEY or not query:
        return None
    media = (media or "").lower().strip()
    if media not in ("movie", "tv"):
        return None
    # Pull a possible "(2010)" suffix off the title and pass it as `year` to
    # TMDB — drastically improves accuracy for sequels and remakes.
    year_match = _re_blog.search(r"\((\d{4})\)\s*$", query)
    year = year_match.group(1) if year_match else None
    clean = _re_blog.sub(r"\((\d{4})\)\s*$", "", query).strip().strip(",;:-—–").strip()
    if not clean:
        return None
    cache_key = (media, clean.lower(), year or "")
    if cache_key in _TMDB_BLOG_CACHE:
        return _TMDB_BLOG_CACHE[cache_key]
    try:
        search_params = {"query": clean, "language": "uk", "include_adult": "false"}
        if year:
            search_params["year" if media == "movie" else "first_air_date_year"] = year
        async with httpx.AsyncClient(timeout=8) as client:
            r = await client.get(
                f"https://api.themoviedb.org/3/search/{media}",
                params=_tmdb_params(search_params),
                headers=_tmdb_headers(),
            )
            if r.status_code != 200:
                _TMDB_BLOG_CACHE[cache_key] = None
                return None
            results = (r.json() or {}).get("results") or []
            if not results:
                # Retry once in English — TMDB sometimes mis-matches UA titles.
                r2 = await client.get(
                    f"https://api.themoviedb.org/3/search/{media}",
                    params=_tmdb_params({**search_params, "language": "en-US"}),
                    headers=_tmdb_headers(),
                )
                if r2.status_code == 200:
                    results = (r2.json() or {}).get("results") or []
            if not results:
                _TMDB_BLOG_CACHE[cache_key] = None
                return None
            top = results[0]
            tmdb_id = top.get("id")
            if not tmdb_id:
                _TMDB_BLOG_CACHE[cache_key] = None
                return None
            # Pull full details for genres + runtime + tagline
            d = await client.get(
                f"https://api.themoviedb.org/3/{media}/{tmdb_id}",
                params=_tmdb_params({"language": "uk-UA"}),
                headers=_tmdb_headers(),
            )
            detail = d.json() if d.status_code == 200 else {}
            title_key = "title" if media == "movie" else "name"
            date_key = "release_date" if media == "movie" else "first_air_date"
            release_year = (detail.get(date_key) or top.get(date_key) or "")[:4]
            info = {
                "media": media,
                "tmdb_id": int(tmdb_id),
                "title": detail.get(title_key) or top.get(title_key) or clean,
                "original_title": detail.get("original_" + title_key) or top.get("original_" + title_key) or "",
                "poster": f"https://image.tmdb.org/t/p/w342{top.get('poster_path')}" if top.get("poster_path") else "",
                "year": release_year,
                "rating": round(float(top.get("vote_average") or 0), 1) or None,
                "vote_count": int(top.get("vote_count") or 0),
                "genres": ", ".join((g.get("name") or "").strip()
                                    for g in (detail.get("genres") or []) if g.get("name"))[:200],
                "overview": (detail.get("overview") or top.get("overview") or "")[:400],
            }
            _TMDB_BLOG_CACHE[cache_key] = info
            return info
    except Exception:
        _TMDB_BLOG_CACHE[cache_key] = None
        return None


_TMDB_DISCOVER_CACHE: dict[tuple, list[dict]] = {}


def _weighted_rating(vote_avg: float, vote_count: int, mean_rating: float = 6.5, min_votes: int = 300) -> float:
    """Bayesian weighted rating (IMDB formula). Prevents films with very
    few votes from topping the list just because 3 people gave them 10/10."""
    v = vote_count
    m = min_votes
    R = vote_avg
    C = mean_rating
    return round((v / (v + m)) * R + (m / (v + m)) * C, 3)


async def _web_search_top_titles(query: str, count: int = 20) -> list[str]:
    """Search the web (DuckDuckGo HTML) for the given query and extract
    film/series titles mentioned in the results. Returns a list of title
    strings (best-effort, may be empty on failure)."""
    try:
        async with httpx.AsyncClient(timeout=10, follow_redirects=True) as client:
            r = await client.get(
                "https://html.duckduckgo.com/html/",
                params={"q": query},
                headers={"User-Agent": "Mozilla/5.0 (compatible; PicksyBot/1.0)"},
            )
            if r.status_code != 200:
                return []
            text = r.text
            snippets: list[str] = []
            for m in _re_blog.finditer(r'class="result__snippet"[^>]*>(.*?)</a', text, _re_blog.DOTALL):
                clean = _re_blog.sub(r'<[^>]+>', '', m.group(1)).strip()
                if clean and len(clean) > 20:
                    snippets.append(clean[:200])
            for m in _re_blog.finditer(r'class="result__a"[^>]*>(.*?)</a', text, _re_blog.DOTALL):
                clean = _re_blog.sub(r'<[^>]+>', '', m.group(1)).strip()
                if clean and len(clean) > 5:
                    snippets.append(clean[:120])
            return snippets[:8]
    except Exception:
        return []


_WEB_SEARCH_CACHE: dict[str, list[str]] = {}


async def _web_search_for_blog(topic: str, media: str, year: int) -> str:
    """Run a web search for the blog topic and return a text block that can
    be injected into the AI prompt as extra grounding context."""
    if media == "tv":
        queries = [
            f"best TV series {year} top rated",
            f"найкращі серіали {year} топ",
        ]
    else:
        queries = [
            f"best movies {year} top rated",
            f"найкращі фільми {year} топ",
        ]
    cache_key = f"{media}:{year}"
    if cache_key in _WEB_SEARCH_CACHE:
        snippets = _WEB_SEARCH_CACHE[cache_key]
    else:
        snippets = []
        for q in queries:
            snippets.extend(await _web_search_top_titles(q))
        _WEB_SEARCH_CACHE[cache_key] = snippets
    if not snippets:
        return ""
    block = (
        "\n\nДОДАТКОВИЙ КОНТЕКСТ З ІНТЕРНЕТУ:\n"
        f"Популярні {'серіали' if media == 'tv' else 'фільми'} {year} за веб-джерелами:\n"
        + "\n".join(f"  — {s[:200]}" for s in snippets[:6])
    )
    return block[:1200]


async def _tmdb_discover_for_blog(media: str, year: int, count: int = 15,
                                  region: str = "") -> list[dict]:
    """Return a list of top-rated films/series from a specific year via
    TMDB's /discover/{media} endpoint.

    Used to ground the AI-blog prompt in REAL data when the user asks for
    "топ 2025 року" or similar — the AI's training-cutoff might be 2023, so
    we hand it the actual list of 2025 releases with ratings instead of
    hoping it makes up reasonable ones.

    Films are ranked by a weighted Bayesian score that accounts for both
    rating AND vote count — a 9.9-rated film with 5 votes will rank below
    an 8.2-rated film with 5000 votes.

    Cached per (media, year, count, region) for the lifetime of the process.
    Returns [] on any failure (no TMDB key, network error, no results).
    """
    if not TMDB_API_KEY:
        return []
    media = (media or "").lower().strip()
    if media not in ("movie", "tv"):
        return []
    try:
        year = int(year)
    except Exception:
        return []
    cache_key = (media, year, count, region or "")
    if cache_key in _TMDB_DISCOVER_CACHE:
        return _TMDB_DISCOVER_CACHE[cache_key]
    try:
        all_results: list[dict] = []
        async with httpx.AsyncClient(timeout=10) as client:
            # Strategy 1: high vote count, sorted by vote_average
            params_quality: dict = {
                "language": "uk-UA",
                "include_adult": "false",
                "sort_by": "vote_average.desc",
                "vote_count.gte": "500",
                "page": "1",
            }
            if media == "movie":
                params_quality["primary_release_year"] = str(year)
                params_quality["with_runtime.gte"] = "60"
            else:
                params_quality["first_air_date_year"] = str(year)
            if region:
                params_quality["with_origin_country"] = region
            r1 = await client.get(
                f"https://api.themoviedb.org/3/discover/{media}",
                params=_tmdb_params(params_quality),
                headers=_tmdb_headers(),
            )
            if r1.status_code == 200:
                all_results.extend((r1.json() or {}).get("results") or [])

            # Strategy 2: popularity-based (catches trending/hyped films)
            params_pop: dict = {
                "language": "uk-UA",
                "include_adult": "false",
                "sort_by": "popularity.desc",
                "vote_count.gte": "100",
                "page": "1",
            }
            if media == "movie":
                params_pop["primary_release_year"] = str(year)
                params_pop["with_runtime.gte"] = "60"
            else:
                params_pop["first_air_date_year"] = str(year)
            if region:
                params_pop["with_origin_country"] = region
            r2 = await client.get(
                f"https://api.themoviedb.org/3/discover/{media}",
                params=_tmdb_params(params_pop),
                headers=_tmdb_headers(),
            )
            if r2.status_code == 200:
                all_results.extend((r2.json() or {}).get("results") or [])

            # Strategy 3: lower bar if still too few
            if len(all_results) < 8:
                params_fallback = dict(params_pop)
                params_fallback.pop("vote_count.gte", None)
                r3 = await client.get(
                    f"https://api.themoviedb.org/3/discover/{media}",
                    params=_tmdb_params(params_fallback),
                    headers=_tmdb_headers(),
                )
                if r3.status_code == 200:
                    all_results.extend((r3.json() or {}).get("results") or [])

        # Deduplicate by TMDB id
        seen_ids: set[int] = set()
        unique: list[dict] = []
        title_key = "title" if media == "movie" else "name"
        date_key = "release_date" if media == "movie" else "first_air_date"
        for top in all_results:
            tid = top.get("id")
            if not tid or tid in seen_ids:
                continue
            tk = top.get(title_key)
            if not tk:
                continue
            rel = (top.get(date_key) or "")[:4]
            if rel and rel != str(year):
                continue
            seen_ids.add(tid)
            unique.append(top)

        # Score by weighted Bayesian rating
        scored: list[tuple[float, dict]] = []
        for top in unique:
            va = float(top.get("vote_average") or 0)
            vc = int(top.get("vote_count") or 0)
            score = _weighted_rating(va, vc)
            scored.append((score, top))
        scored.sort(key=lambda x: x[0], reverse=True)

        out: list[dict] = []
        for _score, top in scored[:count]:
            tk = top.get(title_key)
            rel = (top.get(date_key) or "")[:4]
            vc = int(top.get("vote_count") or 0)
            out.append({
                "media": media,
                "tmdb_id": int(top.get("id") or 0),
                "title": tk,
                "original_title": top.get("original_" + title_key) or tk,
                "year": rel or str(year),
                "rating": round(float(top.get("vote_average") or 0), 1),
                "vote_count": vc,
                "overview": (top.get("overview") or "")[:280],
            })
        _TMDB_DISCOVER_CACHE[cache_key] = out
        return out
    except Exception:
        _TMDB_DISCOVER_CACHE[cache_key] = []
        return []


async def _enrich_blog_content_with_links(content: str) -> tuple[str, list[dict]]:
    """Replace `[[MOVIE:Title (Year)]]` / `[[TV:Title]]` markers in *content*
    with `<a href="/descmovie/{id}" ...>Title</a>` (or `/desctv/{id}`).

    Returns `(rewritten_content, mentions)` where `mentions` is a deduplicated
    list of resolved film/series info dicts (for rendering the "У статті
    згадуються" section).  Markers that don't resolve are stripped — the
    title text remains in the article, just without a link.
    """
    if not content:
        return content or "", []
    matches = list(_BLOG_MARKER_RE.finditer(content))
    if not matches:
        return content, []
    seen_keys: set[tuple] = set()
    mentions: list[dict] = []
    # Process matches sequentially so the cache helps and we don't fire 20
    # parallel TMDB requests from a single blog publish.
    replacements: list[tuple[int, int, str]] = []
    for m in matches:
        media = m.group(1).lower()
        title_raw = m.group(2).strip()
        info = await _tmdb_lookup_for_blog(media, title_raw)
        if info:
            key = (info["media"], info["tmdb_id"])
            if key not in seen_keys:
                seen_keys.add(key)
                mentions.append(info)
            href = f"/descmovie/{info['tmdb_id']}" if media == "movie" else f"/desctv/{info['tmdb_id']}"
            display_title = title_raw
            # Strip the trailing "(YYYY)" from the linked text since it looks
            # cleaner inline; the year is still on the card section.
            display_title = _re_blog.sub(r"\s*\(\d{4}\)\s*$", "", display_title)
            link = (
                f'<a href="{href}" class="picksy-film-link" data-tmdb="{info["tmdb_id"]}" '
                f'data-media="{media}" title="{html.escape(info.get("title") or display_title)}">'
                f'{html.escape(display_title)}</a>'
            )
            replacements.append((m.start(), m.end(), link))
        else:
            # No TMDB match — strip the marker and leave the plain title
            display_title = _re_blog.sub(r"\s*\(\d{4}\)\s*$", "", title_raw)
            replacements.append((m.start(), m.end(), html.escape(display_title)))
    # Apply right-to-left so earlier offsets stay valid
    out = content
    for start, end, repl in sorted(replacements, key=lambda r: -r[0]):
        out = out[:start] + repl + out[end:]
    return out, mentions


def _render_mentions_section(mentions: list[dict]) -> str:
    """Render the "У статті згадуються" HTML block with film/series cards.
    Empty string if no mentions resolved.
    """
    if not mentions:
        return ""
    cards = []
    for m in mentions[:20]:
        href = f"/descmovie/{m['tmdb_id']}" if m["media"] == "movie" else f"/desctv/{m['tmdb_id']}"
        poster = m.get("poster") or ""
        rating = m.get("rating")
        year = m.get("year") or ""
        genres = m.get("genres") or ""
        media_label = "Фільм" if m["media"] == "movie" else "Серіал"
        rating_html = (
            f'<span class="pfc-rating">★ {rating:.1f}</span>'
            if rating else ''
        )
        meta_bits = []
        if year:
            meta_bits.append(year)
        if genres:
            meta_bits.append(genres.split(",")[0].strip())
        meta_line = " · ".join(meta_bits)
        poster_html = (
            f'<img src="{html.escape(poster)}" alt="{html.escape(m["title"])}" loading="lazy" decoding="async">'
            if poster else '<div class="pfc-no-poster">🎬</div>'
        )
        cards.append(
            f'<a class="picksy-film-card" href="{href}">'
            f'<div class="pfc-poster">{poster_html}{rating_html}</div>'
            f'<div class="pfc-body">'
            f'<div class="pfc-media">{media_label}</div>'
            f'<div class="pfc-title">{html.escape(m["title"])}</div>'
            f'<div class="pfc-meta">{html.escape(meta_line)}</div>'
            f'</div></a>'
        )
    return (
        '<section class="picksy-mentions">'
        '<h2>🎬 У статті згадуються</h2>'
        '<div class="picksy-mentions-grid">'
        + "".join(cards) +
        '</div></section>'
    )


_BLOG_TABLE_READY = False


def _ensure_blog_table(cur) -> None:
    """Create the blog_posts table on demand. The TABLES dict registers the
    same DDL at boot, but on some legacy deployments the migration never
    ran (the box was upgraded in-place without restarting the API), which
    used to surface as a bare 500 from every admin/blog endpoint. Running
    a CREATE TABLE IF NOT EXISTS here is cheap and makes the panel self-
    healing for editors. We memoise the result so we don't pay for the
    ALTERs on every list request."""
    global _BLOG_TABLE_READY
    if _BLOG_TABLE_READY:
        return
    try:
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS blog_posts (
                id               INT AUTO_INCREMENT PRIMARY KEY,
                title            VARCHAR(255)  NOT NULL,
                slug             VARCHAR(255)  NOT NULL UNIQUE,
                content          LONGTEXT      NOT NULL,
                excerpt          TEXT,
                cover_image      VARCHAR(500),
                tags             VARCHAR(500)  DEFAULT '',
                content_type     VARCHAR(20)   DEFAULT 'general',
                author_id        INT           DEFAULT NULL,
                is_published     TINYINT(1)    DEFAULT 0,
                is_ai_generated  TINYINT(1)    DEFAULT 0,
                meta_title       VARCHAR(255),
                meta_description VARCHAR(320),
                meta_keywords    VARCHAR(500),
                og_image         VARCHAR(500),
                views            INT           DEFAULT 0,
                created_at       DATETIME      DEFAULT CURRENT_TIMESTAMP,
                updated_at       DATETIME      DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                INDEX idx_slug (slug),
                INDEX idx_published (is_published, created_at)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
            """
        )
    except Exception:
        # Don't block the request if the user is missing CREATE privs; the
        # real query will surface its own error to the client.
        pass
    # Backfill columns that older deployments may be missing. Each ADD is
    # wrapped in its own try/except so one missing column doesn't stop the
    # rest. Order matters: we put the "must have" columns first because if
    # `content` is missing, every single INSERT / SELECT on the table is a
    # 1054 (Unknown column). The legacy-blog table on picksy.my prod was
    # observed with literally no `content`, `slug`, or `title` column —
    # this list rebuilds the schema in place without losing existing rows.
    legacy_cols = [
        ("title", "VARCHAR(255) NOT NULL DEFAULT ''"),
        ("slug", "VARCHAR(255) NOT NULL DEFAULT ''"),
        ("content", "LONGTEXT"),
        ("author_id", "INT DEFAULT NULL"),
        ("og_image", "VARCHAR(500)"),
        ("meta_keywords", "VARCHAR(500)"),
        ("meta_description", "VARCHAR(320)"),
        ("meta_title", "VARCHAR(255)"),
        ("is_ai_generated", "TINYINT(1) DEFAULT 0"),
        ("is_published", "TINYINT(1) DEFAULT 0"),
        ("views", "INT DEFAULT 0"),
        ("tags", "VARCHAR(500) DEFAULT ''"),
        ("content_type", "VARCHAR(20) DEFAULT 'general'"),
        ("excerpt", "TEXT"),
        ("cover_image", "VARCHAR(500)"),
        ("created_at", "DATETIME DEFAULT CURRENT_TIMESTAMP"),
        ("updated_at", "DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP"),
    ]
    # Try the modern "IF NOT EXISTS" form first; if the server is too old
    # to understand it (MariaDB <10.2 / MySQL <8.0.16) fall back to an
    # INFORMATION_SCHEMA pre-check.
    def _column_exists(name: str) -> bool:
        try:
            cur.execute(
                "SELECT 1 FROM information_schema.COLUMNS "
                "WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'blog_posts' "
                "AND COLUMN_NAME = %s LIMIT 1",
                (name,)
            )
            return cur.fetchone() is not None
        except Exception:
            return True  # be conservative — assume present so we don't double-add
    for col, ddl in legacy_cols:
        added = False
        try:
            cur.execute(f"ALTER TABLE blog_posts ADD COLUMN IF NOT EXISTS {col} {ddl}")
            added = True
        except Exception:
            pass
        if not added and not _column_exists(col):
            try:
                cur.execute(f"ALTER TABLE blog_posts ADD COLUMN {col} {ddl}")
            except Exception:
                pass
    _BLOG_TABLE_READY = True


@app.get("/api/admin/blog")
async def admin_blog_list(
    page: int = 1,
    per_page: int = 20,
    search: Optional[str] = None,
    user=Depends(get_current_user)
):
    if not _is_blog_editor(user):
        raise HTTPException(status_code=403, detail="Access denied")
    per_page = max(1, min(per_page, 100))
    offset = (max(1, page) - 1) * per_page
    conn = get_db()
    try:
        with conn.cursor() as cur:
            _ensure_blog_table(cur)
            if search:
                like = f"%{search}%"
                cur.execute(
                    "SELECT COUNT(*) AS c FROM blog_posts WHERE title LIKE %s OR tags LIKE %s",
                    (like, like)
                )
                total = (cur.fetchone() or {}).get('c', 0)
                cur.execute(
                    "SELECT id,title,slug,tags,is_published,is_ai_generated,views,created_at "
                    "FROM blog_posts WHERE title LIKE %s OR tags LIKE %s "
                    "ORDER BY created_at DESC LIMIT %s OFFSET %s",
                    (like, like, per_page, offset)
                )
            else:
                cur.execute("SELECT COUNT(*) AS c FROM blog_posts")
                total = (cur.fetchone() or {}).get('c', 0)
                cur.execute(
                    "SELECT id,title,slug,tags,is_published,is_ai_generated,views,created_at "
                    "FROM blog_posts ORDER BY created_at DESC LIMIT %s OFFSET %s",
                    (per_page, offset)
                )
            rows = cur.fetchall() or []
    except HTTPException:
        raise
    except Exception as e:
        import traceback as _tb
        _tb.print_exc()
        raise HTTPException(status_code=500, detail=f"Blog list failed: {type(e).__name__}: {e}")
    finally:
        try: conn.close()
        except Exception: pass
    return {
        "posts": [_blog_row_to_dict(r) for r in rows],
        "total": total,
        "page": page,
        "per_page": per_page,
        "total_pages": max(1, (total + per_page - 1) // per_page),
    }


@app.post("/api/admin/blog")
async def admin_blog_create(body: BlogPostCreate, user=Depends(get_current_user)):
    if not _is_blog_editor(user):
        raise HTTPException(status_code=403, detail="Access denied")
    title = (body.title or '').strip()
    if not title:
        raise HTTPException(status_code=400, detail="Title is required")
    content = body.content or ''
    if not content.strip():
        raise HTTPException(status_code=400, detail="Content is required")
    # Hard-cap lengths to the column widths so MySQL never throws 1406
    # ("Data too long"). Anything over the limit gets truncated rather than
    # silently rejected with a 500.
    def _clip(s, n):
        return (s or '')[:n] if s else s
    meta_title = _clip(body.meta_title, 255)
    meta_description = _clip(body.meta_description, 320)
    meta_keywords = _clip(body.meta_keywords, 500)
    cover_image = _clip(body.cover_image, 500)
    og_image = _clip(body.og_image, 500)
    tags = _clip(body.tags or '', 500)
    title = title[:255]
    excerpt = body.excerpt  # TEXT, no hard limit

    # Resolve [[MOVIE:...]] / [[TV:...]] markers via TMDB → inline links. Best
    # effort: if the post has no markers (or TMDB is offline) this is a no-op.
    try:
        content, _mentions = await _enrich_blog_content_with_links(content)
    except Exception:
        pass

    base_slug = _generate_slug(title)
    slug = _unique_slug(base_slug)
    conn = get_db()
    try:
        with conn.cursor() as cur:
            _ensure_blog_table(cur)
            content_type = (body.content_type or 'general').strip()[:20]
            if content_type not in ('movies', 'tv', 'books', 'mixed', 'general'):
                content_type = 'general'
            cur.execute(
                "INSERT INTO blog_posts (title,slug,content,excerpt,cover_image,tags,content_type,author_id,"
                "is_published,is_ai_generated,meta_title,meta_description,meta_keywords,og_image) "
                "VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)",
                (
                    title, slug, content, excerpt, cover_image,
                    tags, content_type, user.get('id'),
                    int(bool(body.is_published)), int(bool(body.is_ai_generated)),
                    meta_title, meta_description, meta_keywords, og_image
                )
            )
            conn.commit()
            new_id = cur.lastrowid
            cur.execute("SELECT * FROM blog_posts WHERE id=%s LIMIT 1", (new_id,))
            row = cur.fetchone()
    except HTTPException:
        raise
    except Exception as e:
        import traceback as _tb
        _tb.print_exc()
        raise HTTPException(status_code=500, detail=f"Blog create failed: {type(e).__name__}: {e}")
    finally:
        try: conn.close()
        except Exception: pass
    return _blog_row_to_dict(row)


@app.put("/api/admin/blog/{post_id}")
async def admin_blog_update(post_id: int, body: BlogPostUpdate, user=Depends(get_current_user)):
    if not _is_blog_editor(user):
        raise HTTPException(status_code=403, detail="Access denied")
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT * FROM blog_posts WHERE id=%s LIMIT 1", (post_id,))
            existing = cur.fetchone()
    finally:
        conn.close()
    if not existing:
        raise HTTPException(status_code=404, detail="Post not found")
    fields = []
    values = []
    data = body.dict(exclude_none=True)
    if 'title' in data:
        new_slug = _unique_slug(_generate_slug(data['title']), exclude_id=post_id)
        fields.append("slug=%s")
        values.append(new_slug)
    # If content is being updated, re-run the TMDB enrichment so newly added
    # [[MOVIE:...]] markers from the editor get resolved into anchors before
    # we persist. We don't touch existing already-resolved <a> tags, so
    # repeated saves don't keep re-rewriting the same content.
    if 'content' in data and isinstance(data['content'], str):
        try:
            data['content'], _ = await _enrich_blog_content_with_links(data['content'])
        except Exception:
            pass
    for k, v in data.items():
        fields.append(f"{k}=%s")
        values.append(v)
    if not fields:
        return _blog_row_to_dict(existing)
    values.append(post_id)
    conn2 = get_db()
    try:
        with conn2.cursor() as cur:
            cur.execute(f"UPDATE blog_posts SET {','.join(fields)},updated_at=NOW() WHERE id=%s", values)
            conn2.commit()
            cur.execute("SELECT * FROM blog_posts WHERE id=%s LIMIT 1", (post_id,))
            row = cur.fetchone()
    finally:
        conn2.close()
    return _blog_row_to_dict(row)


@app.delete("/api/admin/blog/{post_id}")
async def admin_blog_delete(post_id: int, user=Depends(get_current_user)):
    if not _is_blog_editor(user):
        raise HTTPException(status_code=403, detail="Access denied")
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute("DELETE FROM blog_posts WHERE id=%s", (post_id,))
            conn.commit()
    finally:
        conn.close()
    return {"success": True}


@app.post("/api/admin/blog/generate-ai")
async def admin_blog_generate_ai(body: BlogAIGenerateRequest, user=Depends(get_current_user)):
    if not _is_blog_editor(user):
        raise HTTPException(status_code=403, detail="Access denied")
    if not AI_API_KEY:
        raise HTTPException(status_code=503, detail="AI API key not configured")
    lang_name = "українською мовою" if body.language == 'uk' else "in English"
    tone_map = {'engaging': 'захопливим і цікавим', 'professional': 'професійним', 'casual': 'розслабленим і дружнім'}
    tone_desc = tone_map.get(body.tone, 'захопливим')

    from datetime import datetime as _dt
    now = _dt.utcnow()
    current_year = now.year
    current_date = now.strftime("%Y-%m-%d")

    # Detect explicit year references in the topic (e.g. "топ 2025", "best films
    # of 2024") so we can ground the AI in REAL TMDB data for that year. Most
    # LLMs have a training cutoff in 2023 — without this they'll happily call
    # 2023 films "2025 releases".
    topic_text = body.topic or ""
    year_matches = _re_blog.findall(r"\b(20\d{2})\b", topic_text)
    target_years: list[int] = []
    for ym in year_matches:
        try:
            y = int(ym)
            if 1980 <= y <= current_year + 2 and y not in target_years:
                target_years.append(y)
        except Exception:
            pass

    # Detect content type from topic
    discover_block = ""
    web_block = ""
    is_tv_topic = bool(_re_blog.search(r"серіал|series|tv\b|шоу|show", topic_text, _re_blog.IGNORECASE))
    is_movie_topic = bool(_re_blog.search(r"фільм|movie|film|кіно|cinema", topic_text, _re_blog.IGNORECASE))
    is_book_topic = bool(_re_blog.search(r"книг|book|роман|novel|читати", topic_text, _re_blog.IGNORECASE))

    if is_tv_topic and not is_movie_topic:
        auto_content_type = "tv"
    elif is_movie_topic and not is_tv_topic:
        auto_content_type = "movies"
    elif is_book_topic:
        auto_content_type = "books"
    elif is_movie_topic and is_tv_topic:
        auto_content_type = "mixed"
    else:
        auto_content_type = "general"

    media_to_fetch = "tv" if is_tv_topic else "movie"

    # If no year mentioned but topic is about movies/tv, use current year
    if not target_years and (is_movie_topic or is_tv_topic):
        target_years = [current_year]

    if target_years:
        discover_lines: list[str] = []
        for y in target_years[:2]:
            items = await _tmdb_discover_for_blog(media_to_fetch, y, count=15)
            if items:
                discover_lines.append(f"\n— Реальні {'серіали' if media_to_fetch == 'tv' else 'фільми'} {y} року (TMDB, за рейтингом):")
                for it in items[:10]:
                    marker = "TV" if media_to_fetch == "tv" else "MOVIE"
                    if marker == "MOVIE":
                        ref = f"[[MOVIE:{it['original_title']} ({it['year']})]]"
                    else:
                        ref = f"[[TV:{it['original_title']}]]"
                    discover_lines.append(
                        f"  • {ref} — ★{it['rating']:.1f} ({it['vote_count']} відг.) {it['overview'][:80]}"
                    )
        if discover_lines:
            discover_block = (
                "\n\nГРАУНДИНГ (TMDB):\n"
                "Використовуй фільми з цього списку. Фільм з малою кількістю відгуків — НЕ топ."
                + "".join(discover_lines)
            )

        # Web search grounding — supplement TMDB with real web sources
        web_block = ""
        for y in target_years[:2]:
            wb = await _web_search_for_blog(topic_text, media_to_fetch, y)
            if wb:
                web_block += wb

    movie_only_instruction = ""
    if is_movie_topic and not is_tv_topic:
        movie_only_instruction = """
ВАЖЛИВО — ТІЛЬКИ ФІЛЬМИ:
- Тема стосується ФІЛЬМІВ. НЕ включай мультфільми, анімацію, аніме — тільки ігрові (live-action) фільми.
- Кожен фільм ОБОВ'ЯЗКОВО повинен мати короткий опис сюжету (1-2 речення).
- Використовуй тільки фільми з високим рейтингом (7.0+ на TMDB/IMDb), підтверджені реальні фільми.
- Для кожного фільму вкажи: назву (з маркером), рік, рейтинг, короткий опис.
"""

    tv_only_instruction = ""
    if is_tv_topic and not is_movie_topic:
        tv_only_instruction = """
ВАЖЛИВО — ТІЛЬКИ СЕРІАЛИ:
- Тема стосується СЕРІАЛІВ. НЕ включай фільми — тільки серіали/шоу.
- Кожен серіал ОБОВ'ЯЗКОВО повинен мати короткий опис сюжету (1-2 речення).
- Використовуй тільки серіали з високим рейтингом, підтверджені реальні серіали.
"""

    prompt = f"""Ти — досвідчений блогер кіно-сайту Picksy. Сьогодні {current_date} (поточний рік: {current_year}).
Напиши розгорнутий блог-пост {lang_name} на тему: "{body.topic}".
Стиль тексту: {tone_desc}.

ВАЖЛИВО — точність дат і фактів:
- Поточний рік — {current_year}. НЕ плутай роки виходу фільмів. Якщо ти не впевнений у році релізу — НЕ вигадуй, використовуй лише фільми зі списку нижче (якщо він є).
- НЕ називай 2023 рік "новим" або "цьогорічним" — це {current_year} рік.
- Використовуй ТІЛЬКИ реальні, підтверджені фільми/серіали з високим рейтингом.
- РЕЙТИНГ + КІЛЬКІСТЬ ВІДГУКІВ: фільм вважається топовим лише якщо має ВИСОКИЙ рейтинг (7.0+) І ВЕЛИКУ кількість відгуків (500+). Фільм з рейтингом 9.9 але лише 1-10 відгуками — це НЕ топ, це маловідомий фільм. Обирай фільми, які дійсно популярні і визнані масовою аудиторією.
{movie_only_instruction}{tv_only_instruction}
ВАЖЛИВО — формат контенту:
- Для КОЖНОГО фільму/серіалу обов'язково додай короткий опис сюжету (1-2 речення).
- Формат кожного пункту: назва з маркером, рік, рейтинг, та 1-2 речення опису сюжету.
- Контент повинен бути структурований з <h2>, <h3>, <p>, <ul>, <li> тегами.

ВАЖЛИВО — посилання на фільми/серіали:
- Кожного разу, коли в тексті згадується конкретний ФІЛЬМ, обов'язково обгорни його назву маркером [[MOVIE:Точна англійська назва (Рік)]]. Приклад: [[MOVIE:Inception (2010)]].
- Кожного разу, коли в тексті згадується конкретний СЕРІАЛ, обгорни його маркером [[TV:Точна англійська назва]]. Приклад: [[TV:Breaking Bad]].
- НЕ використовуй маркери для книг, режисерів, акторів — лише для фільмів та серіалів.
- Використовуй ОРИГІНАЛЬНУ (англійську) назву всередині маркера — це для TMDB. Українську адаптацію можна дати поряд у дужках.
- Згадай мінімум 8-12 конкретних фільмів/серіалів з маркерами.{discover_block}{web_block}

Поверни ТІЛЬКИ валідний JSON без жодного додаткового тексту. УСІ переноси рядків та лапки всередині строкових значень мають бути екрановані (\\n, \\\"). Формат:
{{
  "title": "заголовок поста (до 80 символів)",
  "content": "повний HTML контент поста мінімум 800 слів з тегами <h2>, <p>, <ul>, <li> та з маркерами [[MOVIE:...]] / [[TV:...]] навколо назв. Кожен фільм/серіал з коротким описом сюжету.",
  "excerpt": "короткий опис 2-3 речення без HTML тегів та без маркерів",
  "tags": "тег1, тег2, тег3, тег4",
  "content_type": "{auto_content_type}",
  "meta_title": "SEO заголовок до 60 символів",
  "meta_description": "SEO опис до 160 символів, що спонукає до кліку",
  "meta_keywords": "ключове слово 1, ключове слово 2, ключове слово 3, ключове слово 4, ключове слово 5"
}}"""
    # Safety: truncate prompt if too long for the model context window.
    # Groq llama-3.1-8b has ~8k token limit (~24k chars). Keep prompt
    # under ~20k chars to leave room for the response (4096 tokens).
    if len(prompt) > 18000:
        prompt = prompt[:18000] + "\n...(скорочено)\n}}"
    try:
        async with httpx.AsyncClient(timeout=60) as client:
            resp = await client.post(
                f"{AI_BASE_URL.rstrip('/')}/chat/completions",
                headers={"Authorization": f"Bearer {AI_API_KEY}", "Content-Type": "application/json"},
                json={
                    "model": AI_MODEL,
                    "messages": [{"role": "user", "content": prompt}],
                    "temperature": 0.7,
                    "max_tokens": 4096,
                }
            )
        # Translate the most common upstream errors into something the admin
        # toast can show without raising a generic "AI generation failed".
        if resp.status_code == 429:
            retry_after = resp.headers.get('retry-after') or resp.headers.get('Retry-After') or ''
            wait = f" (спробуй через {retry_after}с)" if retry_after else ''
            raise HTTPException(status_code=429, detail=(
                "Досягнуто ліміт запитів до AI-провайдера (Groq/OpenAI). Зачекай "
                "хвилину та спробуй знову, або заповни пост вручну" + wait
            ))
        if resp.status_code in (401, 403):
            raise HTTPException(status_code=502, detail="AI-провайдер відхилив API-ключ (перевір AI_API_KEY)")
        if resp.status_code >= 500:
            raise HTTPException(status_code=502, detail=f"AI-сервер недоступний ({resp.status_code}). Спробуй знову через хвилину")
        resp.raise_for_status()
        resp_data = resp.json()
        choices = resp_data.get('choices') or []
        if not choices:
            raise HTTPException(status_code=502, detail="AI повернув порожню відповідь (немає choices). Спробуй ще раз")
        raw = (choices[0].get('message', {}).get('content') or '').strip()
        if not raw:
            raise HTTPException(status_code=502, detail="AI повернув порожній контент. Спробуй ще раз або спрости тему")
        # Some models wrap the JSON in ```json ... ``` fences; strip them.
        if raw.startswith('```'):
            raw = raw.split('\n', 1)[-1].rsplit('```', 1)[0].strip()
        start = raw.find('{')
        end = raw.rfind('}')
        if start != -1 and end != -1:
            raw = raw[start:end+1]
        if not raw:
            raise HTTPException(status_code=502, detail="AI не повернув JSON-об'єкт. Спробуй ще раз")
        result = _parse_loose_json(raw)
        for field in ('title','content','excerpt','tags','meta_title','meta_description','meta_keywords'):
            if field not in result:
                result[field] = ''
        if 'content_type' not in result or result['content_type'] not in ('movies','tv','books','mixed','general'):
            result['content_type'] = auto_content_type
        return result
    except json.JSONDecodeError as e:
        raise HTTPException(status_code=502, detail=f"AI повернув невалідний JSON: {str(e)}")
    except HTTPException:
        raise
    except httpx.TimeoutException:
        raise HTTPException(status_code=504, detail="AI-сервер відповідав занадто довго (timeout). Спробуй ще раз")
    except Exception as e:
        raise HTTPException(status_code=502, detail=f"AI generation failed: {str(e)}")


