@app.get("/sitemap.xml")
async def sitemap_xml():
    today = today_kyiv().isoformat()
    urls = [
        {"loc": "/", "priority": "1.0", "changefreq": "daily"},
        {"loc": "/wordle", "priority": "0.9", "changefreq": "daily"},
        {"loc": "/quiz", "priority": "0.9", "changefreq": "weekly"},
        {"loc": "/archetype/all", "priority": "0.8", "changefreq": "monthly"},
        {"loc": "/faq", "priority": "0.8", "changefreq": "monthly"},
        {"loc": "/explore", "priority": "0.8", "changefreq": "weekly"},
        {"loc": "/privacy", "priority": "0.3", "changefreq": "yearly"},
        {"loc": "/match", "priority": "0.85", "changefreq": "weekly"},
        {"loc": "/blog", "priority": "0.85", "changefreq": "daily"},
        {"loc": "/quizzes", "priority": "0.82", "changefreq": "weekly"},
        {"loc": "/tracker", "priority": "0.75", "changefreq": "weekly"},
        {"loc": "/notes", "priority": "0.65", "changefreq": "weekly"},
        {"loc": "/watchlist", "priority": "0.75", "changefreq": "weekly"},
        {"loc": "/collections", "priority": "0.75", "changefreq": "weekly"},
        {"loc": "/profile", "priority": "0.5", "changefreq": "weekly"},
        {"loc": "/humans.txt", "priority": "0.3", "changefreq": "monthly"},
        {"loc": "/llms.txt", "priority": "0.5", "changefreq": "monthly"},
        {"loc": "/llms-full.txt", "priority": "0.5", "changefreq": "monthly"},
    ]

    # Add 16 archetype URLs (cinema-archetype quiz funnel)
    _archs_data = []
    try:
        _arch_path = os.path.join(os.path.dirname(__file__), "..", "frontend", "data", "archetypes.json")
        if os.path.exists(_arch_path):
            with open(_arch_path, "r", encoding="utf-8") as f:
                _archs_data = (json.load(f) or {}).get("archetypes", []) or []
    except Exception:
        _archs_data = []
    for a in _archs_data:
        s = a.get("slug")
        if s:
            urls.append({"loc": f"/archetype/{s}", "priority": "0.7", "changefreq": "monthly"})

    # Add public user-profile URLs (top by saved count, recently active),
    # so search engines can discover @profile pages.  Bounded to 500 to keep
    # the sitemap reasonable; large sites would chunk into sitemap indexes.
    try:
        if get_site_settings().get("public_profiles_enabled", True):
            conn = get_db()
            with conn.cursor() as cur:
                cur.execute(
                    "SELECT username FROM users "
                    "WHERE username IS NOT NULL AND username <> '' "
                    "  AND COALESCE(is_banned, 0) = 0 "
                    "ORDER BY COALESCE(updated_at, created_at) DESC "
                    "LIMIT 500"
                )
                rows = cur.fetchall() or []
            conn.close()
            for r in rows:
                uname = (r.get("username") or "").strip()
                if uname:
                    urls.append({
                        "loc": f"/u/{uname}",
                        "priority": "0.6",
                        "changefreq": "weekly",
                    })
    except Exception:
        pass

    # Add trending movie/TV detail pages to sitemap (only /descmovie, /desctv —
    # share cards /movie, /tv are noindex and canonical→desc, so excluded).
    if TMDB_API_KEY:
        try:
            async with httpx.AsyncClient(timeout=10) as client:
                for media in ("movie", "tv"):
                    desc_prefix = "descmovie" if media == "movie" else "desctv"
                    params = {"language": "uk", "page": 1}
                    hdrs = {}
                    if TMDB_IS_BEARER:
                        hdrs["Authorization"] = f"Bearer {TMDB_API_KEY}"
                    else:
                        params["api_key"] = TMDB_API_KEY
                    # Trending this week
                    r = await client.get(
                        f"https://api.themoviedb.org/3/trending/{media}/week",
                        params=params, headers=hdrs,
                    )
                    if r.status_code == 200:
                        for item in r.json().get("results", [])[:20]:
                            tmdb_id = item.get("id")
                            if tmdb_id:
                                urls.append({
                                    "loc": f"/{desc_prefix}/{tmdb_id}",
                                    "priority": "0.7",
                                    "changefreq": "weekly",
                                })
                    # Popular (additional coverage)
                    r2 = await client.get(
                        f"https://api.themoviedb.org/3/{media}/popular",
                        params=params, headers=hdrs,
                    )
                    if r2.status_code == 200:
                        for item in r2.json().get("results", [])[:20]:
                            tmdb_id = item.get("id")
                            if tmdb_id:
                                loc_desc = f"/{desc_prefix}/{tmdb_id}"
                                if not any(u["loc"] == loc_desc for u in urls):
                                    urls.append({"loc": loc_desc, "priority": "0.7", "changefreq": "weekly"})
        except Exception:
            pass

    # Add published blog posts to sitemap
    try:
        conn_blog = get_db()
        with conn_blog.cursor() as cur_blog:
            cur_blog.execute(
                "SELECT slug, updated_at FROM blog_posts WHERE is_published=1 ORDER BY updated_at DESC LIMIT 500"
            )
            blog_rows = cur_blog.fetchall() or []
        conn_blog.close()
        for bp in blog_rows:
            bslug = (bp.get('slug') or '').strip()
            if bslug:
                lastmod = ''
                try:
                    lastmod = bp['updated_at'].strftime('%Y-%m-%d')
                except Exception:
                    lastmod = today
                urls.append({
                    "loc": f"/blog/{bslug}",
                    "priority": "0.7",
                    "changefreq": "weekly",
                    "lastmod": lastmod,
                })
    except Exception:
        pass

    # Pages we want indexed for both Ukrainian and English. The site uses
    # ?lang=en for the English locale, so we emit explicit hreflang alternates
    # for these so Google can pick the right URL per query language.
    bilingual_locs = {
        "/", "/quiz", "/match", "/explore", "/faq", "/wordle",
        "/archetype/all", "/blog", "/llms.txt", "/llms-full.txt",
    }
    entries = ""
    for u in urls:
        loc = u['loc']
        uk_url = f"{SITE_DOMAIN}{loc}"
        if loc in bilingual_locs or loc.startswith("/archetype/"):
            sep = "&" if "?" in loc else "?"
            en_url = f"{SITE_DOMAIN}{loc}{sep}lang=en"
            entries += (
                "  <url>\n"
                f"    <loc>{uk_url}</loc>\n"
                f"    <lastmod>{today}</lastmod>\n"
                f"    <changefreq>{u['changefreq']}</changefreq>\n"
                f"    <priority>{u['priority']}</priority>\n"
                f'    <xhtml:link rel="alternate" hreflang="uk" href="{uk_url}"/>\n'
                f'    <xhtml:link rel="alternate" hreflang="uk-UA" href="{uk_url}"/>\n'
                f'    <xhtml:link rel="alternate" hreflang="en" href="{en_url}"/>\n'
                f'    <xhtml:link rel="alternate" hreflang="en-US" href="{en_url}"/>\n'
                f'    <xhtml:link rel="alternate" hreflang="x-default" href="{uk_url}"/>\n'
                "  </url>\n"
            )
        else:
            lastmod = u.get('lastmod', today)
            entries += (
                "  <url>\n"
                f"    <loc>{uk_url}</loc>\n"
                f"    <lastmod>{lastmod}</lastmod>\n"
                f"    <changefreq>{u['changefreq']}</changefreq>\n"
                f"    <priority>{u['priority']}</priority>\n"
                "  </url>\n"
            )
    xml = (
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"\n'
        '        xmlns:xhtml="http://www.w3.org/1999/xhtml">\n'
        f"{entries}"
        "</urlset>\n"
    )
    return HTMLResponse(xml, media_type="application/xml")


# ─── Bot integration API (read-only tickets + stats for admin web UI) ───
# Note: Daily Pick endpoints already exist on the site (line ~6279 and ~11140)
# and are used by both the website and the Telegram bot.


@app.get("/api/admin/bot/stats")
async def admin_bot_stats(user=Depends(get_current_user)):
    """Bot stats for admin web UI."""
    if not (user.get("is_admin") or user_role_level(user) >= 2):
        raise HTTPException(status_code=403, detail="Admin only")
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT COUNT(*) AS c FROM bot_subscribers WHERE is_banned=0")
            subs = (cur.fetchone() or {}).get("c", 0)
            cur.execute("SELECT COUNT(*) AS c FROM support_tickets WHERE status='open'")
            open_t = (cur.fetchone() or {}).get("c", 0)
            cur.execute("SELECT COUNT(*) AS c FROM support_tickets WHERE status='closed' AND closed_at >= NOW() - INTERVAL 7 DAY")
            closed_week = (cur.fetchone() or {}).get("c", 0)
            cur.execute("SELECT COUNT(*) AS c FROM bot_broadcasts WHERE created_at >= NOW() - INTERVAL 7 DAY")
            bcasts_week = (cur.fetchone() or {}).get("c", 0)
            cur.execute(
                "SELECT topic, COUNT(*) AS c FROM bot_subscriptions WHERE enabled=1 GROUP BY topic"
            )
            topics = {r["topic"]: r["c"] for r in cur.fetchall()}
        conn.close()
    except Exception:
        raise HTTPException(status_code=503, detail="DB unavailable")
    return {
        "subscribers": subs,
        "open_tickets": open_t,
        "closed_tickets_7d": closed_week,
        "broadcasts_7d": bcasts_week,
        "topic_counts": topics,
    }


@app.get("/api/admin/bot/tickets")
async def admin_list_tickets(
    status: str = "open",
    limit: int = 50,
    offset: int = 0,
    user=Depends(get_current_user),
):
    """Read-only ticket list for admin web UI. Replies are sent through the Telegram bot."""
    if not (user.get("is_admin") or user_role_level(user) >= 2):
        raise HTTPException(status_code=403, detail="Admin only")
    status = (status or "open").strip().lower()
    if status not in {"open", "answered", "awaiting_user", "closed", "spam", "all"}:
        status = "open"
    limit = max(1, min(int(limit or 50), 200))
    offset = max(0, int(offset or 0))
    try:
        conn = get_db()
        with conn.cursor() as cur:
            if status == "all":
                cur.execute(
                    "SELECT id, tg_id, tg_username, category, priority, subject, status, "
                    "assigned_admin_tg_id, created_at, updated_at, closed_at "
                    "FROM support_tickets ORDER BY updated_at DESC LIMIT %s OFFSET %s",
                    (limit, offset),
                )
            else:
                cur.execute(
                    "SELECT id, tg_id, tg_username, category, priority, subject, status, "
                    "assigned_admin_tg_id, created_at, updated_at, closed_at "
                    "FROM support_tickets WHERE status=%s ORDER BY updated_at DESC LIMIT %s OFFSET %s",
                    (status, limit, offset),
                )
            rows = cur.fetchall()
        conn.close()
    except Exception:
        raise HTTPException(status_code=503, detail="DB unavailable")
    return {"items": rows, "limit": limit, "offset": offset, "status": status}


@app.get("/api/admin/bot/tickets/{tid}")
async def admin_ticket_detail(tid: int, user=Depends(get_current_user)):
    if not (user.get("is_admin") or user_role_level(user) >= 2):
        raise HTTPException(status_code=403, detail="Admin only")
    try:
        conn = get_db()
        with conn.cursor() as cur:
            cur.execute("SELECT * FROM support_tickets WHERE id=%s", (tid,))
            ticket = cur.fetchone()
            if not ticket:
                conn.close()
                raise HTTPException(status_code=404, detail="Ticket not found")
            cur.execute(
                "SELECT id, author, tg_id, text, file_kind, is_internal_note, created_at "
                "FROM ticket_messages WHERE ticket_id=%s ORDER BY id ASC",
                (tid,),
            )
            messages = cur.fetchall()
        conn.close()
    except HTTPException:
        raise
    except Exception:
        raise HTTPException(status_code=503, detail="DB unavailable")
    return {"ticket": ticket, "messages": messages}


