    def _build_archetype_index_html(host: str = "picksy.my") -> str:
        archs = _load_archetypes()
        tiles = ""
        for a in archs:
            slug = _esc(a.get("slug", ""))
            tiles += (
                f'<a class="archetype-tile" href="/archetype/{slug}" '
                f'style="--archetype-gradient: {_esc(a.get("gradient", ""))}">'
                f'<span class="archetype-tile-emoji" aria-hidden="true">{_esc(a.get("emoji", "🎬"))}</span>'
                f'<span class="archetype-tile-name">{_esc(a.get("name", ""))}</span>'
                f'<span class="archetype-tile-tag">{_esc(a.get("tagline", ""))}</span>'
                "</a>"
            )
        breadcrumbs = json.dumps({
            "@context": "https://schema.org",
            "@type": "BreadcrumbList",
            "itemListElement": [
                {"@type": "ListItem", "position": 1, "name": "Picksy", "item": f"https://{host}/"},
                {"@type": "ListItem", "position": 2, "name": "Quiz", "item": f"https://{host}/quiz"},
                {"@type": "ListItem", "position": 3, "name": "Архетипи", "item": f"https://{host}/archetype/all"},
            ],
        }, ensure_ascii=False)
        item_list = json.dumps({
            "@context": "https://schema.org",
            "@type": "ItemList",
            "name": "16 кіноархетипів Picksy",
            "itemListElement": [
                {
                    "@type": "ListItem",
                    "position": i + 1,
                    "url": f"https://{host}/archetype/{a.get('slug', '')}",
                    "name": a.get("name", ""),
                }
                for i, a in enumerate(archs)
            ],
        }, ensure_ascii=False)
